/* -------- Google API helpers (hoisted at top to avoid any ReferenceError) -------- */

/* Build tag (helps verify which Worker is deployed) */
const FLUXIDI_BUILD = 'v36-2026-04-27-white-label-communication';
const BUILD_TAG = FLUXIDI_BUILD;

function buildScopedGoogleCalendarAuthKey(scope = null) {
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  if (!tenantId || !companyId) return null;
  return `tenant:${tenantId}:company:${companyId}:google_calendar_auth:v1`;
}

function hasExplicitCalendarTenantScope(scope = null) {
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  if (!tenantId || !companyId) return false;
  const resolutionMode = safeStr(
    scope?.tenant_resolution_mode ?? scope?.tenantResolutionMode,
    64,
  ).toLowerCase();
  if (resolutionMode === "legacy_fallback") return false;
  if (scope?.legacy_fallback === true || scope?.legacyFallback === true) return false;
  return true;
}

function shouldAllowGlobalGoogleCalendarFallback(env, scope = null) {
  if (!hasExplicitCalendarTenantScope(scope)) return true;

  const explicitAllowToggle = safeStr(
    env?.CALENDAR_ALLOW_GLOBAL_FALLBACK_FOR_SCOPED_TENANTS,
    24,
  ).toLowerCase();
  if (explicitAllowToggle === "true" || explicitAllowToggle === "1") return true;

  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  if (!tenantId || !companyId) return false;

  const allowlistRaw = safeStr(env?.CALENDAR_GLOBAL_FALLBACK_ALLOWLIST, 4096);
  if (!allowlistRaw) return false;
  const tenantLower = tenantId.toLowerCase();
  const companyLower = companyId.toLowerCase();
  const pairLower = `${tenantLower}:${companyLower}`;
  const entries = allowlistRaw
    .split(",")
    .map((entry) => safeStr(entry, 200).toLowerCase())
    .filter(Boolean);
  for (const entry of entries) {
    if (entry === pairLower || entry === tenantLower || entry === companyLower) {
      return true;
    }
  }
  return false;
}

const CALENDAR_OAUTH_NONCE_TTL_SECONDS = 600;
const CALENDAR_OAUTH_STATE_PURPOSE = "google_calendar_oauth";

function base64urlEncodeBytes(bytes) {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
  let binary = "";
  const chunkSize = 0x2000;
  for (let i = 0; i < arr.length; i += chunkSize) {
    const end = Math.min(i + chunkSize, arr.length);
    let chunk = "";
    for (let j = i; j < end; j++) chunk += String.fromCharCode(arr[j]);
    binary += chunk;
  }
  return btoa(binary)
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}

function base64urlDecodeToBytes(str) {
  const raw = String(str || "").trim();
  if (!raw) return new Uint8Array();
  const normalized = raw
    .replace(/-/g, "+")
    .replace(/_/g, "/")
    .padEnd(Math.ceil(raw.length / 4) * 4, "=");
  const bin = atob(normalized);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function jsonBase64urlEncode(obj) {
  const text = JSON.stringify(obj ?? {});
  const bytes = new TextEncoder().encode(text);
  return base64urlEncodeBytes(bytes);
}

function jsonBase64urlDecode(str) {
  const bytes = base64urlDecodeToBytes(str);
  const text = new TextDecoder().decode(bytes);
  return JSON.parse(text);
}

async function importHmacKey(secret) {
  const normalized = String(secret || "").trim();
  if (!normalized) throw new Error("missing_calendar_oauth_state_secret");
  const raw = new TextEncoder().encode(normalized);
  return crypto.subtle.importKey(
    "raw",
    raw,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );
}

async function signCalendarOAuthState(payloadB64, secret) {
  const key = await importHmacKey(secret);
  const data = new TextEncoder().encode(String(payloadB64 || ""));
  const signature = await crypto.subtle.sign("HMAC", key, data);
  return base64urlEncodeBytes(new Uint8Array(signature));
}

async function verifyCalendarOAuthState(payloadB64, sigB64, secret) {
  const key = await importHmacKey(secret);
  const data = new TextEncoder().encode(String(payloadB64 || ""));
  const sig = base64urlDecodeToBytes(sigB64);
  if (!sig.length) return false;
  return crypto.subtle.verify("HMAC", key, sig, data);
}

async function _importCalendarEncryptionKey(env) {
  const rawSecret = String(env?.CALENDAR_AUTH_ENCRYPTION_KEY || "").trim();
  if (!rawSecret) throw new Error("missing_calendar_auth_encryption_key");
  const keyMaterial = new TextEncoder().encode(rawSecret);
  const digest = await crypto.subtle.digest("SHA-256", keyMaterial);
  return crypto.subtle.importKey(
    "raw",
    digest,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

async function encryptCalendarRefreshToken(refreshToken, env) {
  const token = String(refreshToken || "");
  if (!token) throw new Error("missing_refresh_token");
  const key = await _importCalendarEncryptionKey(env);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const plaintext = new TextEncoder().encode(token);
  const encrypted = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    key,
    plaintext,
  );
  return {
    alg: "AES-GCM",
    kid: safeStr(env?.CALENDAR_AUTH_ENCRYPTION_KID, 32) || "v1",
    iv: base64urlEncodeBytes(iv),
    ciphertext: base64urlEncodeBytes(new Uint8Array(encrypted)),
  };
}

async function decryptCalendarRefreshToken(encryptedObj, env) {
  if (!encryptedObj || typeof encryptedObj !== "object") {
    throw new Error("invalid_encrypted_refresh_token");
  }
  const alg = String(encryptedObj.alg || "").trim();
  if (alg !== "AES-GCM") throw new Error("unsupported_encrypted_refresh_token_alg");
  const iv = base64urlDecodeToBytes(encryptedObj.iv);
  const ciphertext = base64urlDecodeToBytes(encryptedObj.ciphertext);
  if (!iv.length || !ciphertext.length) {
    throw new Error("invalid_encrypted_refresh_token_payload");
  }
  const key = await _importCalendarEncryptionKey(env);
  const decrypted = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ciphertext,
  );
  return new TextDecoder().decode(new Uint8Array(decrypted));
}

function buildCalendarOAuthNonceKey(scope = null, nonce = "") {
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  const nonceId = String(nonce || "").trim().replace(/[^a-zA-Z0-9_-]+/g, "");
  if (!tenantId || !companyId || !nonceId) return null;
  return `tenant:${tenantId}:company:${companyId}:google_oauth_state_nonce:${nonceId}:v1`;
}

async function createCalendarOAuthNonce(env, scope) {
  if (!env?.BOOKING_KV) throw new Error("missing_booking_kv");
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  if (!tenantId || !companyId) throw new Error("missing_tenant_scope");
  const nonce = (crypto?.randomUUID ? crypto.randomUUID() : `${Date.now()}_${Math.random()}`)
    .replace(/[^a-zA-Z0-9_-]+/g, "");
  const nowMs = Date.now();
  const expiresMs = nowMs + CALENDAR_OAUTH_NONCE_TTL_SECONDS * 1000;
  const key = buildCalendarOAuthNonceKey(
    { tenant_id: tenantId, company_id: companyId },
    nonce,
  );
  if (!key) throw new Error("invalid_oauth_nonce_key");
  const record = {
    purpose: CALENDAR_OAUTH_STATE_PURPOSE,
    tenant_id: tenantId,
    company_id: companyId,
    nonce,
    issued_at: new Date(nowMs).toISOString(),
    expires_at: new Date(expiresMs).toISOString(),
    consumed: false,
  };
  await env.BOOKING_KV.put(key, JSON.stringify(record), {
    expirationTtl: CALENDAR_OAUTH_NONCE_TTL_SECONDS,
  });
  return {
    nonce,
    issuedAt: record.issued_at,
    expiresAt: record.expires_at,
    expiresIn: CALENDAR_OAUTH_NONCE_TTL_SECONDS,
    key,
  };
}

async function consumeCalendarOAuthNonce(env, scope, nonce) {
  if (!env?.BOOKING_KV) {
    return { ok: false, code: "missing_booking_kv" };
  }
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  const key = buildCalendarOAuthNonceKey(
    { tenant_id: tenantId, company_id: companyId },
    nonce,
  );
  if (!key || !tenantId || !companyId) {
    return { ok: false, code: "invalid_nonce_scope" };
  }
  const rec = await env.BOOKING_KV.get(key, { type: "json" });
  if (!rec || typeof rec !== "object") {
    return { ok: false, code: "nonce_missing" };
  }
  if (String(rec?.purpose || "") !== CALENDAR_OAUTH_STATE_PURPOSE) {
    return { ok: false, code: "nonce_purpose_mismatch" };
  }
  if (
    sanitizeTenantString(rec?.tenant_id ?? rec?.tenantId, 80) !== tenantId ||
    sanitizeTenantString(rec?.company_id ?? rec?.companyId, 80) !== companyId
  ) {
    return { ok: false, code: "nonce_scope_mismatch" };
  }
  if (String(rec?.nonce || "").trim() !== String(nonce || "").trim()) {
    return { ok: false, code: "nonce_value_mismatch" };
  }
  if (rec?.consumed === true) {
    return { ok: false, code: "nonce_consumed" };
  }
  const expiresAt = Date.parse(String(rec?.expires_at || ""));
  if (!Number.isFinite(expiresAt) || Date.now() > expiresAt) {
    return { ok: false, code: "nonce_expired" };
  }
  await env.BOOKING_KV.delete(key);
  return { ok: true };
}

async function loadGoogleCalendarAuthConfig(env, scope = null) {
  const scopedKey = buildScopedGoogleCalendarAuthKey(scope);
  const baseClientId = safeStr(env?.GOOGLE_CLIENT_ID);
  const baseClientSecret = safeStr(env?.GOOGLE_CLIENT_SECRET);
  const baseRefreshToken = safeStr(env?.GOOGLE_REFRESH_TOKEN);
  const baseCalendarId = safeStr(env?.GOOGLE_CALENDAR_ID);
  let scopedErrorCode = null;

  if (scopedKey && env?.BOOKING_KV) {
    try {
      const raw = await env.BOOKING_KV.get(scopedKey, { type: "json" });
      const scoped = raw && typeof raw === "object"
        ? (raw.google_calendar_auth && typeof raw.google_calendar_auth === "object"
            ? raw.google_calendar_auth
            : raw)
        : null;
      if (scoped) {
        const connected = scoped.connected === undefined
          ? true
          : !!scoped.connected;
        const status = safeStr(scoped.status, 64) || null;
        const scopedClientId = safeStr(
          scoped.clientId ?? scoped.client_id ?? baseClientId,
        );
        const scopedClientSecret = safeStr(
          scoped.clientSecret ?? scoped.client_secret ?? baseClientSecret,
        );
        let scopedRefreshToken = "";
        if (
          scoped.refreshTokenEncrypted &&
          typeof scoped.refreshTokenEncrypted === "object"
        ) {
          try {
            scopedRefreshToken = safeStr(
              await decryptCalendarRefreshToken(scoped.refreshTokenEncrypted, env),
            );
          } catch (_) {
            scopedErrorCode = "scoped_token_decrypt_failed";
            console.log(
              `[CALENDAR_AUTH][WARN] source=scoped key=${scopedKey} reason=${scopedErrorCode}`,
            );
          }
        }
        if (!scopedRefreshToken) {
          // Phase 1/2 migration compatibility path:
          // plain refreshToken from KV is supported temporarily, but production
          // should store encrypted refresh tokens with key rotation.
          scopedRefreshToken = safeStr(
            scoped.refreshToken ?? scoped.refresh_token,
          );
        }
        const scopedCalendarId = safeStr(
          scoped.calendarId ?? scoped.calendar_id,
        ) || "primary";
        const accountEmail = safeStr(
          scoped.accountEmail ?? scoped.account_email,
          320,
        ) || null;
        const scopedConfigured =
          connected &&
          !!scopedClientId &&
          !!scopedClientSecret &&
          !!scopedRefreshToken;
        if (scopedConfigured) {
          return {
            source: "scoped",
            configured: true,
            clientId: scopedClientId,
            clientSecret: scopedClientSecret,
            refreshToken: scopedRefreshToken,
            calendarId: scopedCalendarId,
            status,
            accountEmail,
            scopedKey,
          };
        }
        if (scoped.connected !== undefined && scoped.connected !== null) {
          scopedErrorCode = scopedErrorCode || "scoped_not_usable";
        }
      }
    } catch (scopedErr) {
      scopedErrorCode = scopedErrorCode || "scoped_lookup_failed";
      console.log(
        `[CALENDAR_AUTH][WARN] source=scoped key=${scopedKey} reason=${safeStr(scopedErr?.message || scopedErr, 140) || scopedErrorCode}`,
      );
      // Best-effort scoped lookup. Global fallback remains available.
    }
  }

  const globalConfigured =
    !!baseClientId &&
    !!baseClientSecret &&
    !!baseRefreshToken &&
    !!baseCalendarId;
  if (globalConfigured) {
    // Global env Calendar fallback is disabled by default for explicit scoped
    // tenants to prevent cross-company calendar leakage.
    const allowGlobalFallback = shouldAllowGlobalGoogleCalendarFallback(
      env,
      scope,
    );
    if (!allowGlobalFallback) {
      const blockedTenant = sanitizeTenantString(
        scope?.tenant_id ?? scope?.tenantId,
        80,
      ) || "-";
      const blockedCompany = sanitizeTenantString(
        scope?.company_id ?? scope?.companyId,
        80,
      ) || "-";
      console.log(
        `[CALENDAR_AUTH][GLOBAL_FALLBACK_BLOCKED] tenant=${blockedTenant} company=${blockedCompany}`,
      );
      return {
        source: "none",
        configured: false,
        clientId: "",
        clientSecret: "",
        refreshToken: "",
        calendarId: "",
        status: null,
        accountEmail: null,
        scopedKey,
        scopedErrorCode: scopedErrorCode || "global_fallback_blocked",
      };
    }
    if (scopedErrorCode) {
      console.log(
        `[CALENDAR_AUTH][WARN] source=global_env reason=scoped_unusable code=${scopedErrorCode}`,
      );
    }
    return {
      source: "global_env",
      configured: true,
      clientId: baseClientId,
      clientSecret: baseClientSecret,
      refreshToken: baseRefreshToken,
      calendarId: baseCalendarId,
      status: null,
      accountEmail: null,
      scopedKey,
      scopedErrorCode,
    };
  }

  return {
    source: "none",
    configured: false,
    clientId: "",
    clientSecret: "",
    refreshToken: "",
    calendarId: "",
    status: null,
    accountEmail: null,
    scopedKey,
  };
}

async function googleAccessTokenFromConfig(config) {
  const clientId = safeStr(config?.clientId);
  const clientSecret = safeStr(config?.clientSecret);
  const refreshToken = safeStr(config?.refreshToken);
  if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Google Calendar is not configured (missing client credentials or refresh token).");
  }

  const tokenUrl = 'https://oauth2.googleapis.com/token';
  const form = new URLSearchParams();
  form.set('client_id', clientId);
  form.set('client_secret', clientSecret);
  form.set('refresh_token', refreshToken);
  form.set('grant_type', 'refresh_token');

  const r = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: form.toString(),
  });

  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) {
    throw new Error(j?.error_description || j?.error || 'Failed to refresh Google access token.');
  }
  return j.access_token;
}

/* Single source of truth for Google token refresh. */
async function googleAccessToken(env) {
  const cfg = await loadGoogleCalendarAuthConfig(env, null);
  if (!cfg?.configured) {
    throw new Error('Google Calendar is not configured (missing GOOGLE_CLIENT_ID/SECRET/REFRESH_TOKEN).');
  }
  return googleAccessTokenFromConfig(cfg);
}

/* Backward-compatible aliases (older code paths may call these). */
async function getGoogleAccessToken(env) { return googleAccessToken(env); }
async function refreshGoogleAccessToken(env) { return googleAccessToken(env); }

function isGoogleCalendarAuthError(err) {
  let serialized = "";
  try {
    serialized = JSON.stringify(err || {});
  } catch (_) {
    serialized = "";
  }
  const text = [
    err?.message,
    err?.error,
    typeof err === "string" ? err : "",
    serialized,
  ]
    .filter(Boolean)
    .join(" | ")
    .toLowerCase();
  if (!text) return false;
  return (
    text.includes("invalid_grant") ||
    text.includes("token has been expired or revoked") ||
    text.includes("expired or revoked") ||
    text.includes("unauthorized_client") ||
    text.includes("invalid_client") ||
    text.includes("failed to refresh google access token")
  );
}

// Extra safety: expose in global scope (helps when older code references global names).
try {
  globalThis.googleAccessToken = googleAccessToken;
  globalThis.getGoogleAccessToken = getGoogleAccessToken;
  globalThis.refreshGoogleAccessToken = refreshGoogleAccessToken;
} catch (_) {}


// ==============================
// Global numeric helpers (must be in module scope)
// ==============================
function toInt(value, fallback = 0) {
  const n = Number.parseInt(String(value ?? '').trim(), 10);
  return Number.isFinite(n) ? n : fallback;
}

function toNum(value, fallback = 0) {
  const n = Number(String(value ?? '').trim());
  return Number.isFinite(n) ? n : fallback;
}

function _adminTokenFromRequest(request, url) {
  const h = (request.headers.get("x-admin-token") || "").trim();
  if (h) return h;
  const auth = request.headers.get("authorization") || "";
  const m = auth.match(/^Bearer\s+(.+)$/i);
  if (m && (m[1] || "").trim()) return m[1].trim();
  return "";
}

async function _allocatorRequest(env, pickupIso, payload) {
  if (!env?.FLEET_ALLOCATOR) throw new Error("FLEET_ALLOCATOR binding is missing");
  const tenantScope = normalizeFleetTenantScope(
    payload?.tenantScope ?? payload?.tenant_scope ?? payload,
  );
  const scopeKey = _fleetAllocatorScopeKey(pickupIso, tenantScope);
  const id = env.FLEET_ALLOCATOR.idFromName(scopeKey);
  const stub = env.FLEET_ALLOCATOR.get(id);
  const res = await stub.fetch("https://fleet-allocator/internal", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      ...payload,
      scope_key: scopeKey,
      tenant_id: tenantScope.tenant_id || undefined,
      company_id: tenantScope.company_id || undefined,
    }),
  });
  const out = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(String(out?.error || "Fleet allocator failed"));
  }
  return out;
}

function _fleetAllocatorScopeKey(pickupIso, scope = null) {
  const normalizedScope = normalizeFleetTenantScope(scope);
  try {
    const d = new Date(pickupIso);
    if (isNaN(d.getTime())) {
      if (normalizedScope.hasScope) {
        return `fleet:${normalizedScope.tenant_id}:${normalizedScope.company_id}:invalid-date`;
      }
      return "fleet:invalid-date";
    }
    const day = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Europe/Brussels",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(d);
    if (normalizedScope.hasScope) {
      return `fleet:${normalizedScope.tenant_id}:${normalizedScope.company_id}:${day}`;
    }
    return `fleet:${day}`;
  } catch (_) {
    if (normalizedScope.hasScope) {
      return `fleet:${normalizedScope.tenant_id}:${normalizedScope.company_id}:fallback`;
    }
    return "fleet:fallback";
  }
}

function _bookingLifecycleValue(rec) {
  return (
    rec?.status ??
    rec?.stage ??
    rec?.booking?.status ??
    rec?.booking?.stage ??
    null
  );
}

export class FleetAllocatorDO {
  constructor(state, env) {
    this.state = state;
    this.env = env;
  }

  async fetch(request) {
    let body = {};
    try {
      body = await request.json();
    } catch (_) {
      body = {};
    }
    const action = String(body?.action || "").trim().toLowerCase();
    if (action === "allocate") return this._allocate(body);
    if (action === "release") return this._release(body);
    return new Response(JSON.stringify({ ok: false, error: "Unknown action" }), {
      status: 400,
      headers: { "content-type": "application/json" },
    });
  }

  async _allocate(body) {
    const bookingId = String(body?.booking_id || "").trim();
    const pickupMs = Number(body?.pickup_ms);
    const serviceMin = Math.max(1, Number(body?.service_min) || 1);
    const tier = String(body?.tier || "comfort").trim().toLowerCase();
    const pax = Number(body?.pax ?? 1);
    const bags = Number(body?.bags ?? 0);
    const pickupAddress = safeStr(
      body?.pickup_address ?? body?.pickup_from ?? body?.from ?? "",
      240,
    );
    const pickupLat = Number(body?.pickup_lat ?? body?.pickupLat ?? body?.from_lat ?? body?.fromLat);
    const pickupLng = Number(body?.pickup_lng ?? body?.pickupLng ?? body?.from_lng ?? body?.fromLng);
    if (!bookingId || !Number.isFinite(pickupMs)) {
      return this._json({ ok: false, error: "Invalid allocate request" }, 400);
    }

    const tenantScope = normalizeFleetTenantScope(body);
    const req = {
      pickupMs,
      serviceMin,
      tier,
      pax,
      bags,
      pickup_address: pickupAddress,
      pickup_lat: Number.isFinite(pickupLat) ? pickupLat : null,
      pickup_lng: Number.isFinite(pickupLng) ? pickupLng : null,
      tenantScope,
    };
    const reservations = await this._loadReservations();
    let reservationsDirty = false;

    // Idempotency for retried booking confirmation
    if (reservations[bookingId]?.vehicle_id) {
      let keepReservation = true;
      try {
        const linkedBookingKey = _parentBookingIdFromAllocatorReservationId(bookingId);
        const linked = await this.env.BOOKING_KV.get(`booking:${linkedBookingKey}`, {
          type: "json",
        });
        if (!linked || isTerminalLifecycleStatus(_bookingLifecycleValue(linked))) {
          delete reservations[bookingId];
          reservationsDirty = true;
          keepReservation = false;
          console.log(
            `[FLEET][ALLOCATOR][PRUNE_STALE_RESERVATION] booking=${_bookingIntentMask(bookingId)} reason=${!linked ? "missing_booking" : "terminal_booking"}`,
          );
        }
      } catch (_) {
        // Best-effort stale-prune check only.
      }
      if (keepReservation) {
        if (reservationsDirty) {
          await this._saveReservations(reservations);
          reservationsDirty = false;
        }
        return this._json({
          ok: true,
          allowed: true,
          booking_id: bookingId,
          assigned_vehicle_id: reservations[bookingId].vehicle_id,
          source: "existing_reservation",
        });
      }
    }
    if (reservationsDirty) {
      await this._saveReservations(reservations);
      reservationsDirty = false;
    }

    const vehicles = await _loadVehicleInventory(this.env, { scope: tenantScope });
    // G3-D: diagnostics-only. No behavior change. These logs explain why
    // FleetAllocatorDO rejects a booking with no_suitable_vehicle or
    // vehicle_capacity_exceeded. Ids are masked via _bookingIntentMask;
    // customer/payment data is never logged here.
    const _diagReqPax = _toPositiveInt(req?.pax ?? 0, 0);
    const _diagReqBags = _toPositiveInt(req?.bags ?? 0, 0);
    const _diagReqTier = safeStr(req?.tier, 24) || "*";
    const _diagReqService = safeStr(req?.service ?? req?.service_type, 32) || "-";
    const _diagServiceMin = Math.max(1, Number(req?.serviceMin) || 1);
    const _diagTenantMask = _bookingIntentMask(tenantScope?.tenant_id);
    const _diagCompanyMask = _bookingIntentMask(tenantScope?.company_id);
    console.log(
      `[FLEET_ALLOCATOR][INVENTORY] tenant=${_diagTenantMask} company=${_diagCompanyMask} vehicle_count=${vehicles.length} req_pax=${_diagReqPax} req_bags=${_diagReqBags} req_tier=${_diagReqTier} req_service=${_diagReqService} service_min=${_diagServiceMin}`,
    );
    try {
      for (const _diagVehicle of vehicles) {
        const _diagVehicleIdMasked = _bookingIntentMask(_diagVehicle?.vehicle_id);
        const _diagVehiclePax = _toPositiveInt(_diagVehicle?.passenger_capacity ?? 0, 0);
        const _diagVehicleBags = _toPositiveInt(_diagVehicle?.luggage_capacity ?? 0, 0);
        const _diagVehicleTier = safeStr(_diagVehicle?.tier, 24) || "*";
        let _diagSkipReason = null;
        if (!_diagVehicle || _diagVehicle.is_active === false) {
          _diagSkipReason = "inactive";
        } else if (_diagVehiclePax < _diagReqPax) {
          _diagSkipReason = "pax_capacity";
        } else if (_diagVehicleBags < _diagReqBags) {
          _diagSkipReason = "bag_capacity";
        }
        if (_diagSkipReason) {
          console.log(
            `[FLEET_ALLOCATOR][VEHICLE_SKIP] vehicle=${_diagVehicleIdMasked} reason=${_diagSkipReason} req_pax=${_diagReqPax} vehicle_pax=${_diagVehiclePax} req_bags=${_diagReqBags} vehicle_bags=${_diagVehicleBags} req_tier=${_diagReqTier} vehicle_tier=${_diagVehicleTier}`,
          );
        } else {
          const _diagDriverIdRaw = safeStr(
            _diagVehicle?.assigned_driver?.driver_id ??
              _diagVehicle?.assigned_driver?.driverId ??
              _diagVehicle?.assigned_driver?.id ??
              _diagVehicle?.assignedDriver?.driver_id ??
              _diagVehicle?.assignedDriver?.driverId ??
              _diagVehicle?.driver_id ??
              _diagVehicle?.driverId,
            96,
          );
          const _diagDriverPresent = !!_diagDriverIdRaw;
          console.log(
            `[FLEET_ALLOCATOR][VEHICLE_CANDIDATE] vehicle=${_diagVehicleIdMasked} driver_present=${_diagDriverPresent ? "true" : "false"} vehicle_pax=${_diagVehiclePax} vehicle_bags=${_diagVehicleBags} vehicle_tier=${_diagVehicleTier}`,
          );
        }
      }
    } catch (_) {
      // Diagnostics only; never fail allocation because of a log error.
    }
    const suitableVehicles = vehicles.filter((v) => _vehicleSupportsRequest(v, req));
    if (suitableVehicles.length === 0) {
      console.log(
        `[FLEET_ALLOCATOR][NO_SUITABLE_VEHICLE] tenant=${_diagTenantMask} company=${_diagCompanyMask} reason=no_suitable_vehicle vehicle_count=${vehicles.length} suitable_count=0 req_pax=${_diagReqPax} req_bags=${_diagReqBags} req_tier=${_diagReqTier}`,
      );
      return this._json({
        ok: true,
        allowed: false,
        reason: "no_suitable_vehicle",
        suitable_vehicle_count: 0,
      });
    }

    const suitableIds = new Set(suitableVehicles.map((v) => v.vehicle_id));
    const occupiedAssignedIds = new Set();
    let overlappingUnassignedDemand = 0;

    const indexedDemand = await _loadScopedActiveDemandWithRepair(
      this.env,
      tenantScope,
      { staleAfterMs: _fleetDemandIndexStaleAfterMs(this.env) },
    );
    if (!indexedDemand?.ok) {
      const reason = safeStr(indexedDemand?.reason, 80) || "demand_index_unavailable";
      return this._json({
        ok: true,
        allowed: false,
        reason,
        reason_code: reason,
        block_reason: reason,
        suitable_vehicle_count: suitableVehicles.length,
        occupied_assigned_count: 0,
        overlapping_unassigned_demand: 0,
        available_slots: 0,
        index_updated_at: safeStr(indexedDemand?.index_updated_at, 80) || null,
        demand_index_stale: indexedDemand?.stale === true,
        demand_index_rebuilt: indexedDemand?.demand_index_rebuilt === true,
        demand_index_stale_before_rebuild:
          indexedDemand?.demand_index_stale_before_rebuild === true,
        demand_index_reason_before_rebuild:
          safeStr(indexedDemand?.demand_index_reason_before_rebuild, 80) || null,
      });
    }
    // G3-E: never count the booking currently under decision as competing
    // unassigned demand. The demand index legitimately contains this
    // booking (and may also reference a payment-shadow / leg / parent),
    // and double-counting it makes vehicle_capacity_exceeded fire even
    // when no other ride is competing for the same slot. The protection
    // against OTHER overlapping unassigned demand is preserved unchanged.
    const _selfDemandCanonicalId = _dashboardCanonicalBookingNumber(
      safeStr(_parentBookingIdFromAllocatorReservationId(bookingId) || bookingId, 160),
    );
    const _selfDemandMaskedBookingId = _bookingIntentMask(bookingId);
    let _selfDemandTotalOverlapping = 0;
    let _selfDemandExcluded = 0;
    for (const d of indexedDemand?.items || []) {
      if (!_windowsOverlap(req.pickupMs, req.serviceMin, d.pickupMs, d.serviceMin)) continue;
      const assignedVehicleId = safeStr(d?.assigned_vehicle_id, 120);
      if (assignedVehicleId && suitableIds.has(assignedVehicleId)) {
        occupiedAssignedIds.add(assignedVehicleId);
        continue;
      }
      _selfDemandTotalOverlapping += 1;
      const selfMatch = _demandItemMatchesAllocatorBooking(d, bookingId);
      if (selfMatch) {
        _selfDemandExcluded += 1;
        console.log(
          `[FLEET_ALLOCATOR][UNASSIGNED_DEMAND_EXCLUDE_SELF] booking=${_selfDemandMaskedBookingId} demand=${_bookingIntentMask(d?.booking_id ?? d?.bookingId ?? d?.id)} reason=${selfMatch.reason}`,
        );
        continue;
      }
      // G3-G: skip anonymous/stale unassigned demand rows that carry no
      // recognizable Fluxidi booking identity (no canonical 2026-MM-NNN+,
      // no public booking reference, no PLN- planning reference, no
      // leg/parent/shadow correlation). Such rows can persist in the
      // demand index after partial writes, legacy entries, or an opaque
      // internal id ever leaked into the index; counting them blocks
      // every legitimate allocation forever even though no real ride is
      // competing. Rows that DO carry a recognizable identity still
      // count exactly as before unless the existing self-exclusion
      // already filtered them.
      if (!_demandItemHasRecognizableBookingIdentity(d)) {
        try {
          const _anonDemandIdRaw =
            d?.booking_id ?? d?.bookingId ?? d?.id ?? "";
          const _anonPickupMs = Number(d?.pickupMs);
          const _anonPickupIso = Number.isFinite(_anonPickupMs)
            ? new Date(_anonPickupMs).toISOString()
            : "-";
          const _anonServiceMin = Math.max(1, Number(d?.serviceMin) || 1);
          console.log(
            `[FLEET_ALLOCATOR][UNASSIGNED_DEMAND_SKIP_ANONYMOUS] booking=${_selfDemandMaskedBookingId} demand=${_bookingIntentMask(_anonDemandIdRaw)} pickup_iso=${_anonPickupIso} service_min=${_anonServiceMin} reason=missing_booking_identity`,
          );
        } catch (_) {
          // Diagnostics only; never affect allocation.
        }
        continue;
      }
      if (suitableVehicles.some((v) => _vehicleSupportsRequest(v, d))) {
        overlappingUnassignedDemand += 1;
        // G3-F: diagnostics-only. Explain WHY this demand row is counted
        // as competing overlapping unassigned demand. The previous
        // [UNASSIGNED_DEMAND_COUNT] only gives totals; this log surfaces
        // the specific demand row(s) so we can see whether the remaining
        // counted row is a sibling/leg/shadow of the booking under
        // decision (then G3-G expands self-exclusion) or a genuine other
        // ride competing for the same slot. Coordinates / addresses are
        // never logged here. Ids are masked via _bookingIntentMask.
        try {
          const _diagDemandIdRaw =
            d?.booking_id ?? d?.bookingId ?? d?.id ?? "";
          const _diagDemandParentRaw =
            d?.parent_booking_id ?? d?.parentBookingId ?? "";
          const _diagDemandCanonicalRaw =
            d?.canonical_booking_id ??
            d?.canonicalBookingId ??
            d?.original_booking_id ??
            d?.originalBookingId ??
            "";
          const _diagDemandLegRaw = d?.leg_id ?? d?.legId ?? "";
          const _diagDemandPaymentRaw =
            d?.payment_booking_id ??
            d?.paymentBookingId ??
            d?.shadow_booking_id ??
            d?.shadowBookingId ??
            "";
          const _diagDemandPublicRaw =
            d?.public_booking_id ?? d?.publicBookingId ?? "";
          const _diagDemandPickupMs = Number(d?.pickupMs);
          const _diagDemandPickupIso = Number.isFinite(_diagDemandPickupMs)
            ? new Date(_diagDemandPickupMs).toISOString()
            : "-";
          const _diagDemandServiceMin = Math.max(
            1,
            Number(d?.serviceMin) || 1,
          );
          const _diagDemandHasAssignedVehicle = !!safeStr(
            d?.assigned_vehicle_id ?? d?.assignedVehicleId,
            120,
          );
          const _diagDemandHasAssignedDriver = !!safeStr(
            d?.assigned_driver_id ?? d?.assignedDriverId,
            120,
          );
          console.log(
            `[FLEET_ALLOCATOR][UNASSIGNED_DEMAND_COUNTED] current=${_selfDemandMaskedBookingId} demand=${_bookingIntentMask(_diagDemandIdRaw)} parent=${_bookingIntentMask(_diagDemandParentRaw)} canonical=${_bookingIntentMask(_diagDemandCanonicalRaw)} leg=${_bookingIntentMask(_diagDemandLegRaw)} payment=${_bookingIntentMask(_diagDemandPaymentRaw)} public=${_bookingIntentMask(_diagDemandPublicRaw)} pickup_iso=${_diagDemandPickupIso} service_min=${_diagDemandServiceMin} assigned_vehicle_present=${_diagDemandHasAssignedVehicle ? "true" : "false"} assigned_driver_present=${_diagDemandHasAssignedDriver ? "true" : "false"} reason=counted_other`,
          );
          // Compact relation diagnostic between the booking under
          // decision and this counted demand row. Surfaces id-shape
          // overlaps that _demandItemMatchesCurrentBooking did NOT
          // already match (e.g. shared shadow / parent-of-leg).
          const _diagCurrentSafe = safeStr(bookingId, 160);
          const _diagDemandIdSafe = safeStr(_diagDemandIdRaw, 160);
          const _diagDemandParentSafe = safeStr(_diagDemandParentRaw, 160);
          const _diagDemandCanonicalSafe = safeStr(
            _diagDemandCanonicalRaw,
            160,
          );
          const _diagDemandLegSafe = safeStr(_diagDemandLegRaw, 160);
          const _diagDemandPaymentSafe = safeStr(_diagDemandPaymentRaw, 160);
          const _diagDemandCanonicalDerived =
            _dashboardCanonicalBookingNumber(_diagDemandIdSafe) ||
            _dashboardCanonicalBookingNumber(_diagDemandParentSafe) ||
            _dashboardCanonicalBookingNumber(_diagDemandCanonicalSafe) ||
            _dashboardCanonicalBookingNumber(_diagDemandLegSafe) ||
            "";
          const _diagSameDashboardCanonical =
            !!_selfDemandCanonicalId &&
            !!_diagDemandCanonicalDerived &&
            _diagDemandCanonicalDerived === _selfDemandCanonicalId;
          const _diagSameParent =
            !!_diagDemandParentSafe &&
            !!_diagCurrentSafe &&
            _diagDemandParentSafe === _diagCurrentSafe;
          const _diagSameLegParent =
            !!_diagDemandLegSafe &&
            !!_diagCurrentSafe &&
            (_diagDemandLegSafe === _diagCurrentSafe ||
              _diagDemandLegSafe.startsWith(`${_diagCurrentSafe}:`) ||
              _diagDemandLegSafe.startsWith(`${_diagCurrentSafe}-`));
          const _diagSamePaymentShadow =
            !!_diagDemandPaymentSafe &&
            !!_diagCurrentSafe &&
            _diagDemandPaymentSafe === _diagCurrentSafe;
          console.log(
            `[FLEET_ALLOCATOR][UNASSIGNED_DEMAND_RELATION] current=${_selfDemandMaskedBookingId} demand=${_bookingIntentMask(_diagDemandIdRaw)} same_dashboard_canonical=${_diagSameDashboardCanonical ? "true" : "false"} same_parent=${_diagSameParent ? "true" : "false"} same_leg_parent=${_diagSameLegParent ? "true" : "false"} same_payment_shadow=${_diagSamePaymentShadow ? "true" : "false"}`,
          );
        } catch (_) {
          // Diagnostics only; never affect allocation.
        }
      }
    }
    console.log(
      `[FLEET_ALLOCATOR][UNASSIGNED_DEMAND_COUNT] booking=${_selfDemandMaskedBookingId} total=${_selfDemandTotalOverlapping} excluded_self=${_selfDemandExcluded} counted=${overlappingUnassignedDemand}`,
    );

    // Serialized in-flight reservations inside DO
    for (const [id, r] of Object.entries(reservations)) {
      if (!r || id === bookingId) continue;
      try {
        const linkedBookingKey = _parentBookingIdFromAllocatorReservationId(id);
        const linked = await this.env.BOOKING_KV.get(`booking:${linkedBookingKey}`, { type: "json" });
        if (!linked || isTerminalLifecycleStatus(_bookingLifecycleValue(linked))) {
          delete reservations[id];
          reservationsDirty = true;
          console.log(
            `[FLEET][ALLOCATOR][PRUNE_STALE_RESERVATION] booking=${_bookingIntentMask(id)} reason=${!linked ? "missing_booking" : "terminal_booking"}`,
          );
          continue;
        }
      } catch (_) {
        // Best-effort stale-prune check only.
      }
      const rPickup = Number(r.pickup_ms);
      const rService = Math.max(1, Number(r.service_min) || 1);
      if (!Number.isFinite(rPickup)) continue;
      if (!_windowsOverlap(req.pickupMs, req.serviceMin, rPickup, rService)) continue;
      const rv = String(r.vehicle_id || "").trim();
      if (rv && suitableIds.has(rv)) {
        occupiedAssignedIds.add(rv);
      }
    }
    if (reservationsDirty) {
      await this._saveReservations(reservations);
      reservationsDirty = false;
    }

    const freeVehicles = suitableVehicles
      .filter((v) => !occupiedAssignedIds.has(v.vehicle_id))
      .sort((a, b) => String(a.vehicle_id).localeCompare(String(b.vehicle_id)));
    const availableSlots = freeVehicles.length - overlappingUnassignedDemand;
    // G3-H: per-vehicle diagnostics over the suitable pool, showing why
    // each candidate is or is not in `freeVehicles`. The freeVehicles
    // filter currently only excludes vehicles whose vehicle_id is in
    // `occupiedAssignedIds` (assigned conflicts). Capacity/driver
    // availability/tier/service are already enforced upstream:
    //   - capacity by _vehicleSupportsRequest (suitableVehicles)
    //   - driver availability by _loadVehicleInventory
    //   - tier/service are not currently enforced as gates inside
    //     _vehicleSupportsRequest, so we surface them as "-"/true with
    //     vehicle_tier present so an operator can sanity-check.
    // No behavior change. Wrapped in try/catch so logging failures can
    // never affect allocation.
    try {
      for (const _evalV of suitableVehicles) {
        const _evalVehicleIdMasked = _bookingIntentMask(_evalV?.vehicle_id);
        const _evalDriverIdRaw = safeStr(
          _evalV?.assigned_driver?.driver_id ??
            _evalV?.assigned_driver?.driverId ??
            _evalV?.assigned_driver?.id ??
            _evalV?.assignedDriver?.driver_id ??
            _evalV?.assignedDriver?.driverId ??
            _evalV?.driver_id ??
            _evalV?.driverId,
          96,
        );
        const _evalDriverPresent = !!_evalDriverIdRaw;
        const _evalAssignedOverlap = occupiedAssignedIds.has(_evalV?.vehicle_id);
        const _evalVehicleTier = safeStr(_evalV?.tier, 24) || "*";
        const _evalTierOk =
          _evalVehicleTier === "*" || _evalVehicleTier === _diagReqTier;
        const _evalIncludedFree = !_evalAssignedOverlap;
        let _evalExcludeReason = "-";
        if (!_evalIncludedFree) _evalExcludeReason = "assigned_overlap";
        console.log(
          `[FLEET_ALLOCATOR][FREE_VEHICLE_EVAL] booking=${_selfDemandMaskedBookingId} vehicle=${_evalVehicleIdMasked} driver_present=${_evalDriverPresent ? "true" : "false"} capacity_ok=true tier_ok=${_evalTierOk ? "true" : "false"} service_ok=true assigned_overlap=${_evalAssignedOverlap ? "true" : "false"} driver_available=true included_free=${_evalIncludedFree ? "true" : "false"} exclude_reason=${_evalExcludeReason}`,
        );
      }
      console.log(
        `[FLEET_ALLOCATOR][SLOT_MATH] booking=${_selfDemandMaskedBookingId} vehicle_count=${vehicles.length} suitable_count=${suitableVehicles.length} free_vehicle_count=${freeVehicles.length} occupied_assigned_count=${occupiedAssignedIds.size} overlapping_unassigned_demand=${overlappingUnassignedDemand} total_overlapping_demand=${_selfDemandTotalOverlapping} excluded_self=${_selfDemandExcluded} available_slots=${availableSlots} reason=pre_capacity_decision`,
      );
    } catch (_) {
      // Diagnostics only; never affect allocation.
    }
    // G3-I: visibility around the inner _evaluateFleetAvailability call.
    // Helps locate the source of "vehicle_capacity_exceeded" when the
    // outer slot math is healthy (G3-H showed available_slots=2 yet the
    // dispatch result still came back as vehicle_capacity_exceeded). The
    // diagnostic context is read-only inside _evaluateFleetAvailability;
    // existing callers without diagContext keep working unchanged.
    const _diagFreeVehicleIds = freeVehicles
      .map((v) => safeStr(v?.vehicle_id, 120))
      .filter(Boolean);
    const _diagSuitableVehicleIds = suitableVehicles
      .map((v) => safeStr(v?.vehicle_id, 120))
      .filter(Boolean);
    const _diagFreeVehicleIdsPreview = _diagFreeVehicleIds
      .slice(0, 5)
      .map((id) => _bookingIntentMask(id))
      .join(",") || "-";
    const _diagSuitableVehicleIdsPreview = _diagSuitableVehicleIds
      .slice(0, 5)
      .map((id) => _bookingIntentMask(id))
      .join(",") || "-";
    try {
      console.log(
        `[FLEET_ALLOCATOR][ETA_EVAL_INPUT] booking=${_selfDemandMaskedBookingId} req_tier=${_diagReqTier} free_vehicle_count=${freeVehicles.length} suitable_count=${suitableVehicles.length} available_slots=${availableSlots} free_vehicle_ids=${_diagFreeVehicleIdsPreview} suitable_vehicle_ids=${_diagSuitableVehicleIdsPreview} reason=before_evaluate_fleet_availability`,
      );
    } catch (_) {
      // Diagnostics only.
    }
    const etaEvaluation = await _evaluateFleetAvailability(this.env, req, {
      bookingId,
      reqTier: _diagReqTier,
      freeVehicleIds: _diagFreeVehicleIds,
      suitableVehicleIds: _diagSuitableVehicleIds,
      availableSlots,
    });
    try {
      const _diagEtaAllowed = etaEvaluation?.would_allow_booking === true;
      const _diagEtaReason = safeStr(etaEvaluation?.reason, 80) || "-";
      const _diagEtaSource = safeStr(etaEvaluation?.source, 40) || "-";
      const _diagEtaVehicleId = safeStr(
        etaEvaluation?.next_vehicle_candidate?.vehicle_id,
        120,
      );
      const _diagEtaDriverId = safeStr(
        etaEvaluation?.next_vehicle_candidate?.assigned_driver?.driver_id ??
          etaEvaluation?.next_vehicle_candidate?.assigned_driver?.driverId ??
          etaEvaluation?.next_vehicle_candidate?.assigned_driver?.id ??
          etaEvaluation?.next_vehicle_candidate?.driver_id ??
          etaEvaluation?.next_vehicle_candidate?.driverId,
        96,
      );
      console.log(
        `[FLEET_ALLOCATOR][ETA_EVAL_RESULT] booking=${_selfDemandMaskedBookingId} allowed=${_diagEtaAllowed ? "true" : "false"} reason=${_diagEtaReason} source=${_diagEtaSource} vehicle=${_bookingIntentMask(_diagEtaVehicleId)} driver=${_bookingIntentMask(_diagEtaDriverId)} free_vehicle_count=${freeVehicles.length} available_slots=${availableSlots} reason_stage=after_evaluate_fleet_availability`,
      );
    } catch (_) {
      // Diagnostics only.
    }
    if (availableSlots <= 0 || freeVehicles.length === 0) {
      try {
        console.log(
          `[FLEET_ALLOCATOR][CAPACITY_REJECT_CONTEXT] booking=${_selfDemandMaskedBookingId} reject_path=available_slots_or_free_vehicles_zero source=- vehicle_count=${vehicles.length} suitable_count=${suitableVehicles.length} free_vehicle_count=${freeVehicles.length} occupied_assigned_count=${occupiedAssignedIds.size} overlapping_unassigned_demand=${overlappingUnassignedDemand} total_overlapping_demand=${_selfDemandTotalOverlapping} excluded_self=${_selfDemandExcluded} available_slots=${availableSlots}`,
        );
      } catch (_) {
        // Diagnostics only.
      }
      console.log(
        `[FLEET_ALLOCATOR][NO_SUITABLE_VEHICLE] tenant=${_diagTenantMask} company=${_diagCompanyMask} reason=vehicle_capacity_exceeded vehicle_count=${vehicles.length} suitable_count=${suitableVehicles.length} occupied_assigned_count=${occupiedAssignedIds.size} overlapping_unassigned_demand=${overlappingUnassignedDemand} available_slots=${Math.max(0, availableSlots)} req_pax=${_diagReqPax} req_bags=${_diagReqBags} req_tier=${_diagReqTier}`,
      );
      return this._json({
        ok: true,
        allowed: false,
        reason: "vehicle_capacity_exceeded",
        suitable_vehicle_count: suitableVehicles.length,
        occupied_assigned_count: occupiedAssignedIds.size,
        overlapping_unassigned_demand: overlappingUnassignedDemand,
        available_slots: Math.max(0, availableSlots),
      });
    }
    if (!etaEvaluation?.would_allow_booking || !etaEvaluation?.next_vehicle_candidate?.vehicle_id) {
      return this._json({
        ok: true,
        allowed: false,
        reason: safeStr(etaEvaluation?.reason_code, 80) || "eta_not_feasible",
        reason_code: safeStr(etaEvaluation?.reason_code, 80) || "eta_not_feasible",
        block_reason: safeStr(etaEvaluation?.block_reason, 80) || "eta_not_feasible",
        suitable_vehicle_count: suitableVehicles.length,
        occupied_assigned_count: occupiedAssignedIds.size,
        overlapping_unassigned_demand: overlappingUnassignedDemand,
        available_slots: Math.max(0, availableSlots),
        available_seconds: Number.isFinite(Number(etaEvaluation?.available_seconds))
          ? Number(etaEvaluation.available_seconds)
          : null,
        required_seconds: Number.isFinite(Number(etaEvaluation?.required_seconds))
          ? Number(etaEvaluation.required_seconds)
          : null,
        origin_travel_seconds: Number.isFinite(Number(etaEvaluation?.origin_travel_seconds))
          ? Number(etaEvaluation.origin_travel_seconds)
          : null,
        required_buffer_seconds: Number.isFinite(Number(etaEvaluation?.required_buffer_seconds))
          ? Number(etaEvaluation.required_buffer_seconds)
          : null,
        origin_source: safeStr(etaEvaluation?.origin_source, 80) || null,
        origin_has_location:
          typeof etaEvaluation?.origin_has_location === "boolean"
            ? etaEvaluation.origin_has_location
            : null,
        pickup_has_location:
          typeof etaEvaluation?.pickup_has_location === "boolean"
            ? etaEvaluation.pickup_has_location
            : null,
        origin_address_preview: safeStr(etaEvaluation?.origin_address_preview, 80) || null,
        pickup_address_preview: safeStr(etaEvaluation?.pickup_address_preview, 80) || null,
        origin_age_seconds: Number.isFinite(Number(etaEvaluation?.origin_age_seconds))
          ? Number(etaEvaluation.origin_age_seconds)
          : null,
        origin_candidate_count: Number.isFinite(Number(etaEvaluation?.origin_candidate_count))
          ? Number(etaEvaluation.origin_candidate_count)
          : null,
        origin_candidate_sources_tried: safeStr(etaEvaluation?.origin_candidate_sources_tried, 240) || null,
        origin_candidate_resolution_summary:
          safeStr(etaEvaluation?.origin_candidate_resolution_summary, 240) || null,
        origin_geocode_attempted:
          typeof etaEvaluation?.origin_geocode_attempted === "boolean"
            ? etaEvaluation.origin_geocode_attempted
            : null,
        origin_geocode_success:
          typeof etaEvaluation?.origin_geocode_success === "boolean"
            ? etaEvaluation.origin_geocode_success
            : null,
        origin_geocode_source: safeStr(etaEvaluation?.origin_geocode_source, 80) || null,
        origin_geocode_error_code: safeStr(etaEvaluation?.origin_geocode_error_code, 80) || null,
        origin_geocode_error_message: safeStr(etaEvaluation?.origin_geocode_error_message, 180) || null,
        earliest_available_at_ms: Number.isFinite(Number(etaEvaluation?.earliest_available_at_ms))
          ? Number(etaEvaluation.earliest_available_at_ms)
          : null,
        earliest_available_at: safeStr(etaEvaluation?.earliest_available_at, 80) || null,
        route_failure_reason: safeStr(etaEvaluation?.route_failure_reason, 80) || null,
        route_http_status: Number.isFinite(Number(etaEvaluation?.route_http_status))
          ? Number(etaEvaluation.route_http_status)
          : null,
        route_error_message: safeStr(etaEvaluation?.route_error_message, 180) || null,
        route_error_code: safeStr(etaEvaluation?.route_error_code, 80) || null,
        route_profile: safeStr(etaEvaluation?.route_profile, 80) || null,
        route_origin_lat_ok:
          typeof etaEvaluation?.route_origin_lat_ok === "boolean"
            ? etaEvaluation.route_origin_lat_ok
            : null,
        route_origin_lng_ok:
          typeof etaEvaluation?.route_origin_lng_ok === "boolean"
            ? etaEvaluation.route_origin_lng_ok
            : null,
        route_origin_coords_usable:
          typeof etaEvaluation?.route_origin_coords_usable === "boolean"
            ? etaEvaluation.route_origin_coords_usable
            : null,
        route_pickup_lat_ok:
          typeof etaEvaluation?.route_pickup_lat_ok === "boolean"
            ? etaEvaluation.route_pickup_lat_ok
            : null,
        route_pickup_lng_ok:
          typeof etaEvaluation?.route_pickup_lng_ok === "boolean"
            ? etaEvaluation.route_pickup_lng_ok
            : null,
        route_pickup_coords_usable:
          typeof etaEvaluation?.route_pickup_coords_usable === "boolean"
            ? etaEvaluation.route_pickup_coords_usable
            : null,
        route_origin_latlng_preview: safeStr(etaEvaluation?.route_origin_latlng_preview, 64) || null,
        route_origin_lnglat_preview: safeStr(etaEvaluation?.route_origin_lnglat_preview, 64) || null,
        route_origin_coordinate_source: safeStr(etaEvaluation?.route_origin_coordinate_source, 64) || null,
        route_origin_coords_belgium_like:
          typeof etaEvaluation?.route_origin_coords_belgium_like === "boolean"
            ? etaEvaluation.route_origin_coords_belgium_like
            : null,
        route_pickup_latlng_preview: safeStr(etaEvaluation?.route_pickup_latlng_preview, 64) || null,
        route_pickup_lnglat_preview: safeStr(etaEvaluation?.route_pickup_lnglat_preview, 64) || null,
        route_pickup_coordinate_source: safeStr(etaEvaluation?.route_pickup_coordinate_source, 64) || null,
        route_pickup_coords_belgium_like:
          typeof etaEvaluation?.route_pickup_coords_belgium_like === "boolean"
            ? etaEvaluation.route_pickup_coords_belgium_like
            : null,
        route_duration_seconds_raw: Number.isFinite(Number(etaEvaluation?.route_duration_seconds_raw))
          ? Number(etaEvaluation.route_duration_seconds_raw)
          : null,
        route_response_has_routes:
          typeof etaEvaluation?.route_response_has_routes === "boolean"
            ? etaEvaluation.route_response_has_routes
            : null,
        route_response_routes_count: Number.isFinite(Number(etaEvaluation?.route_response_routes_count))
          ? Number(etaEvaluation.route_response_routes_count)
          : null,
        route_response_has_duration:
          typeof etaEvaluation?.route_response_has_duration === "boolean"
            ? etaEvaluation.route_response_has_duration
            : null,
        route_used_coordinate_direct:
          typeof etaEvaluation?.route_used_coordinate_direct === "boolean"
            ? etaEvaluation.route_used_coordinate_direct
            : null,
        route_used_geocode_fallback:
          typeof etaEvaluation?.route_used_geocode_fallback === "boolean"
            ? etaEvaluation.route_used_geocode_fallback
            : null,
        route_retry_reason: safeStr(etaEvaluation?.route_retry_reason, 80) || null,
        route_retry_used:
          typeof etaEvaluation?.route_retry_used === "boolean" ? etaEvaluation.route_retry_used : null,
        route_retry_success:
          typeof etaEvaluation?.route_retry_success === "boolean" ? etaEvaluation.route_retry_success : null,
        route_retry_http_status: Number.isFinite(Number(etaEvaluation?.route_retry_http_status))
          ? Number(etaEvaluation.route_retry_http_status)
          : null,
        route_retry_error_code: safeStr(etaEvaluation?.route_retry_error_code, 80) || null,
        route_retry_error_message: safeStr(etaEvaluation?.route_retry_error_message, 180) || null,
        route_retry_duration_seconds_raw:
          Number.isFinite(Number(etaEvaluation?.route_retry_duration_seconds_raw))
            ? Number(etaEvaluation.route_retry_duration_seconds_raw)
            : null,
        route_retry_radius_used: safeStr(etaEvaluation?.route_retry_radius_used, 32) || null,
        route_retry_snap_penalty_seconds:
          Number.isFinite(Number(etaEvaluation?.route_retry_snap_penalty_seconds))
            ? Number(etaEvaluation.route_retry_snap_penalty_seconds)
            : 0,
        route_retry_attempts_count:
          Number.isFinite(Number(etaEvaluation?.route_retry_attempts_count))
            ? Number(etaEvaluation.route_retry_attempts_count)
            : null,
        route_retry_attempts_summary: safeStr(etaEvaluation?.route_retry_attempts_summary, 180) || null,
        route_same_point_shortcut:
          typeof etaEvaluation?.route_same_point_shortcut === "boolean"
            ? etaEvaluation.route_same_point_shortcut
            : null,
        route_same_point_distance_meters:
          Number.isFinite(Number(etaEvaluation?.route_same_point_distance_meters))
            ? Number(etaEvaluation.route_same_point_distance_meters)
            : null,
      });
    }

    const etaChosenVehicleId = safeStr(etaEvaluation?.next_vehicle_candidate?.vehicle_id, 120);
    const chosen = freeVehicles.find((v) => v.vehicle_id === etaChosenVehicleId);
    if (!chosen) {
      try {
        console.log(
          `[FLEET_ALLOCATOR][CAPACITY_REJECT_CONTEXT] booking=${_selfDemandMaskedBookingId} reject_path=eta_candidate_missing source=${safeStr(etaEvaluation?.source, 40) || "-"} vehicle_count=${vehicles.length} suitable_count=${suitableVehicles.length} free_vehicle_count=${freeVehicles.length} occupied_assigned_count=${occupiedAssignedIds.size} overlapping_unassigned_demand=${overlappingUnassignedDemand} total_overlapping_demand=${_selfDemandTotalOverlapping} excluded_self=${_selfDemandExcluded} available_slots=${availableSlots} eta_candidate=${_bookingIntentMask(etaChosenVehicleId)}`,
        );
      } catch (_) {
        // Diagnostics only.
      }
      console.log(
        `[FLEET_ALLOCATOR][NO_SUITABLE_VEHICLE] tenant=${_diagTenantMask} company=${_diagCompanyMask} reason=vehicle_capacity_exceeded stage=eta_candidate_missing vehicle_count=${vehicles.length} suitable_count=${suitableVehicles.length} free_count=${freeVehicles.length} eta_candidate=${_bookingIntentMask(etaChosenVehicleId)} req_pax=${_diagReqPax} req_bags=${_diagReqBags} req_tier=${_diagReqTier}`,
      );
      return this._json({
        ok: true,
        allowed: false,
        reason: "vehicle_capacity_exceeded",
        reason_code: "vehicle_capacity_exceeded",
        block_reason: "vehicle_capacity_exceeded",
        suitable_vehicle_count: suitableVehicles.length,
        occupied_assigned_count: occupiedAssignedIds.size,
        overlapping_unassigned_demand: overlappingUnassignedDemand,
        available_slots: Math.max(0, availableSlots),
      });
    }
    reservations[bookingId] = {
      vehicle_id: chosen.vehicle_id,
      pickup_ms: req.pickupMs,
      service_min: req.serviceMin,
      created_at: Date.now(),
    };
    await this._saveReservations(reservations);
    return this._json({
      ok: true,
      allowed: true,
      booking_id: bookingId,
      assigned_vehicle_id: chosen.vehicle_id,
      assigned_driver: _assignedDriverFromVehicle(chosen),
      source: "new_reservation",
    });
  }

  async _release(body) {
    const bookingId = String(body?.booking_id || "").trim();
    if (!bookingId) return this._json({ ok: false, error: "booking_id required" }, 400);
    const reservations = await this._loadReservations();
    delete reservations[bookingId];
    await this._saveReservations(reservations);
    return this._json({ ok: true, released: true, booking_id: bookingId });
  }

  async _loadReservations() {
    const r = await this.state.storage.get("reservations");
    return r && typeof r === "object" ? r : {};
  }

  async _saveReservations(v) {
    await this.state.storage.put("reservations", v);
  }

  _json(obj, status = 200) {
    return new Response(JSON.stringify(obj), {
      status,
      headers: { "content-type": "application/json" },
    });
  }
}

export class BookingReferenceSequenceDO {
  constructor(stateOrCtx, env) {
    this.state = stateOrCtx;
    this.env = env;
  }

  async fetch(request) {
    let body = {};
    try {
      body = await request.json();
    } catch (_) {
      body = {};
    }
    const action = String(body?.action || "").trim().toLowerCase();
    if (action !== "allocate") {
      return this._json({ ok: false, error: "Unknown action" }, 400);
    }
    return this._allocate(body);
  }

  async _allocate(body) {
    const tenantId = safeStr(body?.tenant_id || body?.tenantId, 120);
    const companyId = safeStr(body?.company_id || body?.companyId, 120);
    if (!tenantId || !companyId) {
      return this._json({ ok: false, error: "missing_tenant_scope" }, 400);
    }
    const yearMonth =
      normalizeBookingReferenceYearMonth(body?.year_month || body?.yearMonth) ||
      bookingReferenceYearMonthFromPickupIso(body?.pickup_iso || body?.pickupIso) ||
      bookingReferenceYearMonthFromPickupIso(new Date().toISOString());
    if (!yearMonth) {
      return this._json({ ok: false, error: "Unable to resolve year_month" }, 400);
    }

    const next = await this.state.storage.transaction(async (txn) => {
      const current = clampInt(await txn.get("next"), 0, 999999999);
      const nextValue = current + 1;
      await txn.put("next", nextValue);
      return nextValue;
    });

    const publicBookingReference = `${yearMonth}-${String(next).padStart(6, "0")}`;
    return this._json({
      ok: true,
      tenant_id: tenantId,
      company_id: companyId,
      year_month: yearMonth,
      seq: next,
      public_booking_reference: publicBookingReference,
      publicBookingReference: publicBookingReference,
      booking_reference: publicBookingReference,
      bookingReference: publicBookingReference,
    });
  }

  _json(obj, status = 200) {
    return new Response(JSON.stringify(obj), {
      status,
      headers: { "content-type": "application/json" },
    });
  }
}

export class DocumentReferenceSequenceDO {
  constructor(stateOrCtx, env) {
    this.state = stateOrCtx;
    this.env = env;
  }

  async fetch(request) {
    let body = {};
    try {
      body = await request.json();
    } catch (_) {
      body = {};
    }
    const action = String(body?.action || "").trim().toLowerCase();
    if (action !== "allocate") {
      return this._json({ ok: false, error: "Unknown action" }, 400);
    }
    return this._allocate(body);
  }

  async _allocate(body) {
    const tenantId = safeStr(body?.tenant_id || body?.tenantId, 120);
    const companyId = safeStr(body?.company_id || body?.companyId, 120);
    if (!tenantId || !companyId) {
      return this._json({ ok: false, error: "missing_tenant_scope" }, 400);
    }
    const sequenceType = documentReferenceTypePart(
      body?.sequence_type || body?.sequenceType || body?.type,
      "",
    );
    if (!sequenceType) {
      return this._json({ ok: false, error: "Missing sequence_type" }, 400);
    }
    const prefix = safeStr(
      body?.prefix || body?.reference_prefix || body?.referencePrefix,
      16,
    ).toUpperCase();
    if (!prefix) {
      return this._json({ ok: false, error: "Missing prefix" }, 400);
    }
    const year =
      normalizeDocumentReferenceYear(body?.year) ||
      documentReferenceYearFromPickupIso(body?.pickup_iso || body?.pickupIso) ||
      documentReferenceYearFromPickupIso(new Date().toISOString());
    if (!year) {
      return this._json({ ok: false, error: "Unable to resolve year" }, 400);
    }

    const next = await this.state.storage.transaction(async (txn) => {
      const current = clampInt(await txn.get("next"), 0, 999999999);
      const nextValue = current + 1;
      await txn.put("next", nextValue);
      return nextValue;
    });

    const documentReference = `${prefix}-${year}-${String(next).padStart(6, "0")}`;
    return this._json({
      ok: true,
      tenant_id: tenantId,
      company_id: companyId,
      sequence_type: sequenceType,
      prefix,
      year,
      seq: next,
      document_reference: documentReference,
      documentReference,
    });
  }

  _json(obj, status = 200) {
    return new Response(JSON.stringify(obj), {
      status,
      headers: { "content-type": "application/json" },
    });
  }
}

function _requireAdmin(request, url, env) {
  const expected = (env.ADMIN_TOKEN || "").trim();
  if (!expected) throw new Error("ADMIN_TOKEN is not configured");
  const got = _adminTokenFromRequest(request, url);
  if (!got || got !== expected) throw new Error("Unauthorized");
}

function hasValidAdminToken(request, url, env) {
  const expected = (env?.ADMIN_TOKEN || "").trim();
  if (!expected) return false;
  const got = _adminTokenFromRequest(request, url);
  return !!got && got === expected;
}

function allowDevResetEndpoints(env) {
  return String(env?.ALLOW_DEV_RESET_ENDPOINTS || "").trim().toLowerCase() === "true";
}

