async function _publicMediaDriverExistsInScope(env, scope, driverId) {
  const normalizedDriverId = sanitizeTenantString(driverId, 96);
  if (!normalizedDriverId) return false;
  const index = await _loadDriverIndexRecord(env, scope);
  const drivers = index?.drivers && typeof index.drivers === "object" ? index.drivers : {};
  if (drivers[normalizedDriverId]) return true;
  return Object.values(drivers).some(
    (entry) =>
      sanitizeTenantString(entry?.driver_id ?? entry?.driverId, 96) === normalizedDriverId,
  );
}

const DRIVER_INDEX_KV_QUOTA_BACKOFF_MS = 60 * 1000;
const _driverIndexKvQuotaBackoffUntilByScopePayload = new Map();

function _driverIndexQuotaBackoffKey(scope, driversComparable) {
  const tenantId = sanitizeTenantString(scope?.tenant_id ?? scope?.tenantId, 80);
  const companyId = sanitizeTenantString(scope?.company_id ?? scope?.companyId, 80);
  if (!tenantId || !companyId) return "";
  const comparableRaw = stableStringifyForKvCompare(adminSyncComparable(driversComparable));
  let hash = 0;
  for (let i = 0; i < comparableRaw.length; i += 1) {
    hash = ((hash * 31) + comparableRaw.charCodeAt(i)) >>> 0;
  }
  return `${tenantId}:${companyId}:${comparableRaw.length}:${hash}`;
}

async function _saveDriverIndexRecord(env, scope, doc) {
  const key = _companyDriverIndexKey(scope);
  const scopeMasked =
    `${_maskPublicDriverLoginValue(scope?.tenant_id)}:${_maskPublicDriverLoginValue(scope?.company_id)}`;
  const existing = await env.BOOKING_KV.get(key, { type: "json" });
  const existingDrivers =
    existing && typeof existing === "object" && !Array.isArray(existing)
      ? (existing.drivers && typeof existing.drivers === "object" ? existing.drivers : {})
      : {};
  const existingDeletedDrivers =
    existing && typeof existing === "object" && !Array.isArray(existing)
      ? (existing.deleted_drivers && typeof existing.deleted_drivers === "object"
          ? existing.deleted_drivers
          : (existing.deletedDrivers && typeof existing.deletedDrivers === "object"
              ? existing.deletedDrivers
              : {}))
      : {};
  const nextDrivers =
    doc && typeof doc === "object" && !Array.isArray(doc) && doc.drivers && typeof doc.drivers === "object"
      ? doc.drivers
      : {};
  const nextDeletedDrivers =
    doc && typeof doc === "object" && !Array.isArray(doc) &&
    doc.deleted_drivers && typeof doc.deleted_drivers === "object"
      ? doc.deleted_drivers
      : (doc && typeof doc === "object" && !Array.isArray(doc) &&
          doc.deletedDrivers && typeof doc.deletedDrivers === "object"
          ? doc.deletedDrivers
          : {});
  if (
    kvComparableEqual(existingDrivers, nextDrivers) &&
    kvComparableEqual(existingDeletedDrivers, nextDeletedDrivers)
  ) {
    return { key, changed: false };
  }
  const existingCount = Object.keys(existingDrivers).length;
  const nextCount = Object.keys(nextDrivers).length;
  const diffReason = existingCount !== nextCount
    ? "driver_count_changed"
    : "driver_payload_changed";
  const backoffKey = _driverIndexQuotaBackoffKey(scope, nextDrivers);
  const backoffUntilMs = backoffKey
    ? Number(_driverIndexKvQuotaBackoffUntilByScopePayload.get(backoffKey) || 0)
    : 0;
  if (backoffUntilMs > Date.now()) {
    console.log(
      `[KV_WRITE][BACKOFF_SKIP] route=/admin/company/drivers/index/upsert scope=${scopeMasked}`,
    );
    const backoffError = new Error("kv_quota_backoff");
    backoffError.code = "kv_quota_backoff";
    throw backoffError;
  }
  console.log(
    `[KV_WRITE][DIFF_DETECTED] route=/admin/company/drivers/index/upsert scope=${scopeMasked} reason=${diffReason}`,
  );
  try {
    await env.BOOKING_KV.put(
      key,
      JSON.stringify({
        drivers: doc.drivers,
        deleted_drivers: nextDeletedDrivers,
        deletedDrivers: nextDeletedDrivers,
        updated_at: doc.updated_at,
      }),
    );
    if (backoffKey) _driverIndexKvQuotaBackoffUntilByScopePayload.delete(backoffKey);
  } catch (err) {
    const errText = sanitizeTenantString(err?.message ?? err, 180).toLowerCase();
    if (errText.includes("kv put() limit exceeded") || errText.includes("limit exceeded for the day")) {
      if (backoffKey) {
        _driverIndexKvQuotaBackoffUntilByScopePayload.set(
          backoffKey,
          Date.now() + DRIVER_INDEX_KV_QUOTA_BACKOFF_MS,
        );
      }
      console.log(
        `[KV_WRITE][FAILED_QUOTA] route=/admin/company/drivers/index/upsert scope=${scopeMasked}`,
      );
      const quotaError = new Error("kv_quota_exceeded");
      quotaError.code = "kv_quota_exceeded";
      throw quotaError;
    }
    throw err;
  }
  return { key, changed: true };
}

function _isCompanyLinkSmsProviderConfigured(env) {
  const provider = sanitizeTenantString(env?.COMPANY_LINK_SMS_PROVIDER, 32).toLowerCase();
  if (!provider) return false;
  // Future: wire a concrete provider implementation (e.g. Twilio) with strict validation.
  return false;
}

function _readCustomerPhoneAuthSmsConfig(env) {
  const provider = sanitizeTenantString(
    env?.CUSTOMER_PHONE_AUTH_SMS_PROVIDER,
    32,
  ).toLowerCase();
  const defaultUrl = "https://api.smsgatewayapi.com/v1/message/send";
  const url = sanitizeTenantString(env?.CUSTOMER_PHONE_AUTH_SMS_URL, 800) || defaultUrl;
  const clientId = sanitizeTenantString(
    env?.CUSTOMER_PHONE_AUTH_SMS_CLIENT_ID,
    240,
  );
  const clientSecret = sanitizeTenantString(
    env?.CUSTOMER_PHONE_AUTH_SMS_CLIENT_SECRET,
    480,
  );
  const from = sanitizeTenantString(env?.CUSTOMER_PHONE_AUTH_SMS_FROM, 80);
  const fromMode = from.toLowerCase();
  const providerDefaultSender = (
    fromMode === "__omit__" ||
    fromMode === "__default__" ||
    fromMode === "provider_default" ||
    fromMode === "omit" ||
    fromMode === "default"
  );
  return {
    provider,
    url,
    client_id: clientId,
    client_secret: clientSecret,
    from,
    sender_mode: providerDefaultSender ? "provider_default" : "explicit",
    use_provider_default_sender: providerDefaultSender,
    has_url: !!url,
    has_client_id: !!clientId,
    has_client_secret: !!clientSecret,
    has_from: providerDefaultSender ? true : !!from,
  };
}

function _isCustomerPhoneAuthSmsConfigured(env) {
  const cfg = _readCustomerPhoneAuthSmsConfig(env);
  return !!(
    cfg.has_url &&
    cfg.has_from &&
    cfg.has_client_id &&
    cfg.has_client_secret
  );
}

