function _publicHotelNormalizeText(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function _publicHotelMatchesQuery(stay, query) {
  const countryQuery = _publicHotelNormalizeText(query?.country);
  if (countryQuery) {
    const stayCountry = _publicHotelNormalizeText(stay?.country);
    if (!stayCountry.includes(countryQuery) && !countryQuery.includes(stayCountry)) {
      return false;
    }
  }

  const cityQuery = _publicHotelNormalizeText(query?.city);
  if (cityQuery) {
    const stayCity = _publicHotelNormalizeText(stay?.city);
    if (!stayCity.includes(cityQuery) && !cityQuery.includes(stayCity)) {
      return false;
    }
  }

  const latitude = query?.latitude;
  const longitude = query?.longitude;
  const radiusKm = query?.radiusKm;
  if (
    latitude != null &&
    longitude != null &&
    radiusKm != null &&
    Number.isFinite(stay?.lat) &&
    Number.isFinite(stay?.lng)
  ) {
    const distanceKm = _publicEventsHaversineKm(
      latitude,
      longitude,
      stay.lat,
      stay.lng,
    );
    if (distanceKm > radiusKm) return false;
  }

  return true;
}

function _publicHotelResponseImageUrl(raw) {
  const url = String(raw ?? "").trim();
  if (!url) return null;
  const lower = url.toLowerCase();
  if (!lower.startsWith("http://") && !lower.startsWith("https://")) return null;
  return url;
}

function _publicPartnerHotelHasApprovedVisual(stay) {
  if (_publicHotelResponseImageUrl(stay?.image_url)) return true;
  const imageRef = String(stay?.image_ref ?? "").trim();
  if (!imageRef.startsWith("partner_approved:")) return false;
  return imageRef.substring("partner_approved:".length).trim().length > 0;
}

// TODO(HOTELS-PROVIDER): Approved partner backend catalog
const PUBLIC_HOTELS_PARTNER_APPROVED_CATALOG_KEY =
  "public:hotels:partner-approved:v1";

function _publicHotelSanitizedExternalUrl(raw) {
  return _publicHotelResponseImageUrl(raw);
}

function _publicPartnerApprovedHttpsImageUrl(raw) {
  const url = _publicHotelResponseImageUrl(raw);
  if (!url) return null;
  if (!url.toLowerCase().startsWith("https://")) return null;
  return url;
}

function _publicHotelPartnerApprovedImageRef(raw) {
  const imageRef = String(raw ?? "").trim();
  if (!imageRef.startsWith("partner_approved:")) return null;
  const pathSuffix = imageRef.substring("partner_approved:".length).trim();
  if (!pathSuffix) return null;
  return imageRef;
}

function _publicHotelValidCoordinates(lat, lng) {
  const latitude = Number(lat);
  const longitude = Number(lng);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;
  if (latitude < -90 || latitude > 90) return null;
  if (longitude < -180 || longitude > 180) return null;
  return { lat: latitude, lng: longitude };
}

function _extractPartnerApprovedCatalogRows(raw) {
  if (Array.isArray(raw)) return raw;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return [];
  if (Array.isArray(raw.stays)) return raw.stays;
  if (Array.isArray(raw.entries)) return raw.entries;
  if (Array.isArray(raw.items)) return raw.items;
  return [];
}

function _readPartnerApprovedCatalogString(row, keys) {
  if (!row || typeof row !== "object" || Array.isArray(row)) return "";
  for (const key of keys) {
    const value = row[key];
    if (value == null) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return "";
}

function _readPartnerApprovedCatalogNumber(row, keys) {
  if (!row || typeof row !== "object" || Array.isArray(row)) return null;
  for (const key of keys) {
    const value = row[key];
    if (value == null) continue;
    if (typeof value === "number" && Number.isFinite(value)) return value;
    const parsed = Number(String(value).trim());
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function _sanitizePartnerApprovedCatalogEntry(row) {
  if (!row || typeof row !== "object" || Array.isArray(row)) return null;

  const id = _readPartnerApprovedCatalogString(row, ["id"]);
  const name = _readPartnerApprovedCatalogString(row, ["name"]);
  if (!id || !name) return null;

  const coords = _publicHotelValidCoordinates(
    _readPartnerApprovedCatalogNumber(row, ["lat", "latitude"]),
    _readPartnerApprovedCatalogNumber(row, ["lng", "longitude"]),
  );
  if (!coords) return null;

  const imageUrl = _publicPartnerApprovedHttpsImageUrl(
    _readPartnerApprovedCatalogString(row, ["image_url", "imageUrl"]),
  );
  const imageRef = _publicHotelPartnerApprovedImageRef(
    _readPartnerApprovedCatalogString(row, ["image_ref", "imageRef"]),
  );
  if (!imageUrl && !imageRef) return null;

  const externalUrlRaw = _readPartnerApprovedCatalogString(row, [
    "external_url",
    "externalUrl",
    "external_availability_url",
    "externalAvailabilityUrl",
  ]);
  const externalUrl = externalUrlRaw
    ? _publicHotelSanitizedExternalUrl(externalUrlRaw)
    : null;

  const providerId =
    _readPartnerApprovedCatalogString(row, [
      "provider_id",
      "providerId",
      "source_id",
      "sourceId",
    ]) || id;
  const rating =
    _readPartnerApprovedCatalogString(row, ["rating_label", "ratingLabel", "rating"]) ||
    null;
  const priceHint =
    _readPartnerApprovedCatalogString(row, [
      "price_label",
      "priceLabel",
      "price_hint",
      "priceHint",
    ]) || null;
  const availabilityLabel =
    _readPartnerApprovedCatalogString(row, [
      "availability_label",
      "availabilityLabel",
    ]) || null;

  return {
    id,
    name,
    type: _readPartnerApprovedCatalogString(row, ["type"]) || "hotel",
    address: _readPartnerApprovedCatalogString(row, ["address"]),
    city: _readPartnerApprovedCatalogString(row, ["city"]),
    region: _readPartnerApprovedCatalogString(row, ["region"]),
    country: _readPartnerApprovedCatalogString(row, ["country"]),
    lat: coords.lat,
    lng: coords.lng,
    image_url: imageUrl,
    image_ref: imageRef,
    source_id: providerId,
    rating,
    price_hint: priceHint,
    availability_label: availabilityLabel,
    external_url: externalUrl,
    provider: "partner-approved",
    source: "partner_approved",
    is_real_approved: true,
  };
}

async function _loadPublicHotelsPartnerApprovedCatalogDocument(env) {
  if (!env?.BOOKING_KV) {
    return {
      document: null,
      warnings: ["partner_catalog_kv_unavailable"],
    };
  }
  try {
    const document = await env.BOOKING_KV.get(
      PUBLIC_HOTELS_PARTNER_APPROVED_CATALOG_KEY,
      { type: "json" },
    );
    if (!document) {
      return { document: null, warnings: [] };
    }
    if (typeof document !== "object" || Array.isArray(document)) {
      return {
        document: null,
        warnings: ["partner_catalog_malformed"],
      };
    }
    return { document, warnings: [] };
  } catch (_) {
    return {
      document: null,
      warnings: ["partner_catalog_load_failed"],
    };
  }
}

async function _loadPublicHotelsPartnerApprovedCatalogStays(env) {
  const { document, warnings } =
    await _loadPublicHotelsPartnerApprovedCatalogDocument(env);
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];
  const rawRows = _extractPartnerApprovedCatalogRows(document);
  const stays = [];
  for (const row of rawRows) {
    const sanitized = _sanitizePartnerApprovedCatalogEntry(row);
    if (!sanitized) continue;
    if (!_publicPartnerHotelHasApprovedVisual(sanitized)) continue;
    stays.push(sanitized);
  }
  return {
    stays,
    warnings: nextWarnings,
    rawRowCount: rawRows.length,
    catalogVersion:
      document && document.version != null ? String(document.version) : null,
    updatedAt:
      _readPartnerApprovedCatalogString(document, ["updated_at", "updatedAt"]) ||
      null,
  };
}

async function _buildAdminPartnerApprovedHotelsCatalogDiagnostics({ env } = {}) {
  const loadResult = await _loadPublicHotelsPartnerApprovedCatalogStays(env);
  const stays = loadResult.stays.map((stay) => _mapPublicHotelStayToResponse(stay));
  const warnings = Array.isArray(loadResult.warnings) ? [...loadResult.warnings] : [];
  if (!stays.length && !warnings.includes("partner_catalog_empty")) {
    warnings.push("partner_catalog_empty");
  }
  return {
    ok: true,
    kv_key: PUBLIC_HOTELS_PARTNER_APPROVED_CATALOG_KEY,
    catalog_present: loadResult.rawRowCount > 0,
    catalog_version: loadResult.catalogVersion,
    updated_at: loadResult.updatedAt,
    raw_row_count: loadResult.rawRowCount,
    trusted_row_count: stays.length,
    warnings,
    sample_ids: stays.slice(0, 12).map((stay) => stay.id),
    stays,
  };
}

function _publicHotelsProviderConfigured(env, requiredNames) {
  return _publicHotelsProviderEnvReady(env, requiredNames);
}

function _adminConfiguredNativeProviderStatus(env, requiredKeys) {
  const configured = _publicHotelsProviderConfigured(env, requiredKeys);
  return {
    configured,
    role: "native_inventory",
    status: configured ? "provider_adapter_pending" : "provider_not_configured",
  };
}

function _adminExpediaRapidProviderStatus(env) {
  const configured = _publicHotelsProviderConfigured(env, [
    "EXPEDIA_RAPID_API_KEY",
    "EXPEDIA_RAPID_API_SECRET",
  ]);
  if (!configured) {
    return {
      configured: false,
      role: "native_inventory",
      status: "provider_not_configured",
    };
  }
  return {
    configured: true,
    role: "native_inventory",
    status: _expediaRapidAuthSigningReady(env) ? "ready" : "provider_adapter_pending",
  };
}

// Booking.com CJ: affiliate/deeplink handoff only — never Demand API, iframe, scraping, or fake inventory.
function _adminBookingComCjProviderStatus(env) {
  const baseUrl = safeStr(env?.BOOKING_COM_CJ_BASE_URL);
  const enabledRaw = safeStr(env?.BOOKING_COM_CJ_ENABLED, 24).toLowerCase();
  const statusRaw = safeStr(env?.BOOKING_COM_CJ_STATUS, 64).toLowerCase();
  const role = "affiliate_deeplink_pending_or_fallback";
  const explicitlyDisabled = enabledRaw === "false" || enabledRaw === "0";
  const hasBaseUrl = Boolean(baseUrl);

  if (hasBaseUrl && !explicitlyDisabled) {
    return {
      configured: true,
      role,
      status: statusRaw === "configured" ? "configured" : "pending_review",
    };
  }
  if (statusRaw === "pending_review") {
    return { configured: false, role, status: "pending_review" };
  }
  return { configured: false, role, status: "provider_not_configured" };
}

function _bookingComCjAffiliateSearchUrl(query, env) {
  const baseUrl = safeStr(env?.BOOKING_COM_CJ_BASE_URL);
  if (!baseUrl) return null;
  try {
    const url = new URL(baseUrl);
    const city = String(query?.city ?? "").trim();
    const country = String(query?.country ?? "").trim();
    const searchQuery = [city, country].filter(Boolean).join(", ");
    if (searchQuery) url.searchParams.set("ss", searchQuery.slice(0, 200));
    return url.toString();
  } catch (_) {
    return null;
  }
}

function _buildBookingComCjHotelsPayload({ query, env, warnings = [] } = {}) {
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];
  const source = "booking-com-cj";
  const provider = "booking-com-cj";
  const providerStatus = _adminBookingComCjProviderStatus(env);

  if (!providerStatus.configured || providerStatus.status !== "configured") {
    if (providerStatus.status === "pending_review") {
      if (!nextWarnings.includes("booking_com_cj_pending_review")) {
        nextWarnings.push("booking_com_cj_pending_review");
      }
    } else if (!nextWarnings.includes("provider_not_configured")) {
      nextWarnings.push("provider_not_configured");
    }
    return {
      ok: true,
      source,
      provider,
      count: 0,
      stays: [],
      warnings: nextWarnings,
    };
  }

  const availabilityExternalUrl = _publicHotelSanitizedExternalUrl(
    _bookingComCjAffiliateSearchUrl(query, env),
  );
  const payload = {
    ok: true,
    source,
    provider,
    count: 0,
    stays: [],
    warnings: nextWarnings,
  };
  if (availabilityExternalUrl) {
    payload.availability_external_url = availabilityExternalUrl;
  }
  return payload;
}

// Google Places: official place discovery/photos only — not booking inventory, no scraping, no stored photos.
function _adminGooglePlacesHotelsProviderStatus(env) {
  const configured = Boolean(safeStr(env?.GOOGLE_PLACES_API_KEY));
  return {
    configured,
    role: "native_place_discovery",
    status: configured ? "configured" : "provider_not_configured",
  };
}

function _googlePlacesApiKeyReady(env) {
  return Boolean(safeStr(env?.GOOGLE_PLACES_API_KEY));
}

function _publicHotelsRequestOrigin(requestUrl) {
  try {
    return new URL(String(requestUrl || "")).origin;
  } catch (_) {
    return "";
  }
}

function _sanitizeGooglePlacePhotoName(raw) {
  const name = String(raw ?? "").trim();
  if (/^legacy:[A-Za-z0-9_-]{8,600}$/.test(name)) return name;
  if (!/^places\/[\w-]+\/photos\/[\w-]+$/.test(name)) return null;
  return name;
}

function _googlePlacesDisplayName(place) {
  const displayName = place?.displayName;
  if (typeof displayName === "string") return displayName.trim();
  if (displayName && typeof displayName.text === "string") {
    return displayName.text.trim();
  }
  return "";
}

function _googlePlacesRatingLabel(place) {
  const rating = place?.rating;
  if (typeof rating !== "number" || !Number.isFinite(rating)) return null;
  const count = place?.userRatingCount;
  if (typeof count === "number" && Number.isFinite(count) && count > 0) {
    return `${rating.toFixed(1)} (${Math.trunc(count)})`;
  }
  return rating.toFixed(1);
}

function _googlePlacesPrimaryPhotoMeta(place) {
  const photos = Array.isArray(place?.photos) ? place.photos : [];
  if (!photos.length) return { photoName: null, attribution: null };
  const photo = photos[0] ?? {};
  const photoName = String(photo?.name ?? "").trim();
  const attrs = Array.isArray(photo?.authorAttributions)
    ? photo.authorAttributions
    : [];
  const first = attrs[0] ?? {};
  const attribution = String(first?.displayName ?? first?.display_name ?? "").trim();
  return {
    photoName: photoName || null,
    attribution: attribution || null,
  };
}

function _googlePlacesHotelType(place, query) {
  const types = Array.isArray(place?.types)
    ? place.types.map((entry) => String(entry ?? "").toLowerCase())
    : [];
  const primary = String(place?.primaryType ?? "").trim().toLowerCase();
  const all = [...types, primary].filter(Boolean);
  if (all.some((entry) => entry.includes("bed_and_breakfast") || entry === "bnb")) {
    return "b&b";
  }
  if (all.some((entry) => entry.includes("guest_house") || entry.includes("guesthouse"))) {
    return "guesthouse";
  }
  const searchText = String(query?.searchText ?? "").toLowerCase();
  if (searchText.includes("bed and breakfast") || searchText.includes("b&b")) {
    return "b&b";
  }
  return "hotel";
}

function _googlePlacesBuildTextQuery(query) {
  const explicit = String(query?.searchText ?? "").trim();
  if (explicit) return explicit.slice(0, 200);
  const city = String(query?.city ?? "").trim();
  const region = String(query?.region ?? "").trim();
  const country = String(query?.country ?? "").trim();
  if (city && country) return `hotels in ${city}, ${country}`;
  if (city) return `hotels in ${city}`;
  if (region && country) return `bed and breakfast in ${region}, ${country}`;
  if (region) return `hotels in ${region}`;
  if (country) return `hotels in ${country}`;
  return "hotels in Belgium";
}

function _googlePlacesPhotoProxyAbsoluteUrl(origin, photoName) {
  const safeName = _sanitizeGooglePlacePhotoName(photoName);
  if (!safeName || !origin) return null;
  return `${origin}/public/hotels/google-place-photo?photo_name=${encodeURIComponent(safeName)}`;
}

function _googlePlacesDedupePlaces(places) {
  const out = [];
  const seen = new Set();
  for (const place of Array.isArray(places) ? places : []) {
    const id = String(place?.id ?? place?.name ?? "").trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(place);
  }
  return out;
}

function _legacyGooglePlacesNumberOrNull(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function _googlePlacesLegacyRatingText(ratingRaw, countRaw) {
  const rating = Number(ratingRaw);
  if (!Number.isFinite(rating) || rating <= 0) return null;

  const count = Number(countRaw);
  if (Number.isFinite(count) && count > 0) {
    return `${rating.toFixed(1)} (${Math.trunc(count)})`;
  }

  return rating.toFixed(1);
}
function _legacyGooglePlacesPhotoReference(raw) {
  const text = safeStr(raw, 600).trim();
  if (!text) return "";
  if (!/^[A-Za-z0-9_-]{8,600}$/.test(text)) return "";
  return text;
}

function _legacyGooglePlacesPhotoList(place) {
  const photos = Array.isArray(place?.photos) ? place.photos : [];
  const out = [];
  for (const photo of photos) {
    const ref = _legacyGooglePlacesPhotoReference(photo?.photo_reference);
    if (!ref) continue;
    const attributionItems = Array.isArray(photo?.html_attributions)
      ? photo.html_attributions
      : [];
    const attributionText = attributionItems
      .map((entry) => safeStr(entry, 240).replace(/<[^>]*>/g, "").trim())
      .filter(Boolean)
      .join(", ");
    out.push({
      name: `legacy:${ref}`,
      authorAttributions: attributionText
        ? [{ displayName: attributionText }]
        : [],
    });
    if (out.length >= 1) break;
  }
  return out;
}
function _legacyGooglePlacesMapResultToV1Like(place) {
  const placeId = safeStr(place?.place_id);
  const name = safeStr(place?.name);
  if (!placeId || !name) return null;

  const lat = _legacyGooglePlacesNumberOrNull(place?.geometry?.location?.lat);
  const lng = _legacyGooglePlacesNumberOrNull(place?.geometry?.location?.lng);
  const types = Array.isArray(place?.types)
    ? place.types.map((entry) => safeStr(entry)).filter(Boolean)
    : ["lodging"];

  return {
    id: placeId,
    displayName: { text: name },
    formattedAddress: safeStr(place?.formatted_address || place?.vicinity),
    location: lat != null && lng != null ? { latitude: lat, longitude: lng } : undefined,
    rating: _legacyGooglePlacesNumberOrNull(place?.rating),
    userRatingCount: _legacyGooglePlacesNumberOrNull(place?.user_ratings_total),
    ratingLabel: _googlePlacesLegacyRatingText(place?.rating, place?.user_ratings_total),
    primaryType: types[0] || "lodging",
    types: types.length ? types : ["lodging"],
    photos: _legacyGooglePlacesPhotoList(place),
  };
}

function _legacyGooglePlacesResultsToV1Like(payload, source) {
  const status = safeStr(payload?.status);
  if (status && status !== "OK" && status !== "ZERO_RESULTS") {
    console.warn("[PUBLIC_HOTELS][GOOGLE_PLACES_LEGACY][STATUS]", JSON.stringify({
      source,
      status,
      error_message: safeStr(payload?.error_message).slice(0, 240),
    }));
  }

  if (!Array.isArray(payload?.results)) return [];
  return payload.results
    .map((place) => _legacyGooglePlacesMapResultToV1Like(place))
    .filter(Boolean);
}

async function _googlePlacesLegacyTextSearch({ query, apiKey }) {
  const textQuery = _googlePlacesBuildTextQuery(query);
  const url = new URL("https://maps.googleapis.com/maps/api/place/textsearch/json");
  url.searchParams.set("query", textQuery);
  url.searchParams.set("type", "lodging");
  url.searchParams.set("key", apiKey);

  const res = await fetch(url.toString());
  if (!res.ok) {
    console.warn("[PUBLIC_HOTELS][GOOGLE_PLACES_LEGACY][TEXT_HTTP_NOT_OK]", JSON.stringify({
      status: res.status,
      statusText: res.statusText,
    }));
    return [];
  }

  const payload = await res.json().catch(() => null);
  return _legacyGooglePlacesResultsToV1Like(payload, "textsearch");
}

async function _googlePlacesLegacyNearbySearch({ query, apiKey }) {
  const latitude = query?.latitude;
  const longitude = query?.longitude;
  if (latitude == null || longitude == null) return [];

  const radiusMeters = Math.max(
    1000,
    Math.min(50000, Math.round((query?.radiusKm ?? 25) * 1000)),
  );

  const url = new URL("https://maps.googleapis.com/maps/api/place/nearbysearch/json");
  url.searchParams.set("location", `${latitude},${longitude}`);
  url.searchParams.set("radius", String(radiusMeters));
  url.searchParams.set("type", "lodging");
  url.searchParams.set("key", apiKey);

  const res = await fetch(url.toString());
  if (!res.ok) {
    console.warn("[PUBLIC_HOTELS][GOOGLE_PLACES_LEGACY][NEARBY_HTTP_NOT_OK]", JSON.stringify({
      status: res.status,
      statusText: res.statusText,
    }));
    return [];
  }

  const payload = await res.json().catch(() => null);
  return _legacyGooglePlacesResultsToV1Like(payload, "nearbysearch");
}
async function _googlePlacesSearchNearby({ query, apiKey, fieldMask }) {
  return await _googlePlacesLegacyNearbySearch({ query, apiKey });
}
async function _googlePlacesSearchText({ query, apiKey, fieldMask }) {
  return await _googlePlacesLegacyTextSearch({ query, apiKey });
}
function _googlePlacesAddressParts(address) {
  const text = safeStr(address, 400).trim();
  if (!text) return { city: "", country: "" };

  const parts = text
    .split(",")
    .map((part) => safeStr(part, 120).trim())
    .filter(Boolean);

  const last = parts.length ? parts[parts.length - 1] : "";
  const country = /belgium|belgië|belgique/i.test(last) ? "BE" : "";

  let city = "";
  if (parts.length >= 2) {
    const beforeCountry = country ? parts[parts.length - 2] : parts[parts.length - 1];
    city = beforeCountry
      .replace(/^\d{4,5}\s+/, "")
      .replace(/\s*\d{4,5}$/, "")
      .trim();
  }

  return { city, country };
}

function _googlePlacesCountryCodeFromCoordinates(query) {
  const lat = Number(query?.latitude ?? query?.lat);
  const lng = Number(query?.longitude ?? query?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return "";

  // Market-safe coarse bounding boxes for discovery metadata only.
  if (lat >= 49.45 && lat <= 51.55 && lng >= 2.45 && lng <= 6.45) return "BE";
  if (lat >= 50.65 && lat <= 53.75 && lng >= 3.20 && lng <= 7.30) return "NL";
  if (lat >= 41.20 && lat <= 51.25 && lng >= -5.50 && lng <= 9.65) return "FR";
  if (lat >= 47.20 && lat <= 55.10 && lng >= 5.85 && lng <= 15.05) return "DE";
  if (lat >= 35.80 && lat <= 43.90 && lng >= -9.50 && lng <= 4.40) return "ES";
  if (lat >= 49.80 && lat <= 59.00 && lng >= -8.70 && lng <= 1.90) return "GB";

  return "";
}
function _googlePlacesQueryCountryCode(query) {
  const raw = safeStr(query?.country, 32).trim();
  if (!raw) return "";
  const upper = raw.toUpperCase();
  if (upper === "BE" || upper === "BELGIUM" || upper === "BELGIË" || upper === "BELGIQUE") {
    return "BE";
  }
  return upper.replace(/[^A-Z]/g, "").slice(0, 2);
}

function _googlePlacesLegacyRatingLabel(place) {
  const explicit = safeStr(place?.ratingLabel ?? place?.rating_label, 80).trim();
  if (explicit) return explicit;

  const rating = Number(place?.rating ?? place?.ratingAvg ?? place?.rating_avg);
  const count = Number(
    place?.userRatingCount ??
      place?.user_rating_count ??
      place?.user_ratings_total ??
      place?.ratingCount ??
      place?.rating_count ??
      place?.reviewsCount ??
      place?.reviews_count,
  );

  return _googlePlacesLegacyRatingText(rating, count);
}
function _mapGooglePlaceToPublicHotelStay(place, { query, requestUrl } = {}) {
  const placeResourceId = String(place?.id ?? place?.name ?? "").trim();
  const providerId = placeResourceId.replace(/^places\//, "");
  const name = _googlePlacesDisplayName(place);
  if (!providerId || !name) return null;

  const location = place?.location ?? {};
  const lat = Number(location?.latitude);
  const lng = Number(location?.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  const address = String(place?.formattedAddress ?? "").trim();
  const addressParts = _googlePlacesAddressParts(address);
  const city = String(query?.city ?? "").trim() || addressParts.city;
  const region = String(query?.region ?? "").trim();
  const country = _googlePlacesQueryCountryCode(query) || addressParts.country || _googlePlacesCountryCodeFromCoordinates(query);
  const { photoName, attribution } = _googlePlacesPrimaryPhotoMeta(place);
  const origin = _publicHotelsRequestOrigin(requestUrl);
  const imageUrl = photoName
    ? _googlePlacesPhotoProxyAbsoluteUrl(origin, photoName)
    : null;

  return {
    id: `google_places:${providerId}`,
    provider: "google-places",
    provider_id: providerId,
    provider_label: "Real place discovery",
    name,
    type: _googlePlacesHotelType(place, query),
    address,
    city,
    region,
    country,
    lat,
    lng,
    image_url: imageUrl,
    image_ref: null,
    rating_label: _googlePlacesLegacyRatingLabel(place) || _googlePlacesRatingLabel(place),
    price_label: null,
    availability_label: "Live place discovery",
    external_url: null,
    photo_attribution: attribution,
    source: "google_places",
    is_real_approved: true,
  };
}

function _buildGooglePlacesNotConfiguredPayload({ warnings = [] } = {}) {
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];
  if (!nextWarnings.includes("google_places_not_configured")) {
    nextWarnings.push("google_places_not_configured");
  }
  return {
    ok: true,
    source: "google-places",
    provider: "google-places",
    count: 0,
    stays: [],
    warnings: nextWarnings,
  };
}

async function _buildGooglePlacesHotelsPayload({
  query,
  env,
  warnings = [],
  requestUrl = "",
} = {}) {
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];
  if (!_googlePlacesApiKeyReady(env)) {
    return _buildGooglePlacesNotConfiguredPayload({ warnings: nextWarnings });
  }

  const apiKey = safeStr(env?.GOOGLE_PLACES_API_KEY);
  const fieldMask =
    "places.id,places.displayName,places.formattedAddress,places.location,places.rating,places.userRatingCount,places.photos,places.primaryType,places.types";

  try {
    let places = [];
    if (query?.latitude != null && query?.longitude != null) {
      places = await _googlePlacesSearchNearby({ query, apiKey, fieldMask });
    }
    if (!places.length) {
      places = await _googlePlacesSearchText({ query, apiKey, fieldMask });
    }
    places = _googlePlacesDedupePlaces(places).slice(0, 20);

    const stays = [];
    for (const place of places) {
      const mapped = _mapGooglePlaceToPublicHotelStay(place, { query, requestUrl });
      if (!mapped) continue;
      stays.push(_mapPublicHotelStayToResponse(mapped));
    }

    return {
      ok: true,
      source: "google-places",
      provider: "google-places",
      count: stays.length,
      stays,
      warnings: nextWarnings,
    };
  } catch (_) {
    if (!nextWarnings.includes("google_places_fetch_failed")) {
      nextWarnings.push("google_places_fetch_failed");
    }
    return {
      ok: true,
      source: "google-places",
      provider: "google-places",
      count: 0,
      stays: [],
      warnings: nextWarnings,
    };
  }
}

async function _handlePublicGooglePlacePhoto(_request, url, env) {
  if (!_googlePlacesApiKeyReady(env)) {
    return json({ ok: false, error: "google_places_not_configured" }, 503);
  }
  const photoName = _sanitizeGooglePlacePhotoName(url.searchParams.get("photo_name"));
  if (!photoName) {
    return json({ ok: false, error: "invalid_photo_name" }, 400);
  }
  const apiKey = safeStr(env?.GOOGLE_PLACES_API_KEY);
  const legacyPhotoReference = photoName.startsWith("legacy:")
    ? photoName.slice("legacy:".length)
    : "";

  const mediaUrl = legacyPhotoReference
    ? `https://maps.googleapis.com/maps/api/place/photo?maxwidth=800&photo_reference=${encodeURIComponent(legacyPhotoReference)}&key=${encodeURIComponent(apiKey)}`
    : `https://places.googleapis.com/v1/${photoName}/media?maxHeightPx=600&maxWidthPx=800`;

  try {
    const upstream = await fetch(
      mediaUrl,
      legacyPhotoReference
        ? { redirect: "follow" }
        : {
            headers: { "X-Goog-Api-Key": apiKey },
            redirect: "follow",
          },
    );
    if (!upstream.ok) {
      return json({ ok: false, error: "photo_unavailable" }, 502);
    }
    const contentType = upstream.headers.get("content-type") || "image/jpeg";
    return new Response(upstream.body, {
      status: 200,
      headers: {
        "Content-Type": contentType,
        "Cache-Control": "public, max-age=86400",
      },
    });
  } catch (_) {
    return json({ ok: false, error: "photo_fetch_failed" }, 502);
  }
}

function _adminPartnerApprovedProviderStatus(loadResult) {
  const trustedCount = Array.isArray(loadResult?.stays) ? loadResult.stays.length : 0;
  const catalogPresent = Number(loadResult?.rawRowCount || 0) > 0;
  const loadWarnings = Array.isArray(loadResult?.warnings) ? loadResult.warnings : [];

  let status = "partner_catalog_empty";
  if (loadWarnings.includes("partner_catalog_malformed")) {
    status = "partner_catalog_malformed";
  } else if (loadWarnings.includes("partner_catalog_kv_unavailable")) {
    status = "partner_catalog_kv_unavailable";
  } else if (loadWarnings.includes("partner_catalog_load_failed")) {
    status = "partner_catalog_load_failed";
  } else if (trustedCount > 0) {
    status = "ready";
  }

  return {
    configured: true,
    role: "native_inventory_catalog",
    catalog_present: catalogPresent,
    trusted_count: trustedCount,
    status,
  };
}

async function _buildAdminHotelsProvidersStatusPayload(env) {
  const loadResult = await _loadPublicHotelsPartnerApprovedCatalogStays(env);
  const expediaRapid = _adminExpediaRapidProviderStatus(env);
  const partnerApproved = _adminPartnerApprovedProviderStatus(loadResult);
  const hotelbeds = _adminConfiguredNativeProviderStatus(env, [
    "HOTELBEDS_API_KEY",
    "HOTELBEDS_API_SECRET",
  ]);
  const amadeusHospitality = _adminConfiguredNativeProviderStatus(env, [
    "AMADEUS_API_KEY",
    "AMADEUS_API_SECRET",
  ]);
  const stay22 = {
    configured: true,
    role: "affiliate_deeplink_fallback",
    status: "flutter_fallback",
  };
  const bookingComCj = _adminBookingComCjProviderStatus(env);
  const googlePlacesHotels = _adminGooglePlacesHotelsProviderStatus(env);

  const nativeReady =
    expediaRapid.configured === true ||
    partnerApproved.trusted_count > 0 ||
    hotelbeds.configured === true ||
    amadeusHospitality.configured === true ||
    googlePlacesHotels.configured === true;

  const warnings = [];
  for (const warning of loadResult.warnings || []) {
    if (warning && !warnings.includes(warning)) {
      warnings.push(warning);
    }
  }
  if (
    partnerApproved.status === "partner_catalog_empty" &&
    !warnings.includes("partner_catalog_empty")
  ) {
    warnings.push("partner_catalog_empty");
  }

  return {
    ok: true,
    native_ready: nativeReady,
    providers: {
      expedia_rapid: expediaRapid,
      partner_approved: partnerApproved,
      hotelbeds,
      amadeus_hospitality: amadeusHospitality,
      stay22,
      booking_com_cj: bookingComCj,
      google_places_hotels: googlePlacesHotels,
    },
    warnings,
  };
}

async function _buildPartnerApprovedHotelsPayloadAsync({
  query,
  env,
  warnings = [],
} = {}) {
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];
  const loadResult = await _loadPublicHotelsPartnerApprovedCatalogStays(env);
  for (const warning of loadResult.warnings || []) {
    if (warning && !nextWarnings.includes(warning)) {
      nextWarnings.push(warning);
    }
  }
  const seedStays = loadResult.stays;
  const filtered = seedStays.filter((stay) =>
    _publicHotelMatchesQuery(stay, query),
  );
  const stays = filtered.map((stay) => _mapPublicHotelStayToResponse(stay));
  if (!stays.length) {
    if (!nextWarnings.includes("partner_catalog_empty")) {
      nextWarnings.push("partner_catalog_empty");
    }
  }
  return {
    ok: true,
    source: "partner-approved",
    provider: "partner-approved",
    count: stays.length,
    stays,
    warnings: nextWarnings,
  };
}

