function _mapPublicHotelStayToResponse(stay) {
  const ratingSource =
    stay?.rating_label ??
    stay?.ratingLabel ??
    stay?.rating;

  const rating =
    ratingSource == null || ratingSource === ""
      ? null
      : String(ratingSource).trim();
  return {
    id: String(stay?.id ?? "").trim(),
    provider: String(stay?.provider ?? "approved-local").trim() || "approved-local",
    provider_id:
      String(stay?.source_id ?? stay?.id ?? "").trim() ||
      String(stay?.id ?? "").trim(),
    name: String(stay?.name ?? "").trim(),
    type: String(stay?.type ?? "hotel").trim() || "hotel",
    address: String(stay?.address ?? "").trim(),
    city: String(stay?.city ?? "").trim(),
    region: String(stay?.region ?? "").trim(),
    country: String(stay?.country ?? "").trim(),
    lat: Number(stay?.lat),
    lng: Number(stay?.lng),
    image_url: _publicHotelResponseImageUrl(stay?.image_url),
    image_ref: stay?.image_ref ? String(stay.image_ref).trim() : null,
    rating_label: rating,
    price_label: stay?.price_hint ? String(stay.price_hint).trim() : null,
    availability_label: stay?.availability_label
      ? String(stay.availability_label).trim()
      : null,
    external_url: _publicHotelSanitizedExternalUrl(stay?.external_url),
    provider_label: stay?.provider_label ? String(stay.provider_label).trim() : null,
    photo_attribution: stay?.photo_attribution
      ? String(stay.photo_attribution).trim()
      : null,
    source: String(stay?.source ?? "approved_local").trim() || "approved_local",
    is_real_approved: stay?.is_real_approved === true,
  };
}

function _publicHotelsProviderEnvReady(env, requiredKeys) {
  const keys = Array.isArray(requiredKeys) ? requiredKeys : [];
  for (const key of keys) {
    const value = safeStr(env?.[key]);
    if (!value) return false;
  }
  return keys.length > 0;
}

