function _buildHotelbedsHotelsPayload({ query, env, warnings = [] } = {}) {
  const source = "hotelbeds";
  // TODO(HOTELS-PROVIDER-HOTELBEDS): Select Hotelbeds content/search endpoint for property discovery.
  // TODO(HOTELS-PROVIDER-HOTELBEDS): Add availability/shopping endpoint for price_label/availability_label.
  // TODO(HOTELS-PROVIDER-HOTELBEDS): Confirm image licensing/CDN trust before exposing image_url in-app.
  // TODO(HOTELS-PROVIDER-HOTELBEDS): Map Hotelbeds property codes to provider_id via _mapPublicHotelStayToResponse.
  // TODO(HOTELS-PROVIDER-HOTELBEDS): Handle pagination and rate limiting safely.
  // Planned base URL helper: _hotelbedsBaseUrl(env) — default https://api.hotelbeds.com
  if (
    !_publicHotelsProviderEnvReady(env, [
      "HOTELBEDS_API_KEY",
      "HOTELBEDS_API_SECRET",
    ])
  ) {
    return _buildProviderNotConfiguredHotelsPayload({ source, warnings });
  }
  return _buildProviderAdapterPendingHotelsPayload({ source, warnings });
}

function _buildAmadeusHotelsPayload({ query, env, warnings = [] } = {}) {
  const source = "amadeus-hospitality";
  // TODO(HOTELS-PROVIDER-AMADEUS): Select Amadeus hotel content/search endpoint for property discovery.
  // TODO(HOTELS-PROVIDER-AMADEUS): Add availability/shopping endpoint for price_label/availability_label.
  // TODO(HOTELS-PROVIDER-AMADEUS): Confirm image licensing/media trust before exposing image_url in-app.
  // TODO(HOTELS-PROVIDER-AMADEUS): Map Amadeus property ids to provider_id via _mapPublicHotelStayToResponse.
  // TODO(HOTELS-PROVIDER-AMADEUS): Handle pagination and rate limiting safely.
  // Planned base URL helper: _amadeusBaseUrl(env) — default https://api.amadeus.com
  if (
    !_publicHotelsProviderEnvReady(env, [
      "AMADEUS_API_KEY",
      "AMADEUS_API_SECRET",
    ])
  ) {
    return _buildProviderNotConfiguredHotelsPayload({ source, warnings });
  }
  return _buildProviderAdapterPendingHotelsPayload({ source, warnings });
}

async function _buildNativeHotelsSearchPayload({ query, env, warnings = [] } = {}) {
  const nextWarnings = Array.isArray(warnings) ? [...warnings] : [];

  if (
    _publicHotelsProviderEnvReady(env, [
      "EXPEDIA_RAPID_API_KEY",
      "EXPEDIA_RAPID_API_SECRET",
    ])
  ) {
    return await _buildExpediaRapidHotelsPayload({
      query,
      env,
      warnings: nextWarnings,
    });
  }

  if (_publicHotelsPartnerApprovedCatalogReadyAsync(env)) {
    return await _buildPartnerApprovedHotelsPayloadAsync({
      query,
      env,
      warnings: nextWarnings,
    });
  }

  if (
    _publicHotelsProviderEnvReady(env, [
      "HOTELBEDS_API_KEY",
      "HOTELBEDS_API_SECRET",
    ])
  ) {
    return _buildHotelbedsHotelsPayload({
      query,
      env,
      warnings: nextWarnings,
    });
  }

  if (
    _publicHotelsProviderEnvReady(env, [
      "AMADEUS_API_KEY",
      "AMADEUS_API_SECRET",
    ])
  ) {
    return _buildAmadeusHotelsPayload({
      query,
      env,
      warnings: nextWarnings,
    });
  }

  if (!nextWarnings.includes("native_provider_unavailable")) {
    nextWarnings.push("native_provider_unavailable");
  }
  return _buildProviderNotConfiguredHotelsPayload({
    source: "native",
    warnings: nextWarnings,
  });
}

async function _buildPublicHotelsSearchPayload({ query, env, requestUrl = "" } = {}) {
  const source = String(query?.source ?? "approved-local").trim() || "approved-local";
  const warnings = Array.isArray(query?.warnings) ? [...query.warnings] : [];

  if (source === "approved-local") {
    return _buildApprovedLocalHotelsPayload({ query, warnings });
  }

  if (source === "partner-approved") {
    return await _buildPartnerApprovedHotelsPayloadAsync({ query, env, warnings });
  }

  if (source === "native") {
    return await _buildNativeHotelsSearchPayload({ query, env, warnings });
  }

  if (source === "google-places" || source === "places") {
    return await _buildGooglePlacesHotelsPayload({
      query,
      env,
      warnings,
      requestUrl,
    });
  }

  if (source === "travelpayouts") {
    return _buildTravelpayoutsHotelsPayload({ query, env, warnings });
  }

  if (source === "expedia-rapid") {
    return await _buildExpediaRapidHotelsPayload({ query, env, warnings });
  }

  if (source === "hotelbeds") {
    return _buildHotelbedsHotelsPayload({ query, env, warnings });
  }

  if (source === "amadeus-hospitality" || source === "amadeus") {
    return _buildAmadeusHotelsPayload({ query, env, warnings });
  }

  if (source === "agoda") {
    return _buildAgodaHotelsPayload({ query, env, warnings });
  }

  if (source === "booking-demand") {
    return _buildBookingDemandHotelsPayload({ query, env, warnings });
  }

  if (
    source === "booking-com" ||
    source === "booking-cj" ||
    source === "booking-com-cj"
  ) {
    return _buildBookingComCjHotelsPayload({ query, env, warnings });
  }

  if (!warnings.includes("unsupported_source")) {
    warnings.push("unsupported_source");
  }
  return {
    ok: true,
    source,
    provider: source,
    count: 0,
    stays: [],
    warnings,
  };
}

function _ticketmasterCategoryHints(category) {
  switch (String(category || "").toLowerCase()) {
    case "music":
      return { classificationName: "music", keywordHint: "" };
    case "sport":
      return { classificationName: "sports", keywordHint: "" };
    case "culture":
      return { classificationName: "arts", keywordHint: "culture" };
    case "theater":
      return { classificationName: "", keywordHint: "theater" };
    case "comedy":
      return { classificationName: "", keywordHint: "comedy" };
    case "family":
      return { classificationName: "family", keywordHint: "" };
    case "business":
      return { classificationName: "", keywordHint: "business conference summit" };
    case "food":
      return { classificationName: "", keywordHint: "food market culinary gastronomy" };
    default:
      return { classificationName: "", keywordHint: "" };
  }
}

function _ticketmasterCategoryHintStrategies(category) {
  const normalizedCategory = String(category || "").toLowerCase();
  const primary = _ticketmasterCategoryHints(normalizedCategory);
  const strategies = [primary];
  if (normalizedCategory === "theater") {
    strategies.push({
      classificationName: "",
      keywordHint: "theatre theater musical drama spectacle",
      keywordStrategy: true,
    });
    strategies.push({
      classificationName: "Arts & Theatre",
      keywordHint: "theatre theater musical drama spectacle",
      keywordStrategy: false,
    });
    strategies.push({
      classificationName: "",
      keywordHint: "theatre theater musical drama spectacle stage play",
      keywordStrategy: true,
    });
  } else if (normalizedCategory === "comedy") {
    strategies.push({
      classificationName: "",
      keywordHint: "comedy stand-up comedian humor humour",
      keywordStrategy: true,
    });
  }
  const deduped = [];
  const seen = new Set();
  for (const item of strategies) {
    const classificationName = safeStr(item?.classificationName);
    const keywordHint = safeStr(item?.keywordHint);
    const key = `${classificationName}::${keywordHint}`;
    if (seen.has(key)) continue;
    seen.add(key);
    deduped.push({
      classificationName,
      keywordHint,
      keywordStrategy: item?.keywordStrategy === true,
    });
  }
  return deduped;
}

function _ticketmasterDateToUtc(dateTimeValue, dateValue) {
  const dt = safeStr(dateTimeValue);
  if (dt) {
    const parsed = new Date(dt);
    if (!Number.isNaN(parsed.getTime())) return parsed.toISOString();
  }
  const dateOnly = safeStr(dateValue);
  if (dateOnly) {
    const parsed = new Date(`${dateOnly}T00:00:00.000Z`);
    if (!Number.isNaN(parsed.getTime())) return parsed.toISOString();
  }
  return null;
}

function _ticketmasterImageRatioValue(imageItem) {
  const ratioRaw = safeStr(imageItem?.ratio);
  if (!ratioRaw) return null;
  const normalized = ratioRaw.replace("-", "_");
  const parts = normalized.split("_");
  if (parts.length !== 2) return null;
  const w = Number(parts[0]);
  const h = Number(parts[1]);
  if (!Number.isFinite(w) || !Number.isFinite(h) || w <= 0 || h <= 0) {
    return null;
  }
  return w / h;
}

function _ticketmasterNormalizedImages(tmEvent) {
  const list = Array.isArray(tmEvent?.images) ? tmEvent.images : [];
  const out = [];
  for (const item of list) {
    const url = safeStr(item?.url);
    const lowerUrl = url.toLowerCase();
    if (!url || (!lowerUrl.startsWith("https://") && !lowerUrl.startsWith("http://"))) {
      continue;
    }
    const width = Number(item?.width);
    const height = Number(item?.height);
    const ratio = _ticketmasterImageRatioValue(item);
    out.push({
      url,
      width: Number.isFinite(width) && width > 0 ? width : 0,
      height: Number.isFinite(height) && height > 0 ? height : 0,
      ratio,
    });
  }
  return out;
}

function _ticketmasterIsNearSixteenByNine(ratio) {
  if (!Number.isFinite(ratio)) return false;
  return Math.abs(ratio - 16 / 9) <= 0.2;
}

function _ticketmasterPickClosestWidth(items, targetWidth) {
  if (!Array.isArray(items) || !items.length) return null;
  const sorted = [...items].sort((a, b) => {
    const widthA = Number(a?.width) || 0;
    const widthB = Number(b?.width) || 0;
    const diffA = Math.abs(widthA - targetWidth);
    const diffB = Math.abs(widthB - targetWidth);
    if (diffA !== diffB) return diffA - diffB;
    return widthB - widthA;
  });
  return sorted[0] || null;
}

function _ticketmasterBestImageUrls(tmEvent) {
  const candidates = _ticketmasterNormalizedImages(tmEvent);
  if (!candidates.length) {
    return { image_url: null, hero_image_url: null, thumbnail_url: null };
  }

  const nearSixteenByNine = candidates.filter((item) =>
    _ticketmasterIsNearSixteenByNine(Number(item?.ratio)),
  );

  const thumbnailBand = nearSixteenByNine.filter((item) => {
    const width = Number(item?.width) || 0;
    return width >= 640 && width <= 1280;
  });
  const thumbnail =
    _ticketmasterPickClosestWidth(thumbnailBand, 1024) ||
    _ticketmasterPickClosestWidth(nearSixteenByNine, 1024) ||
    _ticketmasterPickClosestWidth(candidates, 1024);

  const heroBand = nearSixteenByNine.filter((item) => {
    const width = Number(item?.width) || 0;
    return width >= 1280 && width <= 1920;
  });
  const hero =
    _ticketmasterPickClosestWidth(heroBand, 1600) ||
    _ticketmasterPickClosestWidth(nearSixteenByNine, 1600) ||
    _ticketmasterPickClosestWidth(candidates, 1600);

  const image = hero || thumbnail || candidates[0];
  return {
    image_url: image?.url || null,
    hero_image_url: hero?.url || image?.url || null,
    thumbnail_url: thumbnail?.url || image?.url || null,
  };
}

function _ticketmasterCategoryFromEvent(tmEvent) {
  const list = Array.isArray(tmEvent?.classifications) ? tmEvent.classifications : [];
  const parts = [];
  for (const item of list) {
    const segment = safeStr(item?.segment?.name);
    const genre = safeStr(item?.genre?.name);
    const subGenre = safeStr(item?.subGenre?.name);
    if (segment) parts.push(segment);
    if (genre) parts.push(genre);
    if (subGenre) parts.push(subGenre);
  }
  const raw = parts.join(" ").trim();
  const normalized = raw.toLowerCase();
  if (
    normalized.includes("comedy") ||
    normalized.includes("comédie") ||
    normalized.includes("comedie") ||
    normalized.includes("stand-up") ||
    normalized.includes("humor") ||
    normalized.includes("humour")
  ) {
    return { key: "comedy", label: "Comedy" };
  }
  if (
    normalized.includes("theatre") ||
    normalized.includes("theater") ||
    normalized.includes("théâtre") ||
    normalized.includes("drama") ||
    normalized.includes("play") ||
    normalized.includes("musical")
  ) {
    return { key: "theater", label: "Theater" };
  }
  if (normalized.includes("music")) return { key: "music", label: "Muziek" };
  if (normalized.includes("sport")) return { key: "sport", label: "Sport" };
  if (normalized.includes("arts") || normalized.includes("culture")) {
    return { key: "culture", label: "Cultuur" };
  }
  if (normalized.includes("family")) return { key: "family", label: "Familie" };
  if (
    normalized.includes("business") ||
    normalized.includes("conference") ||
    normalized.includes("convention")
  ) {
    return { key: "business", label: "Zakelijk" };
  }
  if (normalized.includes("food") || normalized.includes("culinary")) {
    return { key: "food", label: "Vandaag" };
  }
  return { key: "other", label: raw || "Event" };
}

function _ticketmasterVenueAddress(venue) {
  const line1 = safeStr(venue?.address?.line1);
  const line2 = safeStr(venue?.address?.line2);
  if (line1 && line2) return `${line1}, ${line2}`;
  return line1 || line2 || "";
}

function _publicEventCoordinateFromRaw(raw) {
  if (raw == null) return null;
  if (typeof raw === "string" && raw.trim() === "") return null;
  const value = Number(raw);
  if (!Number.isFinite(value)) return null;
  return value;
}

function _publicEventValidateCoordinatePair(latRaw, lngRaw) {
  const latitude = _publicEventCoordinateFromRaw(latRaw);
  const longitude = _publicEventCoordinateFromRaw(lngRaw);
  if (latitude == null || longitude == null) {
    return {
      ok: false,
      latitude: null,
      longitude: null,
      invalidReason: "missing_or_non_finite",
    };
  }
  if (latitude < -90 || latitude > 90) {
    return {
      ok: false,
      latitude: null,
      longitude: null,
      invalidReason: "out_of_range",
    };
  }
  if (longitude < -180 || longitude > 180) {
    return {
      ok: false,
      latitude: null,
      longitude: null,
      invalidReason: "out_of_range",
    };
  }
  if (Math.abs(latitude) < 0.0001 && Math.abs(longitude) < 0.0001) {
    return {
      ok: false,
      latitude: null,
      longitude: null,
      invalidReason: "null_island",
    };
  }
  return {
    ok: true,
    latitude,
    longitude,
    invalidReason: null,
  };
}

function _publicEventsVenueGeocodeQueryParts(venue, query) {
  const venueName = safeStr(venue?.name, 120);
  const addressLine1 = safeStr(venue?.address?.line1, 160);
  const addressLine2 = safeStr(venue?.address?.line2, 160);
  const city = safeStr(venue?.city?.name, 120);
  const region = safeStr(
    venue?.state?.name || venue?.state?.stateCode || venue?.state?.code,
    80,
  );
  const countryName = safeStr(venue?.country?.name, 80);
  const countryCode = safeStr(venue?.country?.countryCode || query?.country, 8).toUpperCase();
  const parts = [
    venueName,
    addressLine1,
    addressLine2,
    city,
    region,
    countryName || countryCode,
  ]
    .map((item) => safeStr(item, 180).trim())
    .filter(Boolean);
  const deduped = [];
  for (const item of parts) {
    const lowered = item.toLowerCase();
    if (deduped.some((entry) => entry.toLowerCase() === lowered)) continue;
    deduped.push(item);
  }
  return deduped;
}

async function _publicEventsVenueGeocodeCacheKey(countryCode, normalizedText) {
  const scopedCountry = safeStr(countryCode, 8).trim().toUpperCase() || "XX";
  const digest = await _sha256Hex(normalizedText);
  return `event_venue_geocode:v1:${scopedCountry}:${digest}`;
}

function _publicEventsCoordinateFromMapboxFeature(feature) {
  const extracted = _allocatorExtractGeocodePoint(feature);
  const validated = _publicEventValidateCoordinatePair(extracted?.lat, extracted?.lng);
  if (!validated.ok) return null;
  return {
    latitude: validated.latitude,
    longitude: validated.longitude,
  };
}

async function _publicEventsGeocodeVenueCoordinates({ env, venue, query }) {
  const token = safeStr(env?.MAPBOX_TOKEN, 400).trim();
  if (!token) {
    return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
  }
  const parts = _publicEventsVenueGeocodeQueryParts(venue, query);
  if (parts.length < 2) {
    return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
  }
  const geocodeText = parts.join(", ").slice(0, 320);
  const normalizedForHash = geocodeText.toLowerCase().replace(/\s+/g, " ").trim();
  if (!normalizedForHash) {
    return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
  }
  const countryHint = _allocatorMapboxCountryHint(
    venue?.country?.countryCode || query?.country || query?.market,
  );
  const cacheKey = await _publicEventsVenueGeocodeCacheKey(countryHint, normalizedForHash);
  const missMarker = "__MISS__";
  if (env?.BOOKING_KV) {
    try {
      const cached = await env.BOOKING_KV.get(cacheKey, { type: "json" });
      if (cached && cached.miss === true) {
        return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
      }
      const cachedValidated = _publicEventValidateCoordinatePair(
        cached?.latitude,
        cached?.longitude,
      );
      if (cachedValidated.ok) {
        return {
          ok: true,
          coordinate: {
            latitude: cachedValidated.latitude,
            longitude: cachedValidated.longitude,
          },
          coordSource: "venue_geocoded",
          warnings: ["coord_source=venue_geocoded"],
        };
      }
    } catch (_) {}
  }
  const queryText = encodeURIComponent(geocodeText);
  const countryPart = countryHint ? `&country=${encodeURIComponent(countryHint)}` : "";
  const url = `https://api.mapbox.com/geocoding/v5/mapbox.places/${queryText}.json?limit=1&autocomplete=false&types=address,poi,place,locality,neighborhood&language=fr,en,nl,es${countryPart}&access_token=${token}`;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 3500);
  try {
    const response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal: controller.signal,
    });
    const payload = await response.json().catch(() => ({}));
    const features = Array.isArray(payload?.features) ? payload.features : [];
    const coordinate = features.length
      ? _publicEventsCoordinateFromMapboxFeature(features[0])
      : null;
    if (coordinate) {
      if (env?.BOOKING_KV) {
        try {
          await env.BOOKING_KV.put(
            cacheKey,
            JSON.stringify({
              latitude: coordinate.latitude,
              longitude: coordinate.longitude,
              source: "venue_geocoded",
              updated_at_utc: new Date().toISOString(),
            }),
            { expirationTtl: 60 * 60 * 24 * 30 },
          );
        } catch (_) {}
      }
      return {
        ok: true,
        coordinate,
        coordSource: "venue_geocoded",
        warnings: ["coord_source=venue_geocoded"],
      };
    }
    if (env?.BOOKING_KV) {
      try {
        await env.BOOKING_KV.put(
          cacheKey,
          JSON.stringify({
            miss: true,
            marker: missMarker,
            updated_at_utc: new Date().toISOString(),
          }),
          { expirationTtl: 60 * 30 },
        );
      } catch (_) {}
    }
    return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
  } catch (_) {
    return { ok: false, coordinate: null, coordSource: "missing", warnings: [] };
  } finally {
    clearTimeout(timer);
  }
}

function _ticketmasterStatusCode(tmEvent) {
  return safeStr(tmEvent?.dates?.status?.code || tmEvent?.dates?.status?.description).toLowerCase();
}

function _ticketmasterDateTimeParam(rawValue) {
  const text = String(rawValue || "").trim();
  if (!text) return "";
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return "";
  const yyyy = String(parsed.getUTCFullYear()).padStart(4, "0");
  const mm = String(parsed.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(parsed.getUTCDate()).padStart(2, "0");
  const hh = String(parsed.getUTCHours()).padStart(2, "0");
  const mi = String(parsed.getUTCMinutes()).padStart(2, "0");
  const ss = String(parsed.getUTCSeconds()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}T${hh}:${mi}:${ss}Z`;
}

function _ticketmasterIsActionable(tmEvent) {
  const statusCode = _ticketmasterStatusCode(tmEvent);
  if (!statusCode) return true;
  if (statusCode.includes("cancel")) return false;
  if (statusCode.includes("offsale")) return false;
  return true;
}

async function _mapTicketmasterEventToPublicEvent(tmEvent, query, receivedAtUtc, env) {
  const eventId = safeStr(tmEvent?.id);
  const title = safeStr(tmEvent?.name);
  if (!eventId || !title) return { event: null, warnings: [] };
  const venue = Array.isArray(tmEvent?._embedded?.venues) ? tmEvent._embedded.venues[0] : null;
  const venueName = safeStr(venue?.name);
  const city = safeStr(venue?.city?.name);
  const countryCode = safeStr(venue?.country?.countryCode || query?.country || "BE").toUpperCase();
  const marketCode = countryCode ? countryCode.toLowerCase() : "";
  const directCoordinate = _publicEventValidateCoordinatePair(
    venue?.location?.latitude,
    venue?.location?.longitude,
  );
  const diagnostics = [];
  let latitude = null;
  let longitude = null;
  if (directCoordinate.ok) {
    latitude = directCoordinate.latitude;
    longitude = directCoordinate.longitude;
    diagnostics.push("coord_source=ticketmaster_venue_location");
  } else if (directCoordinate.invalidReason === "null_island") {
    diagnostics.push("coord_invalid_reason=null_island");
  }
  if (latitude == null || longitude == null) {
    const geocoded = await _publicEventsGeocodeVenueCoordinates({ env, venue, query });
    if (geocoded?.ok === true && geocoded.coordinate) {
      latitude = geocoded.coordinate.latitude;
      longitude = geocoded.coordinate.longitude;
      diagnostics.push(...(Array.isArray(geocoded.warnings) ? geocoded.warnings : []));
    }
  }
  if (latitude == null || longitude == null) {
    diagnostics.push("coord_source=missing");
  }
  const categoryMeta = _ticketmasterCategoryFromEvent(tmEvent);
  const imageUrls = _ticketmasterBestImageUrls(tmEvent);
  const startsAtUtc = _ticketmasterDateToUtc(
    tmEvent?.dates?.start?.dateTime,
    tmEvent?.dates?.start?.localDate,
  );
  const endsAtUtc = _ticketmasterDateToUtc(
    tmEvent?.dates?.end?.dateTime,
    tmEvent?.dates?.end?.localDate,
  );
  const mapped = {
    id: `tm_${eventId}`,
    title,
    subtitle: safeStr(tmEvent?.info || tmEvent?.pleaseNote),
    description: safeStr(tmEvent?.pleaseNote || tmEvent?.info),
    location_name: venueName || city || "",
    venue_name: venueName || "",
    category: categoryMeta.label,
    category_key: categoryMeta.key,
    address: _ticketmasterVenueAddress(venue),
    city,
    country_code: countryCode || "BE",
    market_code: marketCode || "be",
    latitude: latitude ?? null,
    longitude: longitude ?? null,
    distance_label: null,
    image_url: imageUrls.image_url,
    hero_image_url: imageUrls.hero_image_url,
    thumbnail_url: imageUrls.thumbnail_url,
    starts_at_utc: startsAtUtc,
    ends_at_utc: endsAtUtc,
    time_zone: safeStr(tmEvent?.dates?.timezone),
    provider: "ticketmaster",
    source_event_id: eventId,
    source_url: safeStr(tmEvent?.url),
    status: _ticketmasterStatusCode(tmEvent) || "scheduled",
    updated_at_utc: receivedAtUtc,
  };
  mapped.distance_label = _publicEventDistanceLabel(mapped, query);
  return {
    event: mapped,
    warnings: _mergePublicEventWarnings(diagnostics),
  };
}

async function _fetchTicketmasterPublicEvents({ env, query, receivedAtUtc }) {
  const apiKey = safeStr(env?.TICKETMASTER_API_KEY);
  if (!apiKey) {
    return { ok: false, warnings: ["ticketmaster_api_key_missing"] };
  }
  const staticParams = new URLSearchParams();
  staticParams.set("apikey", apiKey);
  staticParams.set("countryCode", safeStr(query?.country || "BE").toUpperCase() || "BE");
  staticParams.set("size", String(Math.max(1, Math.min(50, Number(query?.limit) || 50))));
  const startDateTime = _ticketmasterDateTimeParam(query?.startAtUtc);
  const endDateTime = _ticketmasterDateTimeParam(query?.endAtUtc);
  if (startDateTime) staticParams.set("startDateTime", startDateTime);
  if (endDateTime) staticParams.set("endDateTime", endDateTime);
  if (
    query?.latitude != null &&
    query?.longitude != null &&
    query?.radiusKm != null &&
    Number.isFinite(query.radiusKm)
  ) {
    staticParams.set("latlong", `${query.latitude},${query.longitude}`);
    staticParams.set("radius", String(Math.max(0, Math.min(500, query.radiusKm))));
    staticParams.set("unit", "km");
  }
  const fetchTicketmasterAttempt = async ({ params, includeSort }) => {
    const nextParams = new URLSearchParams(params.toString());
    if (includeSort) nextParams.set("sort", "date,asc");
    const requestUrl = `https://app.ticketmaster.com/discovery/v2/events.json?${nextParams.toString()}`;
    const controller = new AbortController();
    const timeoutMs = 4000;
    const timer = setTimeout(() => {
      controller.abort();
    }, timeoutMs);
    try {
      const response = await fetch(requestUrl, {
        method: "GET",
        headers: { accept: "application/json" },
        signal: controller.signal,
      });
      return { ok: true, response };
    } catch (_) {
      return { ok: false, error: "ticketmaster_http_error" };
    } finally {
      clearTimeout(timer);
    }
  };
  const normalizedCategory = String(query?.category || "").toLowerCase();
  const strategies = _ticketmasterCategoryHintStrategies(normalizedCategory);
  const isRetryCategory = normalizedCategory === "theater" || normalizedCategory === "comedy";
  const providerKeyword = safeStr(query?.keyword);
  const queryDiagnostics = [
    query?.country ? `diag_country_${String(query.country).toLowerCase()}` : "",
    query?.market ? `diag_market_${String(query.market).toLowerCase()}` : "",
    query?.category ? `diag_category_${String(query.category).toLowerCase()}` : "",
    query?.dateMode ? `diag_date_${String(query.dateMode).toLowerCase()}` : "",
  ].filter(Boolean);
  let mergedWarnings = [];
  let retryUsed = false;
  let keywordStrategyUsed = false;
  for (let i = 0; i < strategies.length; i += 1) {
    const strategy = strategies[i] || {};
    const params = new URLSearchParams(staticParams.toString());
    if (strategy.classificationName) {
      params.set("classificationName", strategy.classificationName);
    }
    const keywordParts = [];
    if (providerKeyword) keywordParts.push(providerKeyword);
    if (strategy.keywordHint) keywordParts.push(strategy.keywordHint);
    const keyword = keywordParts.join(" ").trim().slice(0, 120);
    if (keyword) params.set("keyword", keyword);

    let attempt = await fetchTicketmasterAttempt({ params, includeSort: true });
    let response = attempt.response;
    const fallbackWarnings = [];
    if (!attempt.ok) {
      mergedWarnings = _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_http_error"]);
      if (isRetryCategory && i < strategies.length - 1) {
        retryUsed = true;
        continue;
      }
      return { ok: false, warnings: mergedWarnings };
    }
    if (!response || !response.ok) {
      if (response && Number.isFinite(response.status)) {
        fallbackWarnings.push(`ticketmaster_http_status_${response.status}`);
      }
      // Some API configurations reject sort=date,asc for certain queries; retry once without sort.
      attempt = await fetchTicketmasterAttempt({ params, includeSort: false });
      if (!attempt.ok) {
        mergedWarnings = _mergePublicEventWarnings(
          mergedWarnings,
          fallbackWarnings,
          ["ticketmaster_http_error"],
        );
        if (isRetryCategory && i < strategies.length - 1) {
          retryUsed = true;
          continue;
        }
        return { ok: false, warnings: mergedWarnings };
      }
      response = attempt.response;
      if (!response || !response.ok) {
        mergedWarnings = _mergePublicEventWarnings(
          mergedWarnings,
          fallbackWarnings,
          ["ticketmaster_http_error"],
          response && Number.isFinite(response.status)
            ? [`ticketmaster_http_status_${response.status}`]
            : [],
        );
        if (isRetryCategory && i < strategies.length - 1) {
          retryUsed = true;
          continue;
        }
        return { ok: false, warnings: mergedWarnings };
      }
    }
    let payload;
    try {
      payload = await response.json();
    } catch (_) {
      mergedWarnings = _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_invalid_payload"]);
      if (isRetryCategory && i < strategies.length - 1) {
        retryUsed = true;
        continue;
      }
      return { ok: false, warnings: mergedWarnings };
    }
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
      mergedWarnings = _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_invalid_payload"]);
      if (isRetryCategory && i < strategies.length - 1) {
        retryUsed = true;
        continue;
      }
      return { ok: false, warnings: mergedWarnings };
    }
    const rawEvents = Array.isArray(payload?._embedded?.events)
      ? payload._embedded.events
      : [];
    if (!rawEvents.length) {
      mergedWarnings = _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_empty"]);
      if (isRetryCategory && i < strategies.length - 1) {
        retryUsed = true;
        continue;
      }
      break;
    }
    const actionableEvents = rawEvents.filter((item) => _ticketmasterIsActionable(item));
    const mappedWithWarnings = [];
    for (const item of actionableEvents) {
      const mappedItem = await _mapTicketmasterEventToPublicEvent(item, query, receivedAtUtc, env);
      if (!mappedItem || !mappedItem.event) continue;
      mappedWithWarnings.push(mappedItem);
    }
    const mappingWarnings = _mergePublicEventWarnings(
      ...mappedWithWarnings.map((item) => item.warnings),
    );
    const mapped = mappedWithWarnings
      .map((item) => item.event)
      .filter((eventItem) => !!eventItem)
      .filter((eventItem) => {
        if (!isRetryCategory) return true;
        return String(eventItem?.category_key || "").toLowerCase() === normalizedCategory;
      })
      .filter((eventItem) => _publicEventMatchesQuery(eventItem, query))
      .slice(0, query.limit);
    if (mapped.length) {
      if (retryUsed && strategy.keywordStrategy === true) {
        keywordStrategyUsed = true;
      }
      const warnings = keywordStrategyUsed
        ? _mergePublicEventWarnings(
          ["ticketmaster_category_keyword_strategy_used"],
          mappingWarnings,
          queryDiagnostics,
        )
        : _mergePublicEventWarnings(mappingWarnings, queryDiagnostics);
      return { ok: true, warnings, events: mapped };
    }
    mergedWarnings = _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_empty"]);
    if (isRetryCategory && i < strategies.length - 1) {
      retryUsed = true;
      continue;
    }
  }
  if (retryUsed) {
    mergedWarnings = _mergePublicEventWarnings(
      mergedWarnings,
      ["ticketmaster_category_retry_empty"],
    );
  }
  return {
    ok: false,
    warnings: _mergePublicEventWarnings(mergedWarnings, ["ticketmaster_empty"], queryDiagnostics),
  };
}

