// ===============================
// PAY STATUS (fallback finalizer)
// ===============================
function _payStatusExplicitScope(tenantValue, companyValue) {
  const tenantId = _scopeText(tenantValue);
  const companyId = _scopeText(companyValue);
  if (!tenantId || !companyId) return null;
  return {
    tenant_id: tenantId,
    company_id: companyId,
    hasScope: true,
  };
}

function _payStatusScopeMatches(a, b) {
  if (!a?.hasScope || !b?.hasScope) return false;
  return (
    _scopeText(a?.tenant_id) === _scopeText(b?.tenant_id) &&
    _scopeText(a?.company_id) === _scopeText(b?.company_id)
  );
}

function _payStatusScopeFromBookingRecord(rec) {
  return _payStatusExplicitScope(
    rec?.tenant_id ??
      rec?.tenantId ??
      rec?.booking?.tenant_id ??
      rec?.booking?.tenantId,
    rec?.company_id ??
      rec?.companyId ??
      rec?.booking?.company_id ??
      rec?.booking?.companyId,
  );
}

function _payStatusScopeFromPaymentRecord(rec) {
  return _payStatusExplicitScope(
    rec?.tenant_id ??
      rec?.tenantId ??
      rec?.payload?.tenant_id ??
      rec?.payload?.tenantId,
    rec?.company_id ??
      rec?.companyId ??
      rec?.payload?.company_id ??
      rec?.payload?.companyId,
  );
}

function _payStatusBookingIdCandidates(data, id, includeRawId = false) {
  const out = [];
  const add = (value) => {
    const bookingId = safeStr(value, 160);
    if (!bookingId) return;
    if (!out.includes(bookingId)) out.push(bookingId);
  };
  add(data?.booking_id);
  add(data?.bookingId);
  add(data?.public_booking_id);
  add(data?.publicBookingId);
  add(data?.payload?.__booking_id);
  add(data?.payload?.booking_id);
  add(data?.payload?.bookingId);
  if (includeRawId) add(id);
  return out;
}

function _payStatusLooksCanonicalPublicBookingId(value) {
  const token = safeStr(value, 160);
  if (!token) return false;
  if (/^[0-9]{4}-[0-9]{2}-[0-9]{3,}$/i.test(token)) return true;
  return false;
}

function _payStatusResolveCanonicalInvoiceBookingId(data) {
  const candidates = [];
  const seen = new Set();
  const push = (value, source, canonicalOnly = false) => {
    const token = safeStr(value, 160);
    if (!token) return;
    if (canonicalOnly && !_payStatusLooksCanonicalPublicBookingId(token)) return;
    if (seen.has(token)) return;
    seen.add(token);
    candidates.push({ bookingId: token, source: safeStr(source, 80) || "unknown" });
  };

  push(data?.public_booking_id, "data.public_booking_id");
  push(data?.publicBookingId, "data.publicBookingId");
  push(data?.payload?.__booking_id, "data.payload.__booking_id");
  push(data?.payload?.booking_id, "data.payload.booking_id", true);
  push(data?.payload?.bookingId, "data.payload.bookingId", true);

  const metadataSources = [
    { obj: data?.metadata, label: "data.metadata" },
    { obj: data?.payload?.metadata, label: "data.payload.metadata" },
    { obj: data?.mollie?.metadata, label: "data.mollie.metadata" },
    { obj: data?.payload?.mollie?.metadata, label: "data.payload.mollie.metadata" },
  ];
  for (const meta of metadataSources) {
    const entry = meta?.obj && typeof meta.obj === "object" ? meta.obj : null;
    if (!entry) continue;
    push(entry?.public_booking_id, `${meta.label}.public_booking_id`);
    push(entry?.publicBookingId, `${meta.label}.publicBookingId`);
    push(entry?.__booking_id, `${meta.label}.__booking_id`);
    push(entry?.public_reference, `${meta.label}.public_reference`);
    push(entry?.publicReference, `${meta.label}.publicReference`);
    push(entry?.public_booking_reference, `${meta.label}.public_booking_reference`);
    push(entry?.publicBookingReference, `${meta.label}.publicBookingReference`);
    push(entry?.booking_public_id, `${meta.label}.booking_public_id`);
    push(entry?.bookingPublicId, `${meta.label}.bookingPublicId`);
    push(entry?.booking_id, `${meta.label}.booking_id`, true);
    push(entry?.bookingId, `${meta.label}.bookingId`, true);
  }

  if (candidates.length > 0) return candidates[0];
  return { bookingId: "", source: "none" };
}

function resolveCanonicalBookingIdForPaidPayment(stored, paymentBookingId) {
  const paymentId = safeStr(paymentBookingId, 160);
  if (!paymentId) return "";
  const canonicalId = safeStr(
    stored?.public_booking_id ??
      stored?.publicBookingId ??
      stored?.payload?.__booking_id ??
      stored?.payload?.booking_id ??
      stored?.payload?.bookingId,
    160,
  );
  if (!canonicalId || canonicalId === paymentId) return "";
  if (!_dashboardUuidLikeId(paymentId)) return "";
  return canonicalId;
}

function isResumedMolliePaymentRecord(stored, paymentBookingId) {
  const paymentId = safeStr(paymentBookingId, 160);
  const canonicalId = resolveCanonicalBookingIdForPaidPayment(stored, paymentBookingId);
  if (!paymentId || !canonicalId || canonicalId === paymentId) return false;
  if (!_dashboardUuidLikeId(paymentId)) return false;
  return (
    stored?.checkout_resume === true ||
    stored?.checkoutResume === true ||
    stored?.payload?.__checkout_resume === true ||
    stored?.payload?.checkout_resume === true ||
    safeStr(stored?.finalize_debug?.stage, 80) === "handleBooking_failed"
  );
}

function _tenantScopeFromStoredPaymentRecord(stored) {
  const tenant_id = safeStr(
    stored?.tenant_id ??
      stored?.tenantId ??
      stored?.payload?.tenant_id ??
      stored?.payload?.tenantId,
    80,
  );
  const company_id = safeStr(
    stored?.company_id ??
      stored?.companyId ??
      stored?.payload?.company_id ??
      stored?.payload?.companyId,
    80,
  );
  if (!tenant_id || !company_id) return null;
  return { tenant_id, company_id, hasScope: true };
}

function _canonicalAcceptsResumePaymentBookingId(canonicalRec, paymentBookingId, canonicalBookingId) {
  const linkedPaymentBookingId = safeStr(
    canonicalRec?.payment_booking_id ?? canonicalRec?.paymentBookingId,
    160,
  );
  if (linkedPaymentBookingId && linkedPaymentBookingId === paymentBookingId) return true;
  const payloadPaymentBookingId = safeStr(
    canonicalRec?.payload?.payment_booking_id ?? canonicalRec?.payload?.paymentBookingId,
    160,
  );
  if (payloadPaymentBookingId && payloadPaymentBookingId === paymentBookingId) return true;
  if (!linkedPaymentBookingId && !payloadPaymentBookingId) {
    const canonicalSelf = safeStr(
      canonicalRec?.booking_id ??
        canonicalRec?.bookingId ??
        canonicalRec?.public_booking_id ??
        canonicalRec?.publicBookingId ??
        canonicalBookingId,
      160,
    );
    return canonicalSelf === canonicalBookingId;
  }
  return false;
}

function _applyResumePaidPaymentToCanonicalRecord(
  canonicalRec,
  stored,
  { paymentBookingId, molliePaymentId, paidAt } = {},
) {
  const nowIso = new Date().toISOString();
  const paidAtIso =
    safeStr(paidAt || stored?.paid_at || stored?.paidAt, 80) || nowIso;
  const preservedMethod = normalizeBookingPaymentMethodId(
    canonicalRec?.payment_method ??
      canonicalRec?.paymentMethod ??
      canonicalRec?.booking?.payment_method ??
      canonicalRec?.booking?.paymentMethod ??
      canonicalRec?.payload?.payment_method ??
      canonicalRec?.payload?.paymentMethod ??
      stored?.payment_method ??
      stored?.paymentMethod ??
      stored?.payload?.payment_method ??
      stored?.payload?.paymentMethod,
  );
  const safePaymentBookingId = safeStr(paymentBookingId, 160) || null;
  const safeMolliePaymentId = safeStr(molliePaymentId, 120) || null;

  canonicalRec.payment_status = "paid";
  canonicalRec.paymentStatus = "paid";
  canonicalRec.payment_provider = "mollie";
  canonicalRec.paymentProvider = "mollie";
  canonicalRec.payment_mode = "mollie";
  canonicalRec.paymentMode = "mollie";
  canonicalRec.payment_booking_id = safePaymentBookingId;
  canonicalRec.paymentBookingId = safePaymentBookingId;
  canonicalRec.paid_at = paidAtIso;
  canonicalRec.paidAt = paidAtIso;
  if (safeMolliePaymentId) {
    canonicalRec.payment_id = safeMolliePaymentId;
    canonicalRec.paymentId = safeMolliePaymentId;
    canonicalRec.mollie =
      canonicalRec.mollie && typeof canonicalRec.mollie === "object"
        ? { ...canonicalRec.mollie }
        : {};
    canonicalRec.mollie.id = safeMolliePaymentId;
    canonicalRec.mollie.payment_id = safeMolliePaymentId;
    canonicalRec.mollie.status = "paid";
  }
  if (preservedMethod) {
    canonicalRec.payment_method = preservedMethod;
    canonicalRec.paymentMethod = preservedMethod;
  }
  canonicalRec.updatedAt = nowIso;
  canonicalRec.updated_at = nowIso;

  if (canonicalRec.booking && typeof canonicalRec.booking === "object") {
    canonicalRec.booking.payment_status = "paid";
    canonicalRec.booking.paymentStatus = "paid";
    canonicalRec.booking.payment_provider = "mollie";
    canonicalRec.booking.paymentProvider = "mollie";
    canonicalRec.booking.payment_mode = "mollie";
    canonicalRec.booking.paymentMode = "mollie";
    canonicalRec.booking.payment_booking_id = safePaymentBookingId;
    canonicalRec.booking.paymentBookingId = safePaymentBookingId;
    canonicalRec.booking.paid_at = paidAtIso;
    canonicalRec.booking.paidAt = paidAtIso;
    if (safeMolliePaymentId) {
      canonicalRec.booking.payment_id = safeMolliePaymentId;
      canonicalRec.booking.paymentId = safeMolliePaymentId;
      canonicalRec.booking.mollie = canonicalRec.mollie;
    }
    if (preservedMethod) {
      canonicalRec.booking.payment_method = preservedMethod;
      canonicalRec.booking.paymentMethod = preservedMethod;
    }
    canonicalRec.booking.updatedAt = nowIso;
    canonicalRec.booking.updated_at = nowIso;
  }
  if (canonicalRec.payload && typeof canonicalRec.payload === "object") {
    canonicalRec.payload.payment_status = "paid";
    canonicalRec.payload.paymentStatus = "paid";
    canonicalRec.payload.payment_booking_id = safePaymentBookingId;
    canonicalRec.payload.paymentBookingId = safePaymentBookingId;
    if (safeMolliePaymentId) {
      canonicalRec.payload.payment_id = safeMolliePaymentId;
      canonicalRec.payload.paymentId = safeMolliePaymentId;
    }
    if (preservedMethod) {
      canonicalRec.payload.payment_method = preservedMethod;
      canonicalRec.payload.paymentMethod = preservedMethod;
    }
  }
}

async function _requestFleetLegAllocation(env, spec, fleetScope, sourceLabel = "fleet_dispatch") {
  const allocatorBookingId = safeStr(spec?.allocatorBookingId, 200);
  const legKey = safeStr(spec?.legKey, 24).toLowerCase() || "leg";
  const maskedAllocatorId = _bookingIntentMask(allocatorBookingId);
  console.log(
    `[ROUNDTRIP_DISPATCH][LEG_ALLOCATE_START] leg=${legKey} booking=${maskedAllocatorId} source=${safeStr(sourceLabel, 64) || "fleet_dispatch"}`,
  );
  const alloc = await _allocatorRequest(env, spec.pickupIso, {
    action: "allocate",
    booking_id: allocatorBookingId,
    pickup_ms: spec.pickupMs,
    service_min: spec.serviceMin,
    tier: spec.tier,
    pax: spec.pax,
    bags: spec.bags,
    from: spec.from,
    pickup_from: spec.from,
    pickup_address: spec.from,
    to: spec.to,
    dropoff_to: spec.to,
    dropoff_address: spec.to,
    pickup_iso: spec.pickupIso,
    pickup_lat: spec.pickupLat,
    pickup_lng: spec.pickupLng,
    tenantScope: fleetScope,
  });
  const allowed = alloc?.allowed === true;
  const vehicleId = safeStr(alloc?.assigned_vehicle_id, 128) || null;
  let assignedDriver =
    alloc?.assigned_driver && typeof alloc.assigned_driver === "object"
      ? alloc.assigned_driver
      : null;
  if (!assignedDriver && vehicleId) {
    try {
      assignedDriver = await _driverSummaryForVehicleId(env, vehicleId, fleetScope);
    } catch (_) {
      assignedDriver = null;
    }
  }
  const driverId =
    safeStr(
      assignedDriver?.driver_id ?? assignedDriver?.driverId ?? assignedDriver?.id,
      96,
    ) || null;
  console.log(
    `[ROUNDTRIP_DISPATCH][LEG_ALLOCATE_RESULT] leg=${legKey} booking=${maskedAllocatorId} allowed=${allowed ? "true" : "false"} vehicle=${_bookingIntentMask(vehicleId)} driver=${_bookingIntentMask(driverId)} reason=${safeStr(alloc?.reason, 80) || "-"}`,
  );
  return {
    ok: allowed && !!vehicleId,
    allowed,
    allocatorBookingId,
    legKey: safeStr(spec?.legKey, 24).toUpperCase(),
    legType: spec?.legType || legKey,
    assignedVehicleId: vehicleId,
    assignedDriverId: driverId,
    assignedDriver,
    alloc,
    pickupIso: spec.pickupIso,
  };
}

async function _releaseFleetLegReservations(env, reservations, fleetScope) {
  for (const reservation of reservations || []) {
    const bookingId = safeStr(reservation?.bookingId ?? reservation?.allocatorBookingId, 200);
    const pickupIso = safeStr(reservation?.pickupIso, 80);
    if (!bookingId || !pickupIso) continue;
    try {
      await _allocatorRequest(env, pickupIso, {
        action: "release",
        booking_id: bookingId,
        tenantScope: fleetScope,
      });
    } catch (_) {
      // Best-effort release only.
    }
  }
}

async function _vehicleCapacityGateForRoundtripDispatch(env, {
  parentBookingId,
  rec = null,
  bookingFields = null,
  fleetScope,
  pickupLat = null,
  pickupLng = null,
} = {}) {
  const mode = resolveRoundtripDispatchMode(rec || bookingFields || {});
  const bookingObj = bookingFields && typeof bookingFields === "object" ? bookingFields : {};
  const tier = normalizeTier(bookingObj.tier ?? "comfort");
  const pax = clampInt(bookingObj.pax, 1, 99);
  const bags = Math.max(0, clampInt(bookingObj.bags, 0, 99));
  const common = { tier, pax, bags, tenantScope: fleetScope };
  if (mode !== "split_no_wait") {
    return _vehicleCapacityGateForRequest(env, {
      ...common,
      pickupMs: Date.parse(bookingObj.pickup_iso),
      serviceMin: bookingObj.service_min,
      from: bookingObj.from,
      pickup_from: bookingObj.from,
      pickup_address: bookingObj.from,
      to: bookingObj.to,
      dropoff_to: bookingObj.to,
      dropoff_address: bookingObj.to,
      pickup_iso: bookingObj.pickup_iso,
      pickup_lat: pickupLat,
      pickup_lng: pickupLng,
    });
  }
  const legSpecs = _buildSplitRoundtripLegDispatchSpecs({
    parentBookingId,
    rec,
    env,
    outboundPickupIso: bookingObj.pickup_iso,
    outboundFrom: bookingObj.from,
    outboundTo: bookingObj.to,
    outboundPickupLat: pickupLat,
    outboundPickupLng: pickupLng,
    returnPickupIso: bookingObj.return_pickup_iso,
    returnFrom: bookingObj.return_from,
    returnTo: bookingObj.return_to,
    durationRouteMin: bookingObj.duration_route_min,
    returnDurationMin: bookingObj.return_duration_min,
    tier,
    pax,
    bags,
    stopCount: bookingObj.stop_count,
  });
  for (const spec of legSpecs) {
    const gate = await _vehicleCapacityGateForRequest(env, {
      ...common,
      pickupMs: spec.pickupMs,
      serviceMin: spec.serviceMin,
      from: spec.from,
      pickup_from: spec.from,
      pickup_address: spec.from,
      to: spec.to,
      dropoff_to: spec.to,
      dropoff_address: spec.to,
      pickup_iso: spec.pickupIso,
      pickup_lat: spec.pickupLat,
      pickup_lng: spec.pickupLng,
    });
    if (!gate.ok) return gate;
  }
  return { ok: true, available_slots: legSpecs.length, suitable_vehicle_count: legSpecs.length };
}

async function _runBookingCreationFleetDispatch(env, {
  canonicalBookingId,
  fleetScope,
  service,
  pickup_iso,
  from,
  to,
  return_pickup_iso = "",
  return_from = "",
  return_to = "",
  duration_route_min = 0,
  return_duration_min = 0,
  wait_min = 0,
  tier = "comfort",
  pax = 1,
  bags = 0,
  stop_count = 0,
  ret = { enabled: false },
  hasReturnSchedule = false,
  bookingPickupLatForAllocator = null,
  bookingPickupLngForAllocator = null,
  bookingServiceMin = 30,
} = {}) {
  const bookingFields = {
    service,
    pickup_iso,
    from,
    to,
    return_pickup_iso,
    return_from,
    return_to,
    duration_route_min,
    return_duration_min,
    wait_min,
    tier,
    pax,
    bags,
    stop_count,
    return_enabled: ret?.enabled === true,
    hasReturnSchedule,
    service_min: bookingServiceMin,
    // Layer 1B: forward the pickup coordinates resolved by handleBooking
    // (payload pickup_lat/pickupLat/from_lat/fromLat or route geocode) so the
    // allocator route check has a usable pickup origin. Without these the
    // allocator fires with pickup_lat=null, the route returns no_route, and
    // an otherwise free vehicle is rejected with route_pickup_coords_usable=
    // false / route_pickup_coordinate_source=unavailable. Both standard and
    // camelCase aliases are written so any downstream reader matches.
    pickup_lat: bookingPickupLatForAllocator,
    pickup_lng: bookingPickupLngForAllocator,
    pickupLat: bookingPickupLatForAllocator,
    pickupLng: bookingPickupLngForAllocator,
  };
  return _dispatchFleetAssignmentForBooking(env, {
    parentBookingId: canonicalBookingId,
    rec: { booking: bookingFields, return_enabled: ret?.enabled === true, return_pickup_iso, wait_min, service },
    fleetScope,
    sourceLabel: "booking_create",
    requireAllLegs: true,
    allowPartialLegAssignment: false,
    bookingFields,
  });
}

async function _dispatchFleetAssignmentForBooking(
  env,
  {
    parentBookingId,
    rec = null,
    fleetScope,
    sourceLabel = "fleet_dispatch",
    requireAllLegs = false,
    allowPartialLegAssignment = true,
    bookingFields = null,
  } = {},
) {
  const safeParentId = safeStr(parentBookingId, 160);
  const maskedParentId = _bookingIntentMask(safeParentId);
  const mode = resolveRoundtripDispatchMode(rec || bookingFields || {});
  console.log(
    `[ROUNDTRIP_DISPATCH][MODE] mode=${mode} booking=${maskedParentId} source=${safeStr(sourceLabel, 64) || "fleet_dispatch"}`,
  );

  const bookingObj = rec?.booking && typeof rec.booking === "object" ? rec.booking : {};
  const payloadObj = rec?.payload && typeof rec.payload === "object" ? rec.payload : {};
  const quoteObj = rec?.quote && typeof rec.quote === "object" ? rec.quote : {};
  const fields = bookingFields && typeof bookingFields === "object" ? bookingFields : {};
  const tier = normalizeTier(
    fields.tier ?? bookingObj?.tier ?? payloadObj?.tier ?? rec?.tier ?? "comfort",
  );
  const pax = clampInt(fields.pax ?? bookingObj?.pax ?? payloadObj?.pax ?? rec?.pax, 1, 99);
  const bags = Math.max(
    0,
    clampInt(fields.bags ?? bookingObj?.bags ?? payloadObj?.bags ?? rec?.bags, 0, 99),
  );
  const stopCount = Math.max(
    0,
    Array.isArray(fields.stops)
      ? fields.stops.length
      : Array.isArray(bookingObj?.stops)
        ? bookingObj.stops.length
        : Array.isArray(payloadObj?.stops)
          ? payloadObj.stops.length
          : 0,
  );
  const durationRouteMin = Number(
    fields.duration_route_min ??
      bookingObj?.duration_route_min ??
      rec?.duration_route_min ??
      quoteObj?.duration_min ??
      0,
  );
  const returnDurationMin = Number(
    fields.return_duration_min ??
      bookingObj?.return_duration_min ??
      rec?.return_duration_min ??
      quoteObj?.return?.duration_min ??
      0,
  );
  const waitMin = Number(
    fields.wait_min ?? bookingObj?.wait_min ?? rec?.wait_min ?? payloadObj?.wait_min ?? 0,
  );
  const outboundPickupIso =
    safeStr(
      fields.pickup_iso ??
        bookingObj?.pickup_iso ??
        bookingObj?.pickupStartIso ??
        rec?.pickup_iso ??
        quoteObj?.pickup_iso,
      80,
    ) || bookingPickupIsoFromRecord(rec || {});
  const returnPickupIso = safeStr(
    fields.return_pickup_iso ??
      bookingObj?.return_pickup_iso ??
      bookingObj?.returnPickupIso ??
      rec?.return_pickup_iso ??
      rec?.returnPickupIso,
    80,
  );
  const outboundFrom = safeStr(fields.from ?? bookingObj?.from ?? payloadObj?.from ?? quoteObj?.from, 320);
  const outboundTo = safeStr(fields.to ?? bookingObj?.to ?? payloadObj?.to ?? quoteObj?.to, 320);
  const returnFrom = safeStr(
    fields.return_from ?? bookingObj?.return_from ?? rec?.return_from ?? outboundTo,
    320,
  );
  const returnTo = safeStr(
    fields.return_to ?? bookingObj?.return_to ?? rec?.return_to ?? outboundFrom,
    320,
  );
  // Layer 1B: accept the same airport/customer aliases the /book payload and
  // the persisted booking record carry (pickup_lat / pickupLat / from_lat /
  // fromLat). bookingObj may be either bookingFields-shaped (from booking
  // creation) or the persisted booking record (from post-payment auto
  // dispatch) and both spellings must work.
  const outboundPickupLat =
    fields.pickup_lat ??
    fields.pickupLat ??
    fields.from_lat ??
    fields.fromLat ??
    bookingObj?.pickup_lat ??
    bookingObj?.pickupLat ??
    bookingObj?.from_lat ??
    bookingObj?.fromLat ??
    payloadObj?.pickup_lat ??
    payloadObj?.pickupLat ??
    payloadObj?.from_lat ??
    payloadObj?.fromLat ??
    null;
  const outboundPickupLng =
    fields.pickup_lng ??
    fields.pickupLng ??
    fields.from_lng ??
    fields.fromLng ??
    bookingObj?.pickup_lng ??
    bookingObj?.pickupLng ??
    bookingObj?.from_lng ??
    bookingObj?.fromLng ??
    payloadObj?.pickup_lng ??
    payloadObj?.pickupLng ??
    payloadObj?.from_lng ??
    payloadObj?.fromLng ??
    null;

  if (mode === "split_no_wait") {
    const legSpecs = _buildSplitRoundtripLegDispatchSpecs({
      parentBookingId: safeParentId,
      rec,
      bookingObj,
      payloadObj,
      quoteObj,
      env,
      outboundPickupIso,
      outboundFrom,
      outboundTo,
      outboundPickupLat,
      outboundPickupLng,
      returnPickupIso,
      returnFrom,
      returnTo,
      durationRouteMin,
      returnDurationMin,
      tier,
      pax,
      bags,
      stopCount,
    });
    const legResults = [];
    const acquiredReservations = [];
    for (const spec of legSpecs) {
      const existingLeg =
        _bookingOperationalLegsFromRecord(rec || {}).find((leg) => {
          const legType = safeStr(leg?.leg_type ?? leg?.legType, 24).toLowerCase();
          return legType === spec.legType;
        }) || null;
      const existingAssignment = _operationalLegAssignmentFromLeg(existingLeg);
      if (existingAssignment.assignedVehicleId || existingAssignment.assignedDriverId) {
        legResults.push({
          legKey: spec.legKey,
          legType: spec.legType,
          assignedVehicleId: existingAssignment.assignedVehicleId,
          assignedDriverId: existingAssignment.assignedDriverId,
          assignedDriver: null,
          skipped: true,
          reason: "already_assigned",
        });
        continue;
      }
      let result;
      try {
        result = await _requestFleetLegAllocation(env, spec, fleetScope, sourceLabel);
      } catch (err) {
        result = {
          ok: false,
          allowed: false,
          legKey: spec.legKey,
          legType: spec.legType,
          assignedVehicleId: null,
          assignedDriverId: null,
          assignedDriver: null,
          alloc: { reason: safeStr(err?.message || err, 120) || "exception" },
        };
      }
      if (result.ok) {
        acquiredReservations.push({
          bookingId: spec.allocatorBookingId,
          pickupIso: spec.pickupIso,
        });
        legResults.push(result);
      } else if (requireAllLegs) {
        await _releaseFleetLegReservations(env, acquiredReservations, fleetScope);
        return {
          ok: false,
          mode,
          assigned: false,
          reason: "not_allowed",
          allocator_reason: safeStr(result?.alloc?.reason, 80) || "vehicle_capacity_exceeded",
          legResults,
          reservations: acquiredReservations,
        };
      } else if (allowPartialLegAssignment) {
        legResults.push(result);
      }
    }
    const assignedLegs = legResults.filter((leg) => !!leg.assignedVehicleId);
    const allRequestedAssigned =
      legSpecs.length > 0 &&
      legSpecs.every((spec) =>
        legResults.some(
          (leg) =>
            leg.legKey === spec.legKey &&
            (!!leg.assignedVehicleId || leg.skipped === true),
        ),
      );
    return {
      ok: assignedLegs.length > 0 || allRequestedAssigned,
      mode,
      assigned: allRequestedAssigned,
      partial: assignedLegs.length > 0 && !allRequestedAssigned,
      reason: assignedLegs.length ? (allRequestedAssigned ? "assigned" : "partial_assigned") : "not_allowed",
      legResults,
      reservations: acquiredReservations,
      assignedVehicleId: assignedLegs[0]?.assignedVehicleId || null,
      assignedDriverId: assignedLegs[0]?.assignedDriverId || null,
      assignedDriver: assignedLegs[0]?.assignedDriver || null,
    };
  }

  const serviceMin = _operationalLegServiceMinForDispatch({
    durationMin: durationRouteMin,
    stopCount,
    waitMin,
    includeReturnDuration: mode === "continuous_wait" && !returnPickupIso,
    returnDurationMin,
    env,
  });
  const pickupMs = Date.parse(outboundPickupIso);
  const allocatorPayload = {
    action: "allocate",
    booking_id: safeParentId,
    pickup_ms: pickupMs,
    service_min: serviceMin,
    tier,
    pax,
    bags,
    from: outboundFrom,
    pickup_from: outboundFrom,
    pickup_address: outboundFrom,
    to: outboundTo,
    dropoff_to: outboundTo,
    dropoff_address: outboundTo,
    pickup_iso: outboundPickupIso,
    pickup_lat: outboundPickupLat,
    pickup_lng: outboundPickupLng,
    tenantScope: fleetScope,
  };
  console.log(
    `[ROUNDTRIP_DISPATCH][LEG_ALLOCATE_START] leg=parent booking=${maskedParentId} source=${safeStr(sourceLabel, 64) || "fleet_dispatch"}`,
  );
  let alloc;
  try {
    alloc = await _allocatorRequest(env, outboundPickupIso, allocatorPayload);
  } catch (allocErr) {
    return {
      ok: false,
      mode,
      assigned: false,
      reason: "allocator_error",
      allocator_reason: safeStr(allocErr?.message || allocErr, 120) || "exception",
    };
  }
  const vehicleId = safeStr(alloc?.assigned_vehicle_id, 128) || null;
  let assignedDriver =
    alloc?.assigned_driver && typeof alloc.assigned_driver === "object"
      ? alloc.assigned_driver
      : null;
  if (!assignedDriver && vehicleId) {
    try {
      assignedDriver = await _driverSummaryForVehicleId(env, vehicleId, fleetScope);
    } catch (_) {
      assignedDriver = null;
    }
  }
  const driverId =
    safeStr(
      assignedDriver?.driver_id ?? assignedDriver?.driverId ?? assignedDriver?.id,
      96,
    ) || null;
  console.log(
    `[ROUNDTRIP_DISPATCH][LEG_ALLOCATE_RESULT] leg=parent booking=${maskedParentId} allowed=${alloc?.allowed === true ? "true" : "false"} vehicle=${_bookingIntentMask(vehicleId)} driver=${_bookingIntentMask(driverId)} reason=${safeStr(alloc?.reason, 80) || "-"}`,
  );
  if (mode === "continuous_wait") {
    console.log(
      `[ROUNDTRIP_DISPATCH][PARENT_ASSIGNMENT] mode=continuous_wait booking=${maskedParentId} vehicle=${_bookingIntentMask(vehicleId)} driver=${_bookingIntentMask(driverId)}`,
    );
  }
  return {
    ok: alloc?.allowed === true && !!vehicleId,
    mode,
    assigned: alloc?.allowed === true && !!vehicleId,
    reason: alloc?.allowed ? (vehicleId ? "assigned" : "allocator_returned_no_vehicle") : "not_allowed",
    allocator_reason: safeStr(alloc?.reason, 80) || null,
    alloc,
    assignedVehicleId: vehicleId,
    assignedDriverId: driverId,
    assignedDriver,
    reservations: vehicleId
      ? [{ bookingId: safeParentId, pickupIso: outboundPickupIso }]
      : [],
  };
}

// G3: idempotent post-finalize hook that asks the existing FleetAllocatorDO to
// allocate a vehicle/driver for a paid, open, unassigned canonical booking.
//
// Constraints (do not change without G3 review):
// - Only runs when FLEET_AVAILABILITY_MODE === "multi_vehicle".
// - Only runs for paid + open-like + unassigned canonical records.
// - Never assigns blindly: it strictly forwards the existing allocator's
//   `allowed === true` decision. On `allowed === false` it leaves the record
//   untouched so the booking remains visible in Driver > Available.
// - Re-uses _allocatorRequest, _driverSummaryForVehicleId, the same index
//   upserters used by the BOOKED branch, and the same operational-leg shape.
// - Logs are masked via _bookingIntentMask. No PII in logs.
async function ensurePaidOpenBookingAutoDispatched(
  env,
  bookingId,
  rec,
  request,
  opts = {},
) {
  const safeBookingId = safeStr(bookingId, 160);
  const maskedBookingId = _bookingIntentMask(safeBookingId);
  const persist = opts?.persist !== false;
  const sourceLabel = safeStr(opts?.source, 64) || "auto_dispatch";

  const skip = (reason, extra = {}) => {
    console.log(
      `[DISPATCH_AUTO_ASSIGN][SKIP] booking=${maskedBookingId} reason=${reason} source=${sourceLabel}`,
    );
    return {
      ok: true,
      skipped: true,
      mutated: false,
      reason,
      assigned: false,
      assigned_driver_id: null,
      assigned_vehicle_id: null,
      ...extra,
    };
  };

  try {
    if (!env?.BOOKING_KV) return skip("missing_kv");
    if (!env?.FLEET_ALLOCATOR) return skip("missing_allocator_binding");
    if (!safeBookingId) return skip("missing_booking_id");
    if (!rec || typeof rec !== "object") return skip("missing_record");

    if (_availabilityMode(env) !== "multi_vehicle") {
      return skip("mode_not_multi_vehicle");
    }

    if (isTerminalLifecycleStatus(_bookingLifecycleValue(rec))) {
      return skip("terminal_status");
    }

    const dispatchMode = resolveRoundtripDispatchMode(rec);
    if (dispatchMode === "split_no_wait") {
      const operationalLegs = _bookingOperationalLegsFromRecord(rec);
      const unassignedLegs = operationalLegs.filter((leg) => {
        const assignment = _operationalLegAssignmentFromLeg(leg);
        return !assignment.assignedVehicleId && !assignment.assignedDriverId;
      });
      if (!unassignedLegs.length && operationalLegs.length > 0) {
        console.log(
          `[DISPATCH_AUTO_ASSIGN][SKIP] booking=${maskedBookingId} reason=already_assigned source=${sourceLabel} mode=${dispatchMode}`,
        );
        return {
          ok: true,
          skipped: true,
          mutated: false,
          reason: "already_assigned",
          assigned: true,
          assigned_driver_id: safeStr(bookingAssignedDriverId(rec), 96) || null,
          assigned_vehicle_id: safeStr(bookingAssignedVehicleId(rec), 128) || null,
        };
      }
    } else {
      const existingVehicleId = safeStr(bookingAssignedVehicleId(rec), 128);
      const existingDriverId = safeStr(bookingAssignedDriverId(rec), 96);
      if (existingVehicleId || existingDriverId) {
        console.log(
          `[DISPATCH_AUTO_ASSIGN][SKIP] booking=${maskedBookingId} reason=already_assigned source=${sourceLabel} vehicle=${_bookingIntentMask(existingVehicleId)} driver=${_bookingIntentMask(existingDriverId)}`,
        );
        return {
          ok: true,
          skipped: true,
          mutated: false,
          reason: "already_assigned",
          assigned: true,
          assigned_driver_id: existingDriverId || null,
          assigned_vehicle_id: existingVehicleId || null,
        };
      }
    }

    const recordScope = resolveBookingTenantScopeFromRecord(rec);
    const scopeHint = opts?.tenantScope?.hasScope ? opts.tenantScope : recordScope;
    const fleetScope = normalizeFleetTenantScope(scopeHint);
    if (!fleetScope?.hasScope) {
      return skip("missing_scope");
    }

    const bookingObj = rec?.booking && typeof rec.booking === "object" ? rec.booking : {};
    const payloadObj = rec?.payload && typeof rec.payload === "object" ? rec.payload : {};
    const quoteObj = rec?.quote && typeof rec.quote === "object" ? rec.quote : {};

    const paymentStatusToken = _normalizeDriverAvailableLifecycleToken(
      rec?.payment_status ??
        rec?.paymentStatus ??
        bookingObj?.payment_status ??
        bookingObj?.paymentStatus ??
        payloadObj?.payment_status ??
        payloadObj?.paymentStatus,
    );
    const paidAt = safeStr(
      rec?.paid_at ??
        rec?.paidAt ??
        bookingObj?.paid_at ??
        bookingObj?.paidAt,
      80,
    );
    const paymentMode = _normalizeDriverAvailableLifecycleToken(
      rec?.payment_mode ??
        rec?.paymentMode ??
        bookingObj?.payment_mode ??
        bookingObj?.paymentMode ??
        payloadObj?.payment_mode ??
        payloadObj?.paymentMode,
    );
    const paymentProvider = _normalizeDriverAvailableLifecycleToken(
      rec?.payment_provider ??
        rec?.paymentProvider ??
        bookingObj?.payment_provider ??
        bookingObj?.paymentProvider ??
        payloadObj?.payment_provider ??
        payloadObj?.paymentProvider,
    );
    const isOnlineLike =
      paymentMode === "mollie" ||
      paymentMode === "online" ||
      paymentMode === "online_payment" ||
      paymentMode === "online_payments" ||
      paymentMode === "prepaid" ||
      paymentProvider === "mollie" ||
      paymentProvider === "online" ||
      paymentProvider === "online_payment" ||
      paymentProvider === "prepaid";
    const isManualLike =
      paymentMode === "manual" ||
      paymentMode === "cash" ||
      paymentMode === "invoice" ||
      paymentMode === "in_vehicle" ||
      paymentMode === "in_vehicle_card" ||
      paymentProvider === "manual" ||
      paymentProvider === "cash" ||
      paymentProvider === "invoice" ||
      paymentProvider === "in_vehicle_card" ||
      paymentProvider === "qr";
    const paidLike =
      DRIVER_AVAILABLE_ONLINE_PAID_STATUSES.has(paymentStatusToken) || !!paidAt;
    if (isOnlineLike && !isManualLike && !paidLike) {
      return skip("payment_not_paid");
    }

    const pickupIso = bookingPickupIsoFromRecord(rec);
    const pickupMs = Date.parse(pickupIso);
    if (!pickupIso || !Number.isFinite(pickupMs)) {
      return skip("pickup_invalid");
    }

    console.log(
      `[DISPATCH_AUTO_ASSIGN][START] booking=${maskedBookingId} source=${sourceLabel} tenant=${_bookingIntentMask(fleetScope.tenant_id)} company=${_bookingIntentMask(fleetScope.company_id)} pickup_iso=${pickupIso || "-"} mode=${dispatchMode}`,
    );

    let dispatchOutcome;
    try {
      const splitNoWait = dispatchMode === "split_no_wait";
      dispatchOutcome = await _dispatchFleetAssignmentForBooking(env, {
        parentBookingId: safeBookingId,
        rec,
        fleetScope,
        sourceLabel,
        // Split no-wait roundtrips must allocate both legs or neither —
        // do not persist a paid booking with only outbound assigned.
        requireAllLegs: splitNoWait,
        allowPartialLegAssignment: !splitNoWait,
      });
    } catch (dispatchErr) {
      const reason = safeStr(dispatchErr?.message || dispatchErr, 140) || "exception";
      console.log(
        `[DISPATCH_AUTO_ASSIGN][ERROR] booking=${maskedBookingId} stage=allocator_request reason=${reason}`,
      );
      return {
        ok: true,
        skipped: true,
        mutated: false,
        reason: "allocator_error",
        allocator_reason: reason,
        assigned: false,
        assigned_driver_id: null,
        assigned_vehicle_id: null,
      };
    }

    const allocatorReason = safeStr(dispatchOutcome?.allocator_reason, 80) || null;
    console.log(
      `[DISPATCH_AUTO_ASSIGN][ALLOCATOR_RESULT] booking=${maskedBookingId} allowed=${dispatchOutcome?.ok === true ? "true" : "false"} mode=${safeStr(dispatchOutcome?.mode, 24) || "-"} reason=${safeStr(dispatchOutcome?.reason, 80) || "-"} allocator_reason=${allocatorReason || "-"}`,
    );

    if (!dispatchOutcome?.ok) {
      return {
        ok: true,
        skipped: true,
        mutated: false,
        reason: "not_allowed",
        allocator_reason: allocatorReason || "vehicle_capacity_exceeded",
        assigned: false,
        assigned_driver_id: null,
        assigned_vehicle_id: null,
      };
    }

    const nowIso = new Date().toISOString();
    if (dispatchOutcome.mode === "split_no_wait") {
      _applySplitRoundtripLegAssignmentsToRecord(rec, dispatchOutcome.legResults || [], nowIso);
      for (const legResult of dispatchOutcome.legResults || []) {
        if (!legResult?.assignedVehicleId) continue;
        console.log(
          `[ROUNDTRIP_DISPATCH][LEG_ASSIGNMENT_WRITE] leg=${safeStr(legResult?.legKey, 24).toLowerCase() || "leg"} booking=${maskedBookingId} assigned_vehicle=${_bookingIntentMask(legResult.assignedVehicleId)} assigned_driver=${_bookingIntentMask(legResult.assignedDriverId)}`,
        );
      }
    } else {
      const allocVehicleId = safeStr(dispatchOutcome?.assignedVehicleId, 128);
      const assignedDriverId = safeStr(dispatchOutcome?.assignedDriverId, 96) || null;
      const assignedDriver =
        dispatchOutcome?.assignedDriver && typeof dispatchOutcome.assignedDriver === "object"
          ? dispatchOutcome.assignedDriver
          : null;
      if (!allocVehicleId) {
        console.log(
          `[DISPATCH_AUTO_ASSIGN][SKIP] booking=${maskedBookingId} reason=allocator_returned_no_vehicle source=${sourceLabel}`,
        );
        return {
          ok: true,
          skipped: true,
          mutated: false,
          reason: "allocator_returned_no_vehicle",
          allocator_reason: allocatorReason,
          assigned: false,
          assigned_driver_id: null,
          assigned_vehicle_id: null,
        };
      }
      rec.assigned_vehicle_id = allocVehicleId;
      rec.assignedVehicleId = allocVehicleId;
      if (assignedDriver && typeof assignedDriver === "object") {
        rec.assigned_driver = assignedDriver;
        rec.assignedDriver = assignedDriver;
      }
      if (assignedDriverId) {
        rec.assigned_driver_id = assignedDriverId;
        rec.assignedDriverId = assignedDriverId;
      }
      if (dispatchMode === "continuous_wait") {
        rec.roundtrip_dispatch_mode = "continuous_wait";
        rec.roundtripDispatchMode = "continuous_wait";
      }
      rec.updated_at = nowIso;
      rec.updatedAt = nowIso;
      if (rec.booking && typeof rec.booking === "object") {
        rec.booking.assigned_vehicle_id = allocVehicleId;
        rec.booking.assignedVehicleId = allocVehicleId;
        if (assignedDriver && typeof assignedDriver === "object") {
          rec.booking.assigned_driver = assignedDriver;
          rec.booking.assignedDriver = assignedDriver;
        }
        if (assignedDriverId) {
          rec.booking.assigned_driver_id = assignedDriverId;
          rec.booking.assignedDriverId = assignedDriverId;
        }
        rec.booking.updated_at = nowIso;
        rec.booking.updatedAt = nowIso;
      }
      const stampLegs = (legs) => {
        if (!Array.isArray(legs)) return legs;
        for (const leg of legs) {
          _stampOperationalLegFleetAssignment(leg, {
            vehicleId: allocVehicleId,
            driver: assignedDriver,
            driverId: assignedDriverId,
            nowIso,
          });
        }
        return legs;
      };
      if (Array.isArray(rec.operational_legs)) stampLegs(rec.operational_legs);
      if (Array.isArray(rec.operationalLegs)) stampLegs(rec.operationalLegs);
      if (rec.booking && typeof rec.booking === "object") {
        if (Array.isArray(rec.booking.operational_legs)) stampLegs(rec.booking.operational_legs);
        if (Array.isArray(rec.booking.operationalLegs)) stampLegs(rec.booking.operationalLegs);
      }
    }

    const writeBackVehicleId = safeStr(rec?.assigned_vehicle_id ?? rec?.assignedVehicleId, 128);
    const writeBackDriverId = safeStr(rec?.assigned_driver_id ?? rec?.assignedDriverId, 96);
    console.log(
      `[DISPATCH_AUTO_ASSIGN][WRITE_BACK] booking=${maskedBookingId} vehicle=${_bookingIntentMask(writeBackVehicleId)} driver=${_bookingIntentMask(writeBackDriverId)} persist=${persist ? "true" : "false"} mode=${safeStr(dispatchOutcome?.mode, 24) || "-"}`,
    );

    if (persist) {
      try {
        await env.BOOKING_KV.put(`booking:${safeBookingId}`, JSON.stringify(rec));
      } catch (putErr) {
        const reason = safeStr(putErr?.message || putErr, 140) || "exception";
        console.log(
          `[DISPATCH_AUTO_ASSIGN][ERROR] booking=${maskedBookingId} stage=kv_put reason=${reason}`,
        );
        return {
          ok: false,
          skipped: false,
          mutated: false,
          reason: "kv_put_failed",
          assigned: false,
          assigned_driver_id: null,
          assigned_vehicle_id: null,
          error: reason,
        };
      }
      try {
        await upsertBookingDemandIndexBestEffort(env, safeBookingId, rec, fleetScope);
      } catch (_) {
        // Best-effort index emission only.
      }
      try {
        await upsertDriverVehicleBookingIndexesBestEffort(
          env,
          safeBookingId,
          rec,
          fleetScope,
        );
      } catch (_) {
        // Best-effort index emission only.
      }
      try {
        await upsertCompanyBookingsListIndexBestEffort(
          env,
          safeBookingId,
          rec,
          fleetScope,
        );
      } catch (_) {
        // Best-effort index emission only.
      }
      try {
        await upsertDashboardBookingsKpiProjectionBestEffort(
          env,
          safeBookingId,
          rec,
          fleetScope,
        );
      } catch (_) {
        // Best-effort projection update only.
      }
    }

    console.log(
      `[DISPATCH_AUTO_ASSIGN][DONE] booking=${maskedBookingId} source=${sourceLabel} vehicle=${_bookingIntentMask(writeBackVehicleId)} driver=${_bookingIntentMask(writeBackDriverId)} persisted=${persist ? "true" : "false"} mode=${safeStr(dispatchOutcome?.mode, 24) || "-"}`,
    );

    return {
      ok: true,
      skipped: false,
      mutated: true,
      reason: dispatchOutcome?.partial ? "partial_assigned" : "assigned",
      allocator_reason: allocatorReason,
      assigned: dispatchOutcome?.assigned === true,
      partial: dispatchOutcome?.partial === true,
      assigned_driver_id: writeBackDriverId || null,
      assigned_vehicle_id: writeBackVehicleId || null,
      roundtrip_dispatch_mode: safeStr(dispatchOutcome?.mode, 24) || null,
    };
  } catch (err) {
    const reason = safeStr(err?.message || err, 140) || "exception";
    console.log(
      `[DISPATCH_AUTO_ASSIGN][ERROR] booking=${maskedBookingId} stage=helper reason=${reason}`,
    );
    return {
      ok: false,
      skipped: false,
      mutated: false,
      reason: "exception",
      assigned: false,
      assigned_driver_id: null,
      assigned_vehicle_id: null,
      error: reason,
    };
  }
}

async function finalizeResumePaidPaymentToCanonical(stored, env, request, opts = {}) {
  const paymentBookingId = safeStr(
    opts?.paymentBookingId || stored?.bookingId || stored?.booking_id,
    160,
  );
  const canonicalBookingId = resolveCanonicalBookingIdForPaidPayment(stored, paymentBookingId);
  const nowIso = new Date().toISOString();
  stored.finalize_debug = stored.finalize_debug || {};
  stored.finalize_debug.attempted_at = nowIso;
  stored.finalize_debug.payment_booking_id = paymentBookingId || null;
  stored.finalize_debug.canonical_booking_id = canonicalBookingId || null;

  console.log(
    `[PAYMENT_FINALIZE][RESUME_INVOKE] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} hasTenantScope=${opts?.tenantScope?.hasScope === true}`,
  );

  if (!paymentBookingId || !canonicalBookingId) {
    stored.confirm_error = "resume_finalize_missing_canonical_booking_id";
    stored.finalize_debug.stage = "resume_paid_canonical_rejected";
    stored.finalize_debug.error = stored.confirm_error;
    stored.confirming_at = null;
    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }

  const tenantScope =
    opts?.tenantScope && opts.tenantScope.hasScope
      ? opts.tenantScope
      : _tenantScopeFromStoredPaymentRecord(stored);
  if (!tenantScope?.hasScope) {
    stored.confirm_error = "missing_tenant_scope_for_resume_finalize";
    stored.finalize_debug.stage = "resume_paid_canonical_rejected";
    stored.finalize_debug.error = stored.confirm_error;
    stored.confirming_at = null;
    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }

  let canonicalKey = "";
  let canonicalRec = null;
  try {
    const loaded = await loadBookingRecord(env, canonicalBookingId);
    canonicalKey = loaded.key;
    canonicalRec = loaded.rec;
  } catch (loadErr) {
    if (String(loadErr?.message || "") === "Booking not found") {
      stored.confirm_error = "canonical_booking_not_found";
      stored.finalize_debug.stage = "resume_paid_canonical_rejected";
      stored.finalize_debug.error = stored.confirm_error;
      stored.confirming_at = null;
      return { ok: false, updatedStored: stored, error: stored.confirm_error };
    }
    throw loadErr;
  }

  if (!bookingMatchesRequiredTenantCompanyScope(canonicalRec, tenantScope)) {
    stored.confirm_error = "forbidden";
    stored.finalize_debug.stage = "resume_paid_canonical_rejected";
    stored.finalize_debug.error = stored.confirm_error;
    stored.confirming_at = null;
    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }

  if (!_canonicalAcceptsResumePaymentBookingId(canonicalRec, paymentBookingId, canonicalBookingId)) {
    stored.confirm_error = "resume_payment_booking_id_mismatch";
    stored.finalize_debug.stage = "resume_paid_canonical_rejected";
    stored.finalize_debug.error = stored.confirm_error;
    stored.confirming_at = null;
    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }

  const incomingMolliePaymentId = safeStr(
    stored?.payment_id ??
      stored?.paymentId ??
      stored?.mollie?.payment_id ??
      stored?.mollie?.id,
    120,
  );
  const existingPaymentStatus = safeStr(
    canonicalRec?.payment_status ?? canonicalRec?.paymentStatus,
    40,
  ).toLowerCase();
  const existingMolliePaymentId = safeStr(
    canonicalRec?.payment_id ??
      canonicalRec?.paymentId ??
      canonicalRec?.mollie?.payment_id ??
      canonicalRec?.mollie?.id,
    120,
  );
  if (
    existingPaymentStatus === "paid" &&
    (!incomingMolliePaymentId ||
      !existingMolliePaymentId ||
      existingMolliePaymentId === incomingMolliePaymentId)
  ) {
    stored.confirmed_at = stored.confirmed_at || nowIso;
    stored.confirming_at = null;
    stored.finalize_debug.stage = "resume_paid_canonical_already_paid";
    stored.finalize_debug.error = null;
    return {
      ok: true,
      updatedStored: stored,
      already: true,
      canonicalBookingId,
    };
  }

  _applyResumePaidPaymentToCanonicalRecord(canonicalRec, stored, {
    paymentBookingId,
    molliePaymentId: incomingMolliePaymentId,
    paidAt: stored?.paid_at || stored?.paidAt,
  });

  const invoiceContext = _invoiceLifecycleContextFromRecord(canonicalRec);
  _applyPaymentInvoiceLifecycleToRecord(canonicalRec, {
    paymentMode: "mollie",
    paymentProvider: "mollie",
    paymentStatus: "paid",
    invoiceRequested:
      invoiceContext.businessInvoiceIntent ? true : invoiceContext.invoiceRequested,
    invoiceIntent: invoiceContext.businessInvoiceIntent
      ? "business_invoice"
      : invoiceContext.invoiceIntent,
    invoiceState: invoiceContext.businessInvoiceIntent ? "ready_to_send" : "none",
  });

  // G3-M: Persist the canonical paid state and refresh demand/driver/vehicle/
  // company/dashboard indexes BEFORE invoking the auto-dispatch helper.
  //
  // Previous order ran ensurePaidOpenBookingAutoDispatched against the
  // in-memory record while the demand index and KV record still reflected
  // the old "pending" state. The allocator's _evaluateFleetAvailability +
  // _loadScopedActiveDemandWithRepair re-read those indexes, so the just-
  // marked-paid booking would either still appear as competing unassigned
  // demand or fail the canonical-record consistency checks, returning
  // not_allowed / vehicle_capacity_exceeded. A manual /admin/dispatch/ensure
  // seconds later succeeded because by then the indexes had settled.
  //
  // This block is what was already running below the dispatch call; we just
  // moved it ABOVE so the allocator sees a fully consistent view, and we
  // pass persist:true to the dispatch helper so it owns the post-assignment
  // KV.put + index re-emission. No new payment, invoice, or email side-
  // effects are introduced here.
  await env.BOOKING_KV.put(canonicalKey, JSON.stringify(canonicalRec));
  const fleetScope = normalizeFleetTenantScope(tenantScope);
  await upsertBookingDemandIndexBestEffort(env, canonicalBookingId, canonicalRec, fleetScope);
  await upsertDriverVehicleBookingIndexesBestEffort(
    env,
    canonicalBookingId,
    canonicalRec,
    fleetScope,
  );
  await upsertCompanyBookingsListIndexBestEffort(
    env,
    canonicalBookingId,
    canonicalRec,
    fleetScope,
  );
  await upsertDashboardBookingsKpiProjectionBestEffort(
    env,
    canonicalBookingId,
    canonicalRec,
    fleetScope,
  );
  await syncScopedTrackingTripKpiBestEffort({
    env,
    bookingId: canonicalBookingId,
    rec: canonicalRec,
    tenantScope,
    source: "mollie_resume_pay_status_paid",
  });

  // G3: hand the now-paid canonical record to the existing FleetAllocator so
  // resumed Mollie payments do not stay paid-but-unassigned. The helper is
  // idempotent and respects the allocator's "not allowed" decisions; on a
  // skip/deny the canonical record stays unchanged and remains visible in
  // Driver > Available exactly as before. persist:true so the helper itself
  // owns the post-assignment KV.put + index updates (the canonical paid
  // state is already on disk above; helper either no-ops or replaces with
  // assigned state).
  let dispatchOutcome = null;
  try {
    dispatchOutcome = await ensurePaidOpenBookingAutoDispatched(
      env,
      canonicalBookingId,
      canonicalRec,
      request,
      {
        tenantScope,
        persist: true,
        source: "mollie_resume_pay_status_paid",
      },
    );
  } catch (dispatchErr) {
    const reason = safeStr(dispatchErr?.message || dispatchErr, 140) || "exception";
    console.log(
      `[DISPATCH_AUTO_ASSIGN][ERROR] booking=${_bookingIntentMask(canonicalBookingId)} stage=resume_finalize reason=${reason}`,
    );
    dispatchOutcome = null;
  }
  console.log(
    `[DISPATCH_POST_PAYMENT][RESUME_FINALIZE] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} assigned=${dispatchOutcome?.assigned === true} reason=${safeStr(dispatchOutcome?.reason, 80) || "-"} allocator_reason=${safeStr(dispatchOutcome?.allocator_reason, 80) || "-"} skipped=${dispatchOutcome?.skipped === true}`,
  );

  // G3-M: One safe retry when the first attempt was rejected with
  // vehicle_capacity_exceeded. We reload the canonical record from KV (in
  // case any other path mutated it concurrently), re-upsert the demand
  // index defensively, then re-call the same idempotent dispatch helper.
  //
  // This is NOT a manual assignment; the retry is gated to the specific
  // false-negative we observed in the resume-finalize race, and the
  // allocator's existing rules (suitability, ETA, tenant scope, tier,
  // driver/vehicle availability, demand conflicts) still decide. If the
  // retry also legitimately rejects, we leave the booking visible in
  // Driver > Available exactly as the no-retry path would.
  const firstAllocatorReason = safeStr(dispatchOutcome?.allocator_reason, 80).toLowerCase();
  const firstReason = safeStr(dispatchOutcome?.reason, 80).toLowerCase();
  const shouldRetry =
    dispatchOutcome &&
    dispatchOutcome.assigned !== true &&
    firstReason === "not_allowed" &&
    firstAllocatorReason === "vehicle_capacity_exceeded";
  if (shouldRetry) {
    console.log(
      `[DISPATCH_POST_PAYMENT][RESUME_RETRY] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} reason=${firstReason} allocator_reason=${firstAllocatorReason}`,
    );
    let retryRec = canonicalRec;
    try {
      const reloaded = await loadBookingRecord(env, canonicalBookingId);
      if (
        reloaded?.rec &&
        bookingMatchesRequiredTenantCompanyScope(reloaded.rec, tenantScope)
      ) {
        retryRec = reloaded.rec;
        canonicalRec = reloaded.rec;
        console.log(
          `[PAYMENT_FINALIZE][CANONICAL_RELOADED] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} payment_status=${safeStr(retryRec?.payment_status || retryRec?.paymentStatus, 24) || "-"} assigned=${retryRec?.assigned_vehicle_id || retryRec?.assignedVehicleId ? "true" : "false"}`,
        );
      } else {
        console.log(
          `[PAYMENT_FINALIZE][CANONICAL_RELOADED] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} reason=${reloaded?.rec ? "scope_mismatch" : "not_found"} fallback=in_memory`,
        );
      }
    } catch (reloadErr) {
      console.log(
        `[PAYMENT_FINALIZE][CANONICAL_RELOADED] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} reason=reload_error fallback=in_memory error=${safeStr(reloadErr?.message || reloadErr, 80) || "exception"}`,
      );
    }
    try {
      await upsertBookingDemandIndexBestEffort(
        env,
        canonicalBookingId,
        retryRec,
        fleetScope,
      );
    } catch (_) {
      // Best-effort defensive demand-index refresh.
    }
    let retryOutcome = null;
    try {
      retryOutcome = await ensurePaidOpenBookingAutoDispatched(
        env,
        canonicalBookingId,
        retryRec,
        request,
        {
          tenantScope,
          persist: true,
          source: "mollie_resume_pay_status_paid_retry",
        },
      );
    } catch (retryErr) {
      const reason = safeStr(retryErr?.message || retryErr, 140) || "exception";
      console.log(
        `[DISPATCH_AUTO_ASSIGN][ERROR] booking=${_bookingIntentMask(canonicalBookingId)} stage=resume_finalize_retry reason=${reason}`,
      );
      retryOutcome = null;
    }
    console.log(
      `[DISPATCH_POST_PAYMENT][RESUME_RETRY_RESULT] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} assigned=${retryOutcome?.assigned === true} reason=${safeStr(retryOutcome?.reason, 80) || "-"} allocator_reason=${safeStr(retryOutcome?.allocator_reason, 80) || "-"} skipped=${retryOutcome?.skipped === true}`,
    );
    if (retryOutcome) dispatchOutcome = retryOutcome;
  }

  stored.confirmed_at = stored.confirmed_at || nowIso;
  stored.confirming_at = null;
  stored.public_booking_id = stored.public_booking_id || canonicalBookingId;
  stored.finalize_debug = {
    at: nowIso,
    stage: "resume_paid_canonical_updated",
    payment_booking_id: paymentBookingId,
    canonical_booking_id: canonicalBookingId,
    payment_id: incomingMolliePaymentId || null,
    dispatch_reason: dispatchOutcome?.reason || null,
    dispatch_assigned: dispatchOutcome?.assigned === true,
    error: null,
  };

  console.log(
    `[BOOKING][CHECKOUT_RESUME][PAID_FINALIZE] paymentBooking=${_bookingIntentMask(paymentBookingId)} canonical=${_bookingIntentMask(canonicalBookingId)} molliePayment=${_bookingIntentMask(incomingMolliePaymentId)} dispatch=${dispatchOutcome?.reason || "skipped"}`,
  );

  return {
    ok: true,
    updatedStored: stored,
    canonicalBookingId,
    canonicalRec,
    dispatchOutcome,
  };
}

function _payStatusFirstScope(scopes = []) {
  for (const scope of scopes) {
    if (scope?.hasScope) return scope;
  }
  return null;
}

function _payStatusScopesConflict(a, b) {
  if (!a?.hasScope || !b?.hasScope) return false;
  return !_payStatusScopeMatches(a, b);
}

async function _resolvePaymentReturnScope(env, id) {
  const bookingId = safeStr(id, 160);
  if (!bookingId || !env?.BOOKING_KV) return { hasScope: false };
  const candidateScopes = [];
  const candidateBookings = [];

  try {
    const bookingRec = await env.BOOKING_KV.get(`booking:${bookingId}`, { type: "json" });
    if (bookingRec && typeof bookingRec === "object") {
      const bookingScope = _payStatusScopeFromBookingRecord(bookingRec);
      if (bookingScope?.hasScope) candidateScopes.push(bookingScope);
    }
  } catch (_) {}

  let paymentRec = null;
  try {
    const loaded = await env.BOOKING_KV.get(`payment:${bookingId}`, { type: "json" });
    if (loaded && typeof loaded === "object") {
      paymentRec = loaded;
      const paymentScope = _payStatusScopeFromPaymentRecord(loaded);
      if (paymentScope?.hasScope) candidateScopes.push(paymentScope);
      const hintedBookingIds = _payStatusBookingIdCandidates(loaded, bookingId, true);
      for (const hintedBookingId of hintedBookingIds) {
        if (!hintedBookingId) continue;
        if (!candidateBookings.includes(hintedBookingId)) {
          candidateBookings.push(hintedBookingId);
        }
      }
    }
  } catch (_) {}

  if (!candidateBookings.includes(bookingId)) {
    candidateBookings.push(bookingId);
  }
  if (paymentRec) {
    const hintedFromPayment = _payStatusBookingIdCandidates(paymentRec, bookingId, true);
    for (const hintedBookingId of hintedFromPayment) {
      if (!hintedBookingId) continue;
      if (!candidateBookings.includes(hintedBookingId)) {
        candidateBookings.push(hintedBookingId);
      }
    }
  }

  for (const candidateBookingId of candidateBookings) {
    try {
      const loaded = await loadBookingRecord(env, candidateBookingId);
      const bookingScope = _payStatusScopeFromBookingRecord(loaded?.rec);
      if (bookingScope?.hasScope) candidateScopes.push(bookingScope);
    } catch (_) {
      // Best-effort only for /pay/return rendering.
    }
  }

  let resolved = null;
  for (const scope of candidateScopes) {
    if (!scope?.hasScope) continue;
    if (!resolved) {
      resolved = scope;
      continue;
    }
    if (_payStatusScopesConflict(resolved, scope)) {
      return { hasScope: false };
    }
  }

  const firstScope = _payStatusFirstScope([resolved]);
  if (!firstScope?.hasScope) return { hasScope: false };
  return {
    tenant_id: firstScope.tenant_id,
    company_id: firstScope.company_id,
    hasScope: true,
  };
}

async function payStatus(request, env, requestedScopeOverride = null) {
  const url = new URL(request.url);
  const id = (url.searchParams.get("id") || "").trim();
  if (!id) return json({ ok: false, error: "missing id" }, 400);

  // Backwards compatible keys
  const kvKeyBooking = `booking:${id}`;
  const kvKeyPayment = `payment:${id}`;

  // Determine which key exists
  const hasPaymentKey = !!(await env.BOOKING_KV.get(kvKeyPayment));
  const keyToUse = hasPaymentKey ? kvKeyPayment : kvKeyBooking;

  let data = await env.BOOKING_KV.get(keyToUse, "json");
  if (!data && !hasPaymentKey) {
    // if booking key didn't exist, try payment key (edge)
    data = await env.BOOKING_KV.get(kvKeyPayment, "json");
  }
  if (!data) return json({ ok: false, error: "not found" }, 404);

  const resolvedScope =
    requestedScopeOverride && requestedScopeOverride.hasScope
      ? requestedScopeOverride
      : resolveExplicitBookingRequestScope({
          request,
          url,
          allowLegacyFallback: false,
        });
  if (!resolvedScope?.hasScope) {
    return json(
      resolvedScope?.error === "tenant_scope_conflict" ? scopeConflictError() : missingTenantScopeError(),
      400,
    );
  }
  const requestedScope = {
    tenant_id: _scopeText(resolvedScope.tenant_id),
    company_id: _scopeText(resolvedScope.company_id),
    hasScope: true,
  };

  let linkedBooking = null;
  const bookingCandidates = _payStatusBookingIdCandidates(data, id, !hasPaymentKey);
  for (const bookingId of bookingCandidates) {
    try {
      const loaded = await loadBookingRecord(env, bookingId);
      if (loaded?.rec) {
        linkedBooking = { booking_id: bookingId, key: loaded.key, rec: loaded.rec };
        break;
      }
    } catch (_) {
      // Try next candidate.
    }
  }

  const bookingScope = _payStatusScopeFromBookingRecord(linkedBooking?.rec);
  const paymentScope = _payStatusScopeFromPaymentRecord(data);

  if (bookingScope && !_payStatusScopeMatches(bookingScope, requestedScope)) {
    return json({ ok: false, error: "forbidden" }, 403);
  }
  if (paymentScope && !_payStatusScopeMatches(paymentScope, requestedScope)) {
    return json({ ok: false, error: "forbidden" }, 403);
  }
  if (!bookingScope && !paymentScope) {
    return json({ ok: false, error: "forbidden" }, 403);
  }
  if (linkedBooking?.rec && !bookingMatchesRequestedTenantScope(linkedBooking.rec, requestedScope)) {
    return json({ ok: false, error: "forbidden" }, 403);
  }

  const effectiveScope = requestedScope;

  // Helper: clear stale confirming lock
  const clearStaleLockIfNeeded = () => {
    try {
      if (data?.confirming_at) {
        const started = Date.parse(data.confirming_at);
        // If lock older than 3 minutes, consider it stale and recover.
        if (Number.isFinite(started) && (Date.now() - started) > 180_000) {
          data.confirming_at = null;
          data.confirm_error = (data.confirm_error || "") + (data.confirm_error ? " | " : "") + "Recovered stale confirming_at lock";
        }
      }
    } catch (_) {}
  };

  // Always attempt stale-lock recovery (prevents permanent deadlocks)
  clearStaleLockIfNeeded();

  // If Mollie payment exists, fetch latest status (best effort)
  const paymentId = data?.mollie?.payment_id || data?.mollie?.id || data?.mollie_payment_id || data?.payment_id;

  // We will persist back no matter what happens
  let finalizeAttempted = false;
  let compliancePaymentUpdateEmitAttempted = false;

  try {
    if (paymentId) {
      const rideCredentials = await resolveRideMollieCredentialsForPaymentRecord(
        env,
        linkedBooking?.rec || data,
      );
      if (!rideCredentials.ok) {
        data.mollie_credentials_error = safeStr(rideCredentials.error, 80) || "ride_mollie_credentials_required";
        data.mollieCredentialsError = data.mollie_credentials_error;
      }
      const pay = rideCredentials.ok
        ? await mollieFetchPaymentJson(paymentId, env, rideCredentials)
        : null;
      if (!pay) {
        throw new Error(data.mollie_credentials_error || "ride_mollie_credentials_required");
      }
      const status = pay?.status || null;
      const mollieMethod = safeStr(pay?.method, 64) || null;
      const normalized = normalizedPaymentFields({
        status,
        paymentId,
        paidAt: data?.paid_at,
        paymentMethod: mollieMethod,
      });

      Object.assign(data, normalized);
      data.mollie = data.mollie || {};
      data.mollie.status = status;
      data.mollie.last_checked_at = new Date().toISOString();
      if (mollieMethod) {
        data.mollie.method = mollieMethod;
      }

      // Keep webhook timestamp if present
      if (data?.mollie?.last_webhook_at) {
        data.mollie.last_webhook_at = data.mollie.last_webhook_at;
      }

      // If paid and not yet confirmed -> finalize here (single source of truth)
      if (status === "paid" && !data.confirmed_at) {
        if (!effectiveScope?.hasScope) {
          data.confirm_error = data.confirm_error || "missing_tenant_scope_for_finalization";
          data.confirming_at = null;
          return json({ ok: false, error: "missing_tenant_scope_for_finalization" }, 400);
        }
        if (!data.payload || typeof data.payload !== "object") {
          data.payload = {};
        }
        if (!safeStr(data.payload.tenant_id || data.payload.tenantId, 80)) {
          data.payload.tenant_id = effectiveScope.tenant_id;
        }
        if (!safeStr(data.payload.company_id || data.payload.companyId, 80)) {
          data.payload.company_id = effectiveScope.company_id;
        }
        data.paid_at = data.paid_at || new Date().toISOString();
        data.paidAt = data.paidAt || data.paid_at;
        data.payment_status = "paid";
        data.paymentStatus = "paid";
        // Best-effort lock
        try {
          if (data?.confirming_at) {
            const started = Date.parse(data.confirming_at);
            if (Number.isFinite(started) && (Date.now() - started) < 120_000) {
              // Another finalize is running; just persist and return
              await env.BOOKING_KV.put(keyToUse, JSON.stringify(data), { expirationTtl: 60 * 60 * 24 * 30 });
              return json({ ok: true, data, alreadyRunning: true });
            }
          }
        } catch (_) {}

        // Ensure we keep the canonical human id
        data.public_booking_id = data.public_booking_id || safeStr(data?.payload?.__booking_id) || null;

        // Persist confirming lock BEFORE running finalize (reduces races)
        data.confirming_at = new Date().toISOString();
        await env.BOOKING_KV.put(keyToUse, JSON.stringify(data), { expirationTtl: 60 * 60 * 24 * 30 });

        // Run finalize (never throws; returns {ok, updatedStored})
        finalizeAttempted = true;
        const isResumeFinalize = isResumedMolliePaymentRecord(data, id);
        console.log(
          `[PAYMENT_FINALIZE][PAY_STATUS_INVOKE] paymentBooking=${_bookingIntentMask(id)} resume=${isResumeFinalize} mollieStatus=paid hasPayload=${!!data?.payload}`,
        );
        const result = await finalizeBookingFromStored(data, env, request, {
          bypassLock: true,
          paymentBookingId: id,
          tenantScope: effectiveScope,
        });
        data = result?.updatedStored || data;
        console.log(
          `[PAYMENT_FINALIZE][PAY_STATUS_RESULT] paymentBooking=${_bookingIntentMask(id)} resume=${isResumeFinalize} ok=${result?.ok === true} already=${result?.already === true} canonical=${_bookingIntentMask(result?.canonicalBookingId)} dispatch=${result?.dispatchOutcome?.reason || "-"} dispatchAssigned=${result?.dispatchOutcome?.assigned === true}`,
        );
        if (result?.canonicalBookingId && result?.canonicalRec) {
          linkedBooking = {
            booking_id: result.canonicalBookingId,
            key: `booking:${result.canonicalBookingId}`,
            rec: result.canonicalRec,
          };
        } else if (result?.canonicalBookingId) {
          try {
            const loadedCanonical = await loadBookingRecord(env, result.canonicalBookingId);
            if (
              loadedCanonical?.rec &&
              bookingMatchesRequestedTenantScope(loadedCanonical.rec, effectiveScope)
            ) {
              linkedBooking = {
                booking_id: result.canonicalBookingId,
                key: loadedCanonical.key,
                rec: loadedCanonical.rec,
              };
            }
          } catch (_) {
            // Keep existing linkedBooking fallback.
          }
        }
      }
    }

    const paidConfirmedForInvoice =
      String(data?.payment_status || data?.paymentStatus || "").toLowerCase() === "paid" &&
      !!data?.confirmed_at;
    if (paidConfirmedForInvoice) {
      const paymentBookingId = safeStr(id, 160) || id;
      const canonicalResolution = _payStatusResolveCanonicalInvoiceBookingId(data);
      let invoiceRecordInfo = null;
      if (canonicalResolution?.bookingId) {
        try {
          const loadedCanonical = await loadBookingRecord(env, canonicalResolution.bookingId);
          if (
            loadedCanonical?.rec &&
            bookingMatchesRequestedTenantScope(loadedCanonical.rec, effectiveScope)
          ) {
            invoiceRecordInfo = {
              booking_id: canonicalResolution.bookingId,
              key: loadedCanonical.key,
              rec: loadedCanonical.rec,
            };
          }
        } catch (_) {
          // Fall back to existing linked booking behavior below.
        }
      }
      console.log(
        `[INVOICE_LIFECYCLE][CANONICAL_RESOLVE] paymentBookingId=${_bookingIntentMask(paymentBookingId)} canonicalBookingId=${_bookingIntentMask(canonicalResolution?.bookingId)} source=${safeStr(canonicalResolution?.source, 80) || "-"} canonicalFound=${invoiceRecordInfo?.rec ? "true" : "false"}`,
      );

      const invoiceBookingIdFallback =
        safeStr(
          linkedBooking?.booking_id ||
            data?.booking_id ||
            data?.public_booking_id ||
            data?.payload?.__booking_id ||
            data?.payload?.booking_id ||
            data?.payload?.bookingId ||
            id,
          160,
        ) || id;
      if (!invoiceRecordInfo?.rec) {
        console.log(
          `[INVOICE_LIFECYCLE][CANONICAL_FALLBACK] paymentBookingId=${_bookingIntentMask(paymentBookingId)} canonicalBookingId=${_bookingIntentMask(canonicalResolution?.bookingId)} fallbackBookingId=${_bookingIntentMask(invoiceBookingIdFallback)} source=${safeStr(canonicalResolution?.source, 80) || "-"} reason=canonical_not_found_or_scope_mismatch`,
        );
        if (
          linkedBooking?.rec &&
          linkedBooking?.booking_id &&
          bookingMatchesRequestedTenantScope(linkedBooking.rec, effectiveScope)
        ) {
          invoiceRecordInfo = {
            booking_id: linkedBooking.booking_id,
            key: linkedBooking.key,
            rec: linkedBooking.rec,
          };
        } else {
          try {
            const loadedFallback = await loadBookingRecord(env, invoiceBookingIdFallback);
            if (
              loadedFallback?.rec &&
              bookingMatchesRequestedTenantScope(loadedFallback.rec, effectiveScope)
            ) {
              invoiceRecordInfo = {
                booking_id: invoiceBookingIdFallback,
                key: loadedFallback.key,
                rec: loadedFallback.rec,
              };
            }
          } catch (_) {
            // Keep existing behavior: lifecycle remains best-effort in payStatus.
          }
        }
      }
      try {
        if (invoiceRecordInfo?.rec) {
          const invoiceLifecycle = await _maybeGenerateBusinessInvoiceForPaidBooking({
            env,
            bookingId: invoiceRecordInfo.booking_id,
            rec: invoiceRecordInfo.rec,
            source: "mollie_pay_status",
          });
          if (invoiceLifecycle?.mutated) {
            await env.BOOKING_KV.put(invoiceRecordInfo.key, JSON.stringify(invoiceRecordInfo.rec));
            await upsertCompanyBookingsListIndexBestEffort(
              env,
              invoiceRecordInfo.booking_id,
              invoiceRecordInfo.rec,
              normalizeFleetTenantScope(effectiveScope),
            );
            await upsertDashboardBookingsKpiProjectionBestEffort(
              env,
              invoiceRecordInfo.booking_id,
              invoiceRecordInfo.rec,
              normalizeFleetTenantScope(effectiveScope),
            );
          }
          data.invoice_state =
            invoiceRecordInfo.rec?.invoice_state ??
            invoiceRecordInfo.rec?.invoiceState ??
            data.invoice_state;
          data.invoiceState =
            invoiceRecordInfo.rec?.invoiceState ??
            invoiceRecordInfo.rec?.invoice_state ??
            data.invoiceState;
          data.invoice_sent_at =
            invoiceRecordInfo.rec?.invoice_sent_at ??
            invoiceRecordInfo.rec?.invoiceSentAt ??
            data.invoice_sent_at;
          data.invoiceSentAt =
            invoiceRecordInfo.rec?.invoiceSentAt ??
            invoiceRecordInfo.rec?.invoice_sent_at ??
            data.invoiceSentAt;
          data.invoice_number =
            invoiceRecordInfo.rec?.invoice_number ??
            invoiceRecordInfo.rec?.invoiceNumber ??
            data.invoice_number;
          data.invoiceNumber =
            invoiceRecordInfo.rec?.invoiceNumber ??
            invoiceRecordInfo.rec?.invoice_number ??
            data.invoiceNumber;
        }
      } catch (invoiceLifecycleErr) {
        console.log(
          `[INVOICE_LIFECYCLE][ERROR] bookingId=${safeStr(invoiceRecordInfo?.booking_id || invoiceBookingIdFallback)} source=mollie_pay_status reason=${safeStr(invoiceLifecycleErr?.message || invoiceLifecycleErr, 160) || "unknown"}`,
        );
      }
    }

    // Emit one backend compliance payment_update for Mollie/online finalized bookings.
    // This is best-effort only and must never block payment finalization.
    const shouldEmitCompliancePaymentUpdate =
      String(data?.payment_status || data?.paymentStatus || "").toLowerCase() === "paid" &&
      !!data?.confirmed_at &&
      !safeStr(data?.compliance_payment_update_emitted_at);

    if (shouldEmitCompliancePaymentUpdate) {
      compliancePaymentUpdateEmitAttempted = true;
      const complianceBookingId =
        safeStr(
          data?.booking_id ||
            data?.public_booking_id ||
            data?.payload?.__booking_id ||
            data?.payload?.booking_id ||
            data?.payload?.bookingId ||
            id,
        ) || id;
      const compliancePaymentSource =
        pickMeaningfulCompliancePaymentValue(
          data?.payment_source,
          data?.paymentSource,
          data?.payload?.payment_source,
          data?.payload?.paymentSource,
        ) || "mollie";
      const compliancePaymentProvider =
        pickMeaningfulCompliancePaymentValue(
          data?.payment_provider,
          data?.paymentProvider,
          data?.payload?.payment_provider,
          data?.payload?.paymentProvider,
        ) || "mollie";
      const compliancePaymentPayload = {
        payment_status: data?.payment_status || data?.paymentStatus || "paid",
        payment_source: compliancePaymentSource,
        payment_provider: compliancePaymentProvider,
        payment_id:
          safeStr(data?.payment_id || data?.paymentId || data?.mollie?.payment_id || data?.mollie?.id) || null,
        paid_at: safeStr(data?.paid_at || data?.paidAt) || null,
        currency: safeStr(data?.currency || data?.payload?.currency || "EUR") || "EUR",
        tenant_id: effectiveScope?.tenant_id || null,
        company_id: effectiveScope?.company_id || null,
      };
      compliancePaymentPayload.payment_method = resolveCompliancePaymentMethodToken(
        data,
        compliancePaymentPayload,
        {
          provider: compliancePaymentProvider,
          source: compliancePaymentSource,
        },
      );
      if (effectiveScope?.hasScope) {
        const complianceEvent = buildBookingPaymentUpdateComplianceEvent(
          data,
          complianceBookingId,
          compliancePaymentPayload,
        );
        if (complianceEvent) {
          const emitted = await emitComplianceEventBestEffort(env, complianceEvent, {
            timeoutMs: 1500,
            logLabel: "planned_mollie_payment_update",
          });
          if (emitted?.ok) {
            data.compliance_payment_update_emitted_at = new Date().toISOString();
          }
        } else {
          console.log("[COMPLIANCE_EMIT][planned_mollie_payment_update] skipped reason=builder_null");
        }
      } else {
        console.log("[COMPLIANCE_EMIT][planned_mollie_payment_update] skipped reason=missing_tenant_scope");
      }
    }
  } catch (e) {
    // Don't fail /pay/status; persist error for diagnostics
    data.mollie = data.mollie || {};
    data.mollie.status_error = String(e?.message || e);
    // If an error happened during finalize attempt, make sure we do not leave a permanent lock
    try {
      if (finalizeAttempted) {
        data.confirm_error = data.confirm_error || "Finalize failed inside /pay/status";
        data.confirming_at = null;
      }
      if (compliancePaymentUpdateEmitAttempted) {
        data.confirm_error =
          data.confirm_error || "Compliance payment_update emit failed inside /pay/status";
      }
    } catch (_) {}
  } finally {
    // Always persist the latest state (including lock recovery)
    await env.BOOKING_KV.put(keyToUse, JSON.stringify(data), { expirationTtl: 60 * 60 * 24 * 30 });
  }

  if (String(data?.payment_status || data?.paymentStatus || "").toLowerCase() === "paid") {
    const syncBookingId =
      safeStr(
        linkedBooking?.booking_id ||
          data?.booking_id ||
          data?.public_booking_id ||
          data?.payload?.__booking_id ||
          data?.payload?.booking_id ||
          data?.payload?.bookingId ||
          id,
      ) || id;
    const syncRecordBase =
      linkedBooking?.rec && typeof linkedBooking.rec === "object"
        ? linkedBooking.rec
        : {};
    const syncRecord = {
      ...syncRecordBase,
      payment_status: data?.payment_status ?? data?.paymentStatus,
      paymentStatus: data?.paymentStatus ?? data?.payment_status,
      paid_at: data?.paid_at ?? data?.paidAt,
      paidAt: data?.paidAt ?? data?.paid_at,
      payment_method: data?.payment_method ?? data?.paymentMethod,
      paymentMethod: data?.paymentMethod ?? data?.payment_method,
      payment_source: data?.payment_source ?? data?.paymentSource,
      paymentSource: data?.paymentSource ?? data?.payment_source,
      currency: data?.currency ?? syncRecordBase?.currency ?? syncRecordBase?.booking?.currency,
      payment_amount:
        data?.payment_amount ?? data?.paymentAmount ?? syncRecordBase?.payment_amount ?? syncRecordBase?.paymentAmount,
      paymentAmount:
        data?.paymentAmount ?? data?.payment_amount ?? syncRecordBase?.paymentAmount ?? syncRecordBase?.payment_amount,
      tenant_id:
        syncRecordBase?.tenant_id ??
        syncRecordBase?.tenantId ??
        data?.payload?.tenant_id ??
        data?.payload?.tenantId ??
        effectiveScope?.tenant_id,
      company_id:
        syncRecordBase?.company_id ??
        syncRecordBase?.companyId ??
        data?.payload?.company_id ??
        data?.payload?.companyId ??
        effectiveScope?.company_id,
    };
    await syncScopedTrackingTripKpiBestEffort({
      env,
      bookingId: syncBookingId,
      rec: syncRecord,
      tenantScope: effectiveScope,
      source: "mollie_pay_status_paid",
    });
  }

  return json({ ok: true, data });
}

async function mollieFetchPaymentJson(paymentId, env, rideCredentials = null, options = {}) {
  let creds = rideCredentials;
  if (!creds?.ok) {
    if (options.bootstrapCentralDemo) {
      const base = getMollieConfig(env);
      if (!base.ok) throw new Error(base.error);
      creds = {
        ok: true,
        apiKey: base.apiKey,
        mode: base.mode,
        keyKind: base.keyKind,
        payment_credential_source: "fluxidi_central_demo",
      };
    } else if (options.tenantScope) {
      creds = await resolveRideMollieCredentials(env, options.tenantScope, options);
      if (!creds.ok) throw new Error(creds.error || "ride_mollie_credentials_required");
    } else {
      throw new Error("ride_mollie_credentials_required");
    }
  }
  const url = `https://api.mollie.com/v2/payments/${encodeURIComponent(paymentId)}`;
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${creds.apiKey}`,
      "Content-Type": "application/json",
    },
  });
  const txt = await res.text();
  let j = null;
  try { j = JSON.parse(txt); } catch (_) {}
  if (!res.ok) throw new Error(`Mollie get payment failed (${res.status}): ${txt?.slice(0, 300)}`);
  return j;
}

async function finalizeBookingFromStored(stored, env, request, opts = {}) {
  // Idempotent: if already confirmed, do nothing
  if (stored?.confirmed_at) {
    stored.confirming_at = null;
    return { ok: true, updatedStored: stored, already: true };
  }

  // Stale lock recovery (important!)
  try {
    if (stored?.confirming_at) {
      const started = Date.parse(stored.confirming_at);
      if (Number.isFinite(started) && (Date.now() - started) > 180_000) {
        stored.confirming_at = null;
        stored.confirm_error = (stored.confirm_error || "") + (stored.confirm_error ? " | " : "") + "Recovered stale confirming_at lock (finalizeBookingFromStored)";
      }
    }
  } catch (_) {}

  // If another finalize started very recently, skip (unless bypassLock=true)
  if (!opts?.bypassLock) {
    try {
      if (stored?.confirming_at) {
        const started = Date.parse(stored.confirming_at);
        if (Number.isFinite(started) && (Date.now() - started) < 120_000) {
          return { ok: true, updatedStored: stored, alreadyRunning: true };
        }
      }
    } catch (_) {}
  }

  if (!stored?.payload) {
    stored.confirm_error = "Cannot finalize: missing stored.payload";
    stored.confirming_at = null;
    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }

  const paymentBookingId = safeStr(
    opts?.paymentBookingId || stored?.bookingId || stored?.booking_id,
    160,
  );
  if (isResumedMolliePaymentRecord(stored, paymentBookingId)) {
    return finalizeResumePaidPaymentToCanonical(stored, env, request, {
      paymentBookingId,
      tenantScope: opts?.tenantScope || _tenantScopeFromStoredPaymentRecord(stored),
      bypassLock: opts?.bypassLock,
    });
  }

  const nowIso = new Date().toISOString();
  stored.confirming_at = nowIso;

  // Initialize debug container early so even early crashes are visible
  stored.finalize_debug = stored.finalize_debug || {};
  stored.finalize_debug.attempted_at = nowIso;
  stored.finalize_debug.stage = "start";
  stored.finalize_debug.error = null;

  try {
    // Ensure payload is treated as paid so it won't create a NEW Mollie payment.
    stored.payload.__mollie_paid = true;
    const finalPaymentFields = normalizedPaymentFields({
      status: stored.payment_status || stored.paymentStatus || stored?.mollie?.status,
      paymentId: stored.payment_id || stored.paymentId || stored?.mollie?.payment_id || stored?.mollie?.id,
      paidAt: stored.paid_at || stored.paidAt,
    });
    Object.assign(stored.payload, finalPaymentFields);
    Object.assign(stored, finalPaymentFields);
    console.log("[PAYMENT_STATUS][FINALIZE]", JSON.stringify({
      payment_id: finalPaymentFields.payment_id || null,
      payment_status: finalPaymentFields.payment_status || null,
      paid_at: finalPaymentFields.paid_at || null,
      booking_id: stored.booking_id || stored.public_booking_id || stored.payload.booking_id || stored.payload.bookingId || null,
    }));

    // Re-use the original human booking id if present (canonical ID everywhere)
    if (stored.public_booking_id) stored.payload.__booking_id = stored.public_booking_id;
    if (stored.booking_id) stored.payload.__booking_id = stored.booking_id;
    if (stored.payload.booking_id) stored.payload.__booking_id = stored.payload.booking_id;
    if (stored.payload.bookingId) stored.payload.__booking_id = stored.payload.bookingId;
    const storedPublicBookingReference = safeStr(
      stored.public_booking_reference ||
        stored.publicBookingReference ||
        stored.booking_reference ||
        stored.bookingReference ||
        stored.payload?.__public_booking_reference ||
        stored.payload?.public_booking_reference ||
        stored.payload?.publicBookingReference,
    );
    if (storedPublicBookingReference) {
      stored.payload.__public_booking_reference = storedPublicBookingReference;
      attachPublicBookingReferenceAliases(stored.payload, storedPublicBookingReference);
    }

    // Use the current request origin (prevents "https://internal" links in emails)
    const origin = (() => {
      try { return request ? (new URL(request.url)).origin : "https://fluxidi-booking-api.fluxidi.workers.dev"; }
      catch { return "https://fluxidi-booking-api.fluxidi.workers.dev"; }
    })();

    const fakeReq = new Request(origin + "/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(stored.payload),
    });

    stored.finalize_debug.stage = "handleBooking";
    const bookingResult = await handleBooking(stored.payload, env, fakeReq);

    // If the booking pipeline still thinks payment is required, do NOT confirm.
    if (!bookingResult?.ok || bookingResult?.requiresPayment) {
      stored.confirm_error = bookingResult?.error || JSON.stringify(bookingResult || {});
      stored.finalize_debug.stage = "handleBooking_failed";
      stored.finalize_debug.error = stored.confirm_error;
      stored.confirming_at = null;
      return { ok: false, updatedStored: stored, bookingResult };
    }

    // Mark confirmed (even if some non-critical outputs had warnings)
    stored.confirmed_at = new Date().toISOString();
    stored.confirming_at = null;

    // Persist useful ids (best-effort)
    if (bookingResult?.booking_id) stored.booking_id = bookingResult.booking_id;
    if (bookingResult?.calendar_event_id) stored.calendar_event_id = bookingResult.calendar_event_id;

    // Store debug summary for /pay/status troubleshooting
    stored.finalize_debug = {
      at: new Date().toISOString(),
      stage: "done",
      booking_id: bookingResult?.booking_id || null,
      calendar_event_id: bookingResult?.calendar_event_id || null,
      email: bookingResult?.email || null,
      invoice: bookingResult?.invoice || null,
      invoice_number: bookingResult?.invoice_number || bookingResult?.invoiceNumber || null,
      warnings: bookingResult?.warnings || null,
      error: null
    };

    return { ok: true, updatedStored: stored, bookingResult };

  } catch (e) {
    // NEVER throw here — we must not leave the booking in a permanent lock.
    stored.confirm_error = String(e?.message || e);
    stored.finalize_debug = stored.finalize_debug || {};
    stored.finalize_debug.stage = stored.finalize_debug.stage || "unknown";
    stored.finalize_debug.error = stored.confirm_error;

    // Clear lock so the next /pay/status poll can retry
    stored.confirming_at = null;

    return { ok: false, updatedStored: stored, error: stored.confirm_error };
  }
}
